/* factions q10 (135 mục) — R6 sửa lỗi */
window.__LIBQ=window.__LIBQ||{};window.__LIBQ["pham-nhan-tu-tien"]=window.__LIBQ["pham-nhan-tu-tien"]||{};window.__LIBQ["pham-nhan-tu-tien"]["q10"]=window.__LIBQ["pham-nhan-tu-tien"]["q10"]||{};window.__LIBQ["pham-nhan-tu-tien"]["q10"]["factions"]={"updatedAt":"2026-07-26","count":135,"factions":[{"id":"minh-toc","name":"Minh tộc","cn":"","type":"chung-toc","typeLabel":"Dị tộc","diaBan":"Có thành thị trên Phong Nguyên Đại Lục","nhanVatChinh":["Lôi Vân Tử"],"blurb":"Một dị tộc có thành thị trên Phong Nguyên Đại Lục, nơi Hàn Lập từng bí mật tiến vào.","detail":"Lôi Vân Tử là Trận Pháp tông sư rất có danh tiếng trong Minh tộc. Tại một thành nhỏ của tộc này, hắn nhận ra Hàn Lập là người ngoại tộc và giao chiến với Hàn Lập hơn một tháng.","caoThuManhNhat":"Lôi Vân Tử được xác nhận là tu sĩ Luyện Hư trung kỳ trong chương.","thanhVien":[{"ten":"Lôi Vân Tử","chucVu":"Trận Pháp tông sư","tuChuong":"@c1748","trangThai":"dang-thuoc"}],"tabs":{"tienTrinh":[{"chuong":"@c1748","loai":"nhắc tới","importance":"bridge","giaiDoan":"Hé lộ thành thị và cao thủ","text":"Minh tộc được nhắc tới qua thành thị nơi Hàn Lập gặp Lôi Vân Tử và danh tiếng Trận Pháp tông sư của người này.","anchor":"vị Lôi Vân Tử này lại là một Trận Pháp tông sư rất có danh tiếng trong Minh tộc","trangThaiMoc":"Đang tồn tại"}]},"capNhatToi":"@c1748","nguon":["@c1748"]},{"id":"nhan-toc-va-yeu-toc","name":"Nhân tộc và Yêu tộc","cn":"","aliases":[],"type":"lien-minh","typeLabel":"Liên minh chủng tộc","diaBan":"Tam cảnh Thất địa và Thiên Uyên Thành","nhanVatChinh":[],"blurb":"Liên minh phòng thủ của Nhân tộc và Yêu tộc tại Thiên Uyên Thành.","detail":"Hai tộc phối hợp chống lại cuộc vây công của liên quân dị tộc, chịu thương vong nặng nhưng giữ được Thiên Uyên Thành cho tới khi đối phương bất ngờ rút quân.","tonChi":"Phối hợp bảo vệ địa vực hai tộc và Thiên Uyên Thành.","quanHe":"Đối địch với Liên quân dị tộc trong cuộc chiến Thiên Uyên Thành.","trangThai":"Giữ được Thiên Uyên Thành","capNhatToi":"@c1749","tabs":{"tienTrinh":[{"chuong":"@c1749","loai":"khai chiến","importance":"normal","giaiDoan":"Phòng thủ Thiên Uyên Thành","text":"Nhân tộc và Yêu tộc phối hợp phòng thủ Thiên Uyên Thành trước liên quân dị tộc và cùng chịu thương vong nặng.","anchor":"nhờ có Nhân tộc và Yêu tộc phối hợp phòng thủ, nên hai bên đều có thảm thương trầm trọng","trangThaiMoc":"Giữ được thành"}]},"nguon":["@c1749"]},{"id":"lien-quan-di-toc","name":"Liên quân dị tộc","cn":"","aliases":[],"type":"lien-minh","typeLabel":"Liên minh chủng tộc","diaBan":"Chiến trường Thiên Uyên Thành","nhanVatChinh":[],"blurb":"Liên quân gồm nhiều dị tộc từng tiến công Thiên Uyên Thành.","detail":"Liên quân giao chiến dữ dội với lực lượng Nhân–Yêu nhưng bất ngờ rút lui khi chiến sự đang kịch liệt. Nguyên nhân rút quân chưa được xác nhận, chỉ có các giả thuyết về biến cố hậu phương hoặc cuộc tranh đoạt Huyền Thiên chi bảo.","nguonGoc":"Nhiều dị tộc xung quanh liên thủ.","quanHe":"Đối địch với liên minh Nhân tộc và Yêu tộc.","trangThai":"Đã rút khỏi chiến trường Thiên Uyên Thành","capNhatToi":"@c1749","tabs":{"tienTrinh":[{"chuong":"@c1749","loai":"khai chiến","importance":"normal","giaiDoan":"Rút khỏi Thiên Uyên","text":"Liên quân dị tộc bất ngờ rút khỏi chiến trường giữa lúc cuộc chiến tại Thiên Uyên Thành còn đang kịch liệt.","anchor":"đại quân dị tộc bỗng nhiên bất ngờ rút quân","trangThaiMoc":"Đã rút quân"}]},"nguon":["@c1749"]},{"id":"tiep-dan-thai","name":"Tiếp Dẫn Thai","cn":"","aliases":[],"type":"Cơ chế Tiên giới","typeLabel":"Cơ chế tiếp dẫn và kiểm soát","diaBan":"Tiên giới","nhanVatChinh":[],"blurb":"Nơi hoặc cơ chế kiểm soát người từ hạ giới độ kiếp phi thăng lên Tiên giới.","detail":"Theo các tiên nhân, người tu luyện Luyện thần thuật ở hạ giới dù không bị can thiệp ngay cũng khó che giấu cấm thuật trước người của Tiếp Dẫn Thai khi độ kiếp phi thăng.","tonChi":"Kiểm soát người từ hạ giới phi thăng lên Tiên giới","trangThai":"Đang hoạt động","capNhatToi":"@c1754","tabs":{"tienTrinh":[{"chuong":"@c1754","loai":"nhắc tới","importance":"bridge","giaiDoan":"Kiểm soát người phi thăng","text":"Các tiên nhân cho rằng người hạ giới tu luyện cấm thuật sẽ bị người của Tiếp Dẫn Thai phát hiện khi độ kiếp phi thăng.","anchor":"khi độ kiếp phi thăng cũng không có thể giấu diếm được người của Tiếp Dẫn Thai","trangThaiMoc":"Đang hoạt động"}]},"nguon":["@c1754"]},{"id":"cung-dien-trang-noan","name":"Cung điện trắng noãn","cn":"","aliases":[],"type":"Cơ quan Tiên giới","typeLabel":"Cơ quan giám sát","diaBan":"Một không gian tối tăm thuộc Tiên giới","nhanVatChinh":["Huyền Minh","Nhân ảnh trong bạch quang"],"blurb":"Cung điện lơ lửng trong một không gian tối tăm, nơi nhiều tiên nhân tụ họp và bàn luận về Luyện thần thuật.","detail":"Bên trong cung điện có các đài cao vài chục trượng bao quanh một đóa kỳ hoa đen trắng khổng lồ. Những tiên nhân bị linh quang che phủ ngồi trên đài cao, phía sau mỗi người có hàng chục đệ tử đứng hầu.","quyMo":"Nhiều tiên nhân, mỗi người có hàng chục đệ tử phục vụ","lanhDaoHienThoi":"Không rõ","thanhVien":[{"ten":"Huyền Minh","chucVu":"Người đảm nhiệm chức giám sát","tuChuong":"@c1754","trangThai":"Đang hoạt động"},{"ten":"Nhân ảnh trong bạch quang","chucVu":"Tiên nhân","tuChuong":"@c1754","trangThai":"Đang hoạt động"}],"trangThai":"Đang hoạt động","capNhatToi":"@c1754","tabs":{"tienTrinh":[{"chuong":"@c1754","loai":"nhắc tới","importance":"normal","giaiDoan":"Hội nghị về cấm thuật","text":"Các tiên nhân trong cung điện bàn luận việc một người tại tiểu linh giới tu thành tầng thứ nhất của Luyện thần thuật và thống nhất không can thiệp.","anchor":"trong một cung điện trắng noãn đang lơ lửng trong không trung, có mấy bóng người mơ hồ chìm trong ánh sáng mênh mông","trangThaiMoc":"Đang hoạt động"}]},"nguon":["@c1754"]},{"id":"ngan-toc","name":"Ngân Tộc","cn":"","type":"chung-toc","typeLabel":"Chủng tộc","diaBan":"Khu vực xa địa phận Nhân Tộc","nhanVatChinh":["Người canh giữ Ngân Tộc"],"blurb":"Chủng tộc sở hữu một động quật truyền tống bí mật được bảo vệ bằng hơn mười giáp sĩ khôi lỗi.","detail":"Cơ sở truyền tống của Ngân Tộc bị bạch y nữ tử và hắc bào đại hán xâm nhập. Các khôi lỗi bị phá hủy và người canh giữ bị sát hại.","quyMo":"Có truyền tống trận bí mật, người canh giữ và lực lượng giáp sĩ khôi lỗi.","trangThai":"Động quật truyền tống bị xâm nhập","thanhVien":[{"ten":"Người canh giữ Ngân Tộc","chucVu":"Người canh giữ truyền tống trận","tuChuong":"@c1763","trangThai":"Đã tử vong"}],"tabs":{"tienTrinh":[{"chuong":"@c1763","loai":"khai chiến","importance":"normal","giaiDoan":"Cơ sở truyền tống bị xâm nhập","text":"Hai kẻ lạ sử dụng truyền tống trận của Ngân Tộc, phá hủy lực lượng khôi lỗi và sát hại người canh giữ.","anchor":"Các người là ai. Vì sao lại sử dụng truyền tống trận của Ngân Tộc chúng ta?","trangThaiMoc":"Động quật truyền tống bị xâm nhập"}]},"capNhatToi":"@c1763","nguon":["@c1763"]},{"id":"hua-gia","name":"Hứa gia","cn":"","type":"gia-toc","typeLabel":"Gia tộc tu tiên","diaBan":"Thiên Nguyên cảnh","nhanVatChinh":["Hứa Giao","Hứa Thiên Vũ","Băng Phách tiên tử","Huyết Linh","Lão giả Luyện Hư Hứa gia"],"blurb":"Gia tộc tu tiên tại Thiên Nguyên cảnh, được xác nhận là nhánh hậu nhân chính thống và giữ truyền thừa trực tiếp của Băng Phách tiên tử.","detail":"Hậu nhân Băng Phách tiên tử đã phân thành hơn mười nhánh, nhưng Hứa gia được Hứa Thiên Vũ xác nhận là nhánh có huyết mạch và truyền thừa trực tiếp nhất. Gia tộc có danh tiếng nhất định dù không thuộc hàng Chân Linh thế gia; tộc trưởng hiện thời là phụ thân của Hứa Thiên Vũ và trong tộc còn có vài vị thúc tổ.","nguonGoc":"Dòng hậu nhân và truyền thừa trực tiếp của Băng Phách tiên tử.","lanhDaoHienThoi":"Hứa Giao","quyMo":"Một gia tộc có danh tiếng nhất định tại Thiên Nguyên cảnh.","quanHe":"Là một trong hơn mười nhánh hậu nhân của Băng Phách tiên tử và được xác nhận là nhánh chính thống nhất.","trangThai":"Đang di chuyển tới Thiên Nguyên Thành","thanhVien":[{"ten":"Hứa Giao","chucVu":"Tộc trưởng","tuChuong":"@c1765","trangThai":"đương nhiệm"},{"ten":"Hứa Thiên Vũ","chucVu":"Hậu nhân trực hệ","tuChuong":"@c1765","trangThai":"đang thuộc gia tộc"},{"ten":"Huyết Linh","chucVu":"Người quyết định việc di chuyển","tuChuong":"@c1873","trangThai":"Đang dẫn dắt gia tộc"},{"ten":"Lão giả Luyện Hư Hứa gia","chucVu":"Tu sĩ Luyện Hư","tuChuong":"@c1873","trangThai":"Đang theo gia tộc di chuyển"}],"lanhDaoMoc":[{"ten":"Hứa Giao","tuChuong":"@c1765","denChuong":""}],"tabs":{"tienTrinh":[{"chuong":"@c1765","loai":"nhắc tới","importance":"normal","giaiDoan":"Xác nhận dòng chính thống","text":"Hứa gia được xác nhận là nhánh hậu nhân chính thống nhất và giữ truyền thừa trực tiếp từ Băng Phách tiên tử.","anchor":"chắc chắn Hứa gia chúng ta đích thực là huyết mạch hậu nhân chính thống nhất","trangThaiMoc":"Đang do phụ thân Hứa Thiên Vũ lãnh đạo"},{"chuong":"@c1873","loai":"mất địa bàn","importance":"normal","giaiDoan":"Bỏ gia nghiệp lánh nạn","text":"Hứa gia bỏ lại toàn bộ gia nghiệp, dùng hàng trăm chiến thuyền chuyển hàng nghìn người tới Thiên Nguyên Thành để nương tựa.","anchor":"gia nghiệp to lớn như thế của Hứa gia, dĩ nhiên cũng vì lần Ma Kiếp này mà bỏ lại","trangThaiMoc":"Rời địa bàn cũ"}]},"capNhatToi":"@c1765","nguon":["@c1765","@c1873"]},{"id":"thanh-dao","name":"Thánh đảo","cn":"","type":"to-chuc","typeLabel":"Tổ chức","diaBan":"Không rõ","nhanVatChinh":["Mạc Giản Ly","Vũ Khiếu Thiên","Thiên Thiền đại sư","Thôi Ông","Ngao Khiếu"],"blurb":"Thánh đảo là thế lực đại diện Nhân tộc và Yêu tộc trong việc ứng phó ma kiếp, đảm nhiệm truyền tin, hoạch định chiến lược và thiết lập minh ước. Thế lực này từng cảnh báo Ma giới sắp xâm lấn, tham gia bố trí chiến trường, thúc đẩy đình chiến với các dị tộc và cung cấp bảo vật phục vụ nhiệm vụ liên quan đến đại cục.","detail":"Trước khi ma kiếp bùng nổ, Thánh đảo đã phát mật tin cảnh báo về cuộc xâm lấn sắp tới của Ma giới, trở thành một trong những căn cứ để Trưởng lão hội Thiên Uyên thành nhận định tai kiếp khó tránh khỏi @c1766. Sau đó, Thánh đảo cùng Mạc Giản Ly chọn Thiên Linh Thành làm mồi nhử nhằm tiêu hao đại quân Ma tộc @c1793. Với tư cách đại diện Nhân Yêu lưỡng tộc, Thánh đảo còn công bố đình chiến với các dị tộc đối địch và thiết lập một minh ước kéo dài @c1837. Trong kỳ ma kiếp bất thường, Cốc trưởng lão tin rằng Thánh đảo đã chuẩn bị đối sách @c1887. Thánh đảo cũng giao Ngân Tiêu Lôi Võng cho Vũ Khiếu Thiên mang rời đảo để thực hiện nhiệm vụ bắt Hoàng Lương Thạch Li @c1940, đồng thời là nơi truyền ra tin ba đại thủy tổ có thể cùng phủ xuống Linh Giới @c2005.","trangThai":"Đang hoạt động","nguon":["@c1766","@c1793","@c1837","@c1887","@c1940","@c2005"],"tabs":{"tienTrinh":[{"chuong":"@c1766","loai":"nhắc tới","importance":"normal","giaiDoan":"Cảnh báo ma kiếp","text":"Thánh đảo phát mật tin cảnh báo trước về cuộc xâm lấn sắp tới của Ma giới.","anchor":"mật tin từ trong Thánh đảo truyền ra báo động trước"},{"chuong":"@c1793","loai":"liên minh","importance":"normal","giaiDoan":"Bố trí chiến trường tiêu hao","text":"Thánh Đảo cùng Mạc Giản Ly chọn Thiên Linh Thành làm mồi nhử để tiêu hao đại quân Ma tộc khi Ma kiếp bùng nổ.","anchor":"Mạc Giản Ly tiền bối cùng với người của Thánh Đảo cố ý làm cho Thiên Linh Thành trở thành một mồi câu hấp dẫn đám Ma tộc"},{"chuong":"@c1837","loai":"liên minh","importance":"major","giaiDoan":"Công bố đình chiến","text":"Thánh Đảo đại diện Nhân Yêu lưỡng tộc công bố đình chiến với các dị tộc đối địch và thiết lập minh ước kéo dài một nghìn năm.","anchor":"Trong vòng ngàn năm, các tộc không được khai chiến lẫn nhau, ngược lại tuân thủ ước định đồng minh công thủ.","trangThaiMoc":"Thiết lập liên minh công thủ"},{"chuong":"@c1887","loai":"nhắc tới","importance":"normal","giaiDoan":"Được nhắc tại hội nghị trưởng lão Thiên Uyên Thành","text":"Cốc trưởng lão tin Thánh Đảo đã chuẩn bị đối sách cho ma kiếp bất thường lần này.","anchor":"bên phía Thánh Đảo ắt hẳn cũng đã có dự phòng"},{"chuong":"@c1940","loai":"nhắc tới","importance":"normal","giaiDoan":"Giao Linh bảo làm nhiệm vụ","text":"Thánh Đảo giao Ngân Tiêu Lôi Võng cho Vũ Khiếu Thiên mang rời đảo để phục vụ nhiệm vụ bắt Hoàng Lương Thạch Linh.","anchor":"nếu không phải việc lần này trọng đại, thánh đảo sẽ không dễ dàng để lão phu mang lưới rời đi","trangThaiMoc":"Cử người bắt Hoàng Lương Thạch Linh"},{"chuong":"@c2005","loai":"nhắc tới","importance":"normal","giaiDoan":"Truyền tin về thủy tổ","text":"Thánh Đảo là nơi truyền ra tin ba đại thủy tổ có thể cùng phủ xuống Linh Giới.","anchor":"Tin tức này lão phu lấy được từ Thánh Đảo","trangThaiMoc":"Đang điều phối tin tức"}]},"thanhVien":[{"ten":"Vũ Khiếu Thiên","chucVu":"Người thi hành nhiệm vụ","tuChuong":"@c1940","trangThai":"đang hoạt động"},{"ten":"Thiên Thiền đại sư","chucVu":"Người thi hành nhiệm vụ","tuChuong":"@c1940","trangThai":"đang hoạt động"},{"ten":"Thôi Ông","chucVu":"Sứ giả","tuChuong":"@c2005","trangThai":"Được phái tới Thiên Uyên Thành"}],"dacDiem":"Là đầu mối đại diện và điều phối của Nhân Yêu lưỡng tộc, nổi bật ở hoạt động tình báo, ngoại giao và bố trí đối sách trước ma kiếp.","congNang":["Thu thập và phát mật tin cảnh báo trước về nguy cơ Ma giới xâm lấn Linh giới @c1766.","Tham gia hoạch định chiến lược chống Ma tộc, cùng Mạc Giản Ly chọn Thiên Linh Thành làm mồi nhử để tiêu hao đại quân đối phương @c1793.","Đại diện Nhân Yêu lưỡng tộc tiến hành ngoại giao, công bố đình chiến với các dị tộc đối địch và thiết lập minh ước kéo dài @c1837.","Điều phối bảo vật phục vụ nhiệm vụ, từng giao Ngân Tiêu Lôi Võng cho Vũ Khiếu Thiên để bắt Hoàng Lương Thạch Li @c1940.","Truyền tin tình báo trọng yếu về khả năng ba đại thủy tổ cùng phủ xuống Linh Giới @c2005."]},{"id":"ma-toc","name":"Ma tộc","cn":"","aliases":["Cổ Ma"],"type":"chung-toc","typeLabel":"Chủng tộc","diaBan":"Ma giới","nhanVatChinh":["Tàng ma tôn","Lãnh Nhận","Vũ Tiên tử","Hỏa giáp cự nhân","Hắc giáp nữ tử","Nguyên Sát","Huyết bào thiếu niên","Huyết Quang Thánh tổ","Lão Quý","Thanh niên Ma tộc mặc chiến giáp đen"],"blurb":"Ma tộc là thế lực tại Ma giới phát động cuộc xâm lấn quy mô lớn vào Linh giới. Trong quá trình giao chiến, họ liên tục công thành, triển khai nhiều lực lượng và phương thức tấn công, từng đánh hạ Thiên Linh thành và chiếm giữ mắt trận số một.","detail":"Cuộc xâm lấn do Cổ Ma tại Ma giới chuẩn bị, đi cùng sự lan rộng của ma chướng và nguy cơ Chân Ma tộc phá giới. Sau khi tiến vào Linh giới, Ma tộc giao chiến với tu sĩ Nhân tộc, sử dụng Già Luân chiến ma mở đường khi công thành, điều động biển ma thú đánh vào tuyến phòng thủ và phân chia lực lượng để đối phó Thiên hà tứ bảo. Ma tộc từng đánh hạ Thiên Linh thành, phá hủy phần lớn thành trì rồi xây dựng cơ sở đóng giữ lâu dài; về sau còn chiếm được mắt trận số một, dù hai nhóm tiến tới mắt trận số hai lần lượt mất liên lạc.","tonChi":"Xâm lấn Linh giới và cướp đoạt tài nguyên tu luyện","trangThai":"Chiếm mắt trận số một, chịu tổn thất tại mắt trận số hai","capNhatToi":"@c1766","nguon":["@c1766","@c1876","@c1912","@c1917","@c1964","@c1994","@c2169"],"tabs":{"tienTrinh":[{"chuong":"@c1766","loai":"khai chiến","importance":"major","giaiDoan":"Chuẩn bị xâm lấn Linh giới","text":"Cổ Ma tại Ma giới đang chuẩn bị một cuộc chiến quy mô lớn để xâm lấn Linh giới.","anchor":"Cổ Ma trong Ma giới đang tiến hành chuẩn bị một cuộc chiến quy mô lớn"},{"chuong":"@c1876","loai":"khai chiến","importance":"normal","giaiDoan":"Ma chướng lan rộng","trangThaiMoc":"Dự kiến phá giới sau ba, bốn tháng","text":"Ma chướng ngày càng lan rộng và Chân Ma tộc được dự đoán sẽ sớm phá giới.","anchor":"Hiện tại Ma chướng càng lúc càng lan rộng, khoảng chừng ba bốn tháng sau thì có lẽ Chân Ma tộc sẽ phá giới đến nơi"},{"chuong":"@c1912","loai":"khai chiến","importance":"normal","giaiDoan":"Bốn Ma tôn bị kiềm chế","text":"Bốn Ma tộc tôn giả lần lượt bị các tu sĩ Nhân tộc nghênh chiến, trong khi Tàng ma tôn chưa thể chiếm ưu thế.","anchor":"Ma tộc lại có chút phiền muộn.","trangThaiMoc":"Đang giao chiến"},{"chuong":"@c1917","loai":"khai chiến","importance":"normal","giaiDoan":"Chiếm ưu thế cục bộ","text":"Ma tộc tiếp tục công thành, dùng Già Luân chiến ma mở đường và giành ưu thế trong cuộc giao phong của các cường giả đỉnh giai.","anchor":"Mấy chục ma vật cầm đầu thần thông vượt xa đám tồn tại cùng cấp"},{"chuong":"@c1964","loai":"mở rộng/mất địa bàn","importance":"major","giaiDoan":"Chiếm Thiên Linh thành","trangThaiMoc":"Chiếm giữ và cải tạo thành cứ điểm lâu dài","text":"Ma tộc đánh hạ Thiên Linh thành, phá hủy phần lớn thành trì rồi xây dựng cơ sở để đóng giữ lâu dài.","anchor":"Thiên Linh thành, một trong ba đại hoàng thành của Nhân tộc rốt cục dưới vô biên vô hạn đại quân Ma tộc bao phủ mà thất thủ"},{"chuong":"@c1994","loai":"khai chiến","importance":"normal","giaiDoan":"Tổng công thành","text":"Ma tộc dùng biển ma thú tấn công tuyến phòng thủ và điều bốn luồng lực lượng đối phó Thiên hà tứ bảo.","anchor":"một đoàn hắc vân, một cỗ hoàng sắc quái phong cùng với lưỡng đạo huyết hồng chợt loé lên liền từ phía sau đàn thú lướt bay lên","trangThaiMoc":"Đang công thành"},{"chuong":"@c2169","loai":"khai chiến","importance":"normal","giaiDoan":"Công kích hệ thống mắt trận","text":"Ma tộc chiếm mắt trận số một nhưng hai nhóm tiến đến mắt trận số hai lần lượt mất liên lạc.","anchor":"Tại sao hai nhóm lần lượt đi qua đấy đều không có lấy một tin tức nào được truyền về?","trangThaiMoc":"Chiếm mắt trận số một"}]},"uyLuc":"Chiến quả lớn nhất đã ghi nhận là đánh hạ Thiên Linh thành, phá hủy phần lớn thành trì và thiết lập cơ sở đóng giữ lâu dài. @c1964","dacDiem":"Là thế lực xâm lấn từ Ma giới, có khả năng tổ chức chiến tranh quy mô lớn và phối hợp nhiều phương thức tác chiến như công thành, sử dụng chiến ma, biển ma thú và chia quân đánh các mục tiêu phòng thủ.","congNang":["Chuẩn bị và phát động chiến tranh quy mô lớn nhằm xâm lấn Linh giới. @c1766","Mở rộng ma chướng và tiến hành phá giới để tiến vào Linh giới. @c1876","Điều động các Ma tộc tôn giả tham chiến với tu sĩ Nhân tộc. @c1912","Dùng Già Luân chiến ma mở đường trong hoạt động công thành. @c1917","Đánh hạ, phá hủy thành trì và xây dựng cơ sở để đóng giữ lâu dài. @c1964","Điều khiển biển ma thú tấn công tuyến phòng thủ. @c1994","Chia nhiều luồng lực lượng để đối phó Thiên hà tứ bảo. @c1994","Đánh chiếm mắt trận trong hệ thống phòng thủ. @c2169"]},{"id":"hai-toc-nhan-yeu","name":"Hai tộc Nhân Yêu","cn":"","aliases":["Hai tộc Nhân tộc và Yêu tộc"],"type":"lien-minh","typeLabel":"Liên minh chủng tộc","diaBan":"Tam cảnh Thất địa","nhanVatChinh":["Ngao Khiếu","Mạc Giản Ly"],"blurb":"Cộng đồng hai tộc Nhân và Yêu tại Linh giới, đang đứng trước nguy cơ ma kiếp trong khi các thế lực lớn đều co cụm tự bảo vệ.","detail":"Sự ổn định của hai tộc dựa đáng kể vào hai tu sĩ Đại Thừa là Ngao Khiếu và Mạc Giản Ly. Thiên Uyên thành là một thành trì trọng yếu trong kế hoạch ứng phó Ma giới.","lanhDaoHienThoi":"Các thế lực do Tam Hoàng và Thất Yêu Vương đứng đầu","caoThuManhNhat":"Ngao Khiếu và Mạc Giản Ly","trangThai":"Chuẩn bị ứng phó ma kiếp","capNhatToi":"@c1766","thanhVien":[{"ten":"Ngao Khiếu","chucVu":"Trụ cột Đại Thừa Yêu tộc","tuChuong":"@c1766","trangThai":"Đang bế quan hồi phục"},{"ten":"Mạc Giản Ly","chucVu":"Trụ cột Đại Thừa Nhân tộc","tuChuong":"@c1766","trangThai":"Đang hoạt động"}],"nguon":["@c1766"],"tabs":{"tienTrinh":[{"chuong":"@c1766","loai":"nhắc tới","importance":"normal","giaiDoan":"Đối diện ma kiếp","text":"Hai tộc Nhân Yêu dựa vào Ngao Khiếu và Mạc Giản Ly làm trụ cột trong lúc nguy cơ Ma giới xâm lấn đến gần.","anchor":"lão tổ tông cùng với Mạc tiền bối chính là những tồn tại trụ cột"}]}},{"id":"mat-ve-hua-gia","name":"Mật vệ Hứa gia","type":"quan-doi","typeLabel":"Quân đội","diaBan":"Sơn mạch Hứa gia","nhanVatChinh":[],"blurb":"Lực lượng tinh nhuệ bí mật của Hứa gia gồm hơn trăm người, phần lớn đạt Nguyên Anh kỳ, có bí thuật liên thủ cho phép ba bốn người đấu ngang tu sĩ Hóa Thần.","detail":"Đội vệ sĩ bí mật và lực lượng tinh nhuệ nhất của Hứa gia, gồm hơn trăm người phần lớn đạt Nguyên Anh kỳ. Họ có thủ pháp ẩn nấp cao siêu, kỷ luật nghiêm ngặt, và biết bí thuật liên thủ cho phép ba bốn người phối hợp đủ sức giao chiến với tu sĩ Hóa Thần kỳ. Toàn bộ lực lượng được điều tới tông miếu canh giữ nghi thức gọi hồn.","quyMo":"Hơn trăm người, phần lớn Nguyên Anh kỳ","tabs":{"tienTrinh":[{"chuong":"@c1771","loai":"xuat-hien","importance":"normal","giaiDoan":"Hứa Giao tiết lộ cho Hàn Lập","trangThaiMoc":"Toàn bộ triệu tập bảo vệ nghi thức gọi hồn","text":"Hứa Giao giới thiệu đây là đội vệ sĩ bí mật và lực lượng tinh nhuệ nhất của Hứa gia, hơn trăm người phần lớn Nguyên Anh kỳ, biết bí thuật liên thủ.","anchor":"đây là đội vệ sĩ bí mật của chúng ta, và cũng chính là lực lượng tinh nhuệ nhất của Hứa gia"}]},"nguon":["@c1771"]},{"id":"vu-hai-mon","name":"Vụ Hải môn","cn":"","aliases":[],"type":"tong-mon","typeLabel":"Tông môn","diaBan":"Vùng hẻo lánh tại Linh giới","nhanVatChinh":["Huyền Linh Tử","Khí Linh Tử"],"blurb":"Vụ Hải môn là tông môn do Huyền Linh Tử vội vàng sáng lập tại Linh giới sau khi bị trọng thương trong lúc phi thăng. Sau khi Huyền Linh Tử vẫn lạc, môn phái dần suy yếu và Khí Linh Tử tự nhận là người kế thừa y bát.","detail":"Vụ Hải môn được Huyền Linh Tử sáng lập sau khi ông phi thăng Linh giới và chịu trọng thương, rồi không lâu sau đó vẫn lạc @c1776. Tông môn lưu truyền Vụ Hải Vô Cực đại pháp, một công pháp đòi hỏi tư chất đặc thù. Trong giai đoạn môn phái đã suy yếu, Khí Linh Tử tự nhận là người kế thừa y bát và nhiều lần tìm cách mời Hải đại thiếu cùng Hàn Lập gia nhập nhằm củng cố Vụ Hải môn.","nguonGoc":"Do Huyền Linh Tử sáng lập sau khi phi thăng Linh giới và chịu trọng thương","lanhDaoHienThoi":"Không rõ","quyMo":"Suy yếu","tranPhai":"Vụ Hải Vô Cực đại pháp","trangThai":"Suy","thanhVien":[{"ten":"Huyền Linh Tử","chucVu":"Tổ sư sáng lập","tuChuong":"@c1776","trangThai":"tu-vong"},{"ten":"Khí Linh Tử","chucVu":"Người kế thừa y bát","tuChuong":"@c1776","trangThai":"dang-hoat-dong"}],"capNhatToi":"@c1776","tabs":{"tienTrinh":[{"chuong":"@c1776","loai":"lập","importance":"major","giaiDoan":"Sáng lập tại Linh giới","text":"Huyền Linh Tử sáng lập Vụ Hải môn sau khi bị trọng thương trong lúc phi thăng, rồi vẫn lạc và để lại truyền thừa cho hậu nhân.","anchor":"Sau khi vội vàng sáng lập ra Vụ Hải môn liền vẩn lạc.","trangThaiMoc":"Được sáng lập rồi suy yếu"}]},"nguon":["@c1776"],"dacDiem":"Tông môn lưu truyền Vụ Hải Vô Cực đại pháp, công pháp đòi hỏi tư chất đặc thù; về sau đã suy yếu và cần tìm người gia nhập để củng cố môn phái."},{"id":"luc-luong-nhan-yeu-tran-thu-cuu-tien-son","name":"Lực lượng Nhân - Yêu trấn thủ Cửu Tiên Sơn","cn":"","type":"liên minh","typeLabel":"Lực lượng liên hợp","diaBan":"Cửu Tiên Sơn","nhanVatChinh":[],"blurb":"Lực lượng tinh nhuệ do Nhân tộc và Yêu tộc cùng phái tới trấn giữ Cửu Tiên Sơn. Hai bên bảo vệ khu vực tổ chức Vạn bảo giao dịch hội ngàn năm một lần.","detail":"Lực lượng liên hợp chiếm giữ chín ngọn linh sơn và thanh trừ các tiểu thế lực có tiếng xấu quanh vùng trước khi Vạn bảo giao dịch hội khai mở.","nguonGoc":"Do Nhân tộc và Yêu tộc cùng phái nhân thủ thành lập để kiểm soát Cửu Tiên Sơn.","tonChi":"Trấn giữ Cửu Tiên Sơn và bảo đảm an toàn cho Vạn bảo giao dịch hội.","quyMo":"Gồm nhiều nhân thủ tinh nhuệ của cả Nhân tộc lẫn Yêu tộc.","quanHe":"Lực lượng liên hợp giữa Nhân tộc và Yêu tộc.","trangThai":"Đang trấn giữ Cửu Tiên Sơn","capNhatToi":"@c1777","tabs":{"tienTrinh":[{"chuong":"@c1777","loai":"nhắc tới","importance":"normal","giaiDoan":"Thanh trừ khu vực quanh hội","text":"Nhân tộc và Yêu tộc cùng phái nhiều nhân thủ trấn giữ Cửu Tiên Sơn, đồng thời quét sạch các tiểu thế lực có tiếng xấu quanh vùng.","anchor":"Nhân - Yêu nhị tộc đã phái ra rất nhiều nhân thủ đem toàn bộ tiểu thế lực xú danh phụ cận quét sạch không còn một mảnh.","trangThaiMoc":"Kiểm soát Cửu Tiên Sơn trước kỳ Vạn bảo giao dịch hội"}]},"nguon":["@c1777"]},{"id":"nam-son-tam-ac","name":"Nam Sơn Tam Ác","cn":"","type":"nhom-tu-si","typeLabel":"Nhóm tu sĩ","diaBan":"Nam Sơn","nhanVatChinh":["Thạch Luân","Hai đồng bọn của Thạch Luân"],"blurb":"Nam Sơn Tam Ác là nhóm ba tu sĩ hung ác từng truy sát phụ tử Bạch Hóa Cập. Cả ba cuối cùng đều bị tiêu diệt @c1780.","detail":"Nam Sơn Tam Ác gồm Thạch Luân và hai đồng bọn. Sau khi uy hiếp và truy sát phụ tử Bạch Hóa Cập, Thạch Luân bị Hàn Lập tiêu diệt cả thân thể lẫn nguyên thần, còn hai thành viên kia bị lôi quang đánh thành tro; từ đó cả nhóm bị xóa sổ @c1780.","quyMo":"Ba người","trangThai":"Diệt","thanhVien":[{"ten":"Thạch Luân","chucVu":"Thành viên","tuChuong":"@c1780","trangThai":"Tử vong"},{"ten":"Hai đồng bọn của Thạch Luân","chucVu":"Thành viên","tuChuong":"@c1780","trangThai":"Tử vong"}],"capNhatToi":"@c1780","tabs":{"tienTrinh":[{"chuong":"@c1780","loai":"diệt/sáp nhập","importance":"major","giaiDoan":"Toàn nhóm bị tiêu diệt","trangThaiMoc":"Diệt","text":"Cả ba thành viên Nam Sơn Tam Ác đều bị giết sau khi truy sát phụ tử Bạch Hóa Cập.","anchor":"bọn đó đã bị đánh chết rồi"}]},"nguon":["@c1780"],"dacDiem":"Gồm ba tu sĩ hung ác, hành động cùng nhau và từng truy sát phụ tử Bạch Hóa Cập."},{"id":"doi-ho-gia-thien-nguyen-thanh-hoang","name":"Đội hộ giá Thiên Nguyên Thánh Hoàng","cn":"","type":"Đội hộ vệ","typeLabel":"Đội hộ vệ","diaBan":"Thiên Nguyên Cảnh","nhanVatChinh":["Thiên Nguyên Thánh Hoàng"],"blurb":"Đoàn hộ giá quy mô lớn phục vụ Thiên Nguyên Thánh Hoàng. Lực lượng gồm hơn một trăm kỵ sĩ Nguyên Anh, giáp sĩ trên ba mươi sáu chiến xa và mười tám tu sĩ Luyện Hư hậu kỳ viên mãn.","detail":"Đội ngũ di chuyển trong mây ngũ sắc với kỵ sĩ cưỡi quái thú đầu trâu thân hổ, ba mươi sáu chiến xa do phi cầm kéo và mười tám tu sĩ Luyện Hư hậu kỳ viên mãn. Trung tâm đoàn hộ giá là thú xa hình lầu các của Thiên Nguyên Thánh Hoàng.","lanhDaoHienThoi":"Thiên Nguyên Thánh Hoàng","quyMo":"Hơn một trăm tu sĩ Nguyên Anh, mười tám tu sĩ Luyện Hư hậu kỳ viên mãn cùng các giáp sĩ trên ba mươi sáu chiến xa","caoThuManhNhat":"Thiên Nguyên Thánh Hoàng","thanhVien":[{"ten":"Thiên Nguyên Thánh Hoàng","chucVu":"Chủ nhân đoàn hộ giá","tuChuong":"@c1781","trangThai":"Đang lãnh đạo"}],"lanhDaoMoc":[{"ten":"Thiên Nguyên Thánh Hoàng","tuChuong":"@c1781","denChuong":""}],"trangThai":"Đang hoạt động","capNhatToi":"@c1781","tabs":{"tienTrinh":[{"chuong":"@c1781","loai":"nhắc tới","importance":"normal","giaiDoan":"Hộ tống Thánh Hoàng","text":"Đội hộ giá hùng hậu đi ngang qua nơi nhóm Hàn Lập đang dừng chân, phô bày lực lượng đông đảo gồm các tu sĩ Nguyên Anh và Luyện Hư.","anchor":"Không ngờ đám kỵ sĩ này toàn bộ đều là Nguyên Anh Kỳ tu sĩ, ước trừng phải có tới hơn một trăm người.","trangThaiMoc":"Đang hộ tống Thiên Nguyên Thánh Hoàng"}]},"nguon":["@c1781"]},{"id":"that-dai-yeu-vuong","name":"Thất Đại Yêu Vương","cn":"","type":"nhom-cuong-gia","typeLabel":"Nhóm cường giả Yêu tộc","diaBan":"Lãnh địa Yêu tộc","nhanVatChinh":["Ly Hỏa Giao Vương","Hắc Phượng Yêu Vương"],"blurb":"Nhóm bảy Yêu Vương đứng đầu, mỗi người đều có tu vi và thiên phú đáng gờm.","detail":"Thiên Nguyên Thánh Hoàng cho biết người có tu vi thấp nhất trong Thất Đại Yêu Vương cũng đạt từ Hợp Thể trung kỳ trở lên. Khoảng một nửa trong số họ sở hữu thân thể cực mạnh, còn mỗi người đều có thiên phú thần thông riêng.","quyMo":"Bảy Yêu Vương","caoThuManhNhat":"Chưa rõ","soCaoThu":"Bảy","thanhVien":[{"ten":"Ly Hỏa Giao Vương","chucVu":"Yêu Vương","tuChuong":"@c1782","trangThai":"Đương nhiệm"},{"ten":"Hắc Phượng Yêu Vương","chucVu":"Yêu Vương","tuChuong":"@c1782","trangThai":"Đương nhiệm"}],"tabs":{"tienTrinh":[{"chuong":"@c1782","loai":"nhắc tới","importance":"bridge","giaiDoan":"Cảnh báo thực lực","text":"Thiên Nguyên Thánh Hoàng cảnh báo Hàn Lập không nên tùy tiện đắc tội Thất Đại Yêu Vương.","anchor":"Yêu tộc thất đại yêu vương tu vi thấp nhất cũng là Hợp Thể Trung Kỳ trở lên","trangThaiMoc":"Đang tồn tại"}]},"trangThai":"Đang tồn tại","capNhatToi":"@c1782","nguon":["@c1782"]},{"id":"kim-quang-tong","name":"Kim Quảng Tông","cn":"","type":"tong-mon","typeLabel":"Tông môn","diaBan":"Huyền Vũ cảnh","nhanVatChinh":["Điền Thanh Diệp","Nhạc Hoa tiên tử"],"blurb":"Tông môn bậc trung tại Huyền Vũ cảnh, có hai trưởng lão.","detail":"Điền Thanh Diệp là một trong hai trưởng lão của Kim Quảng Tông, còn Nhạc Hoa tiên tử là đệ tử thân truyền của bà.","quyMo":"Tông môn bậc trung","capBac":"Có hai trưởng lão","thanhVien":[{"ten":"Điền Thanh Diệp","chucVu":"Trưởng lão","tuChuong":"@c1783","trangThai":"Đang tại vị"},{"ten":"Nhạc Hoa tiên tử","chucVu":"Đệ tử thân truyền của Điền Thanh Diệp","tuChuong":"@c1783","trangThai":"Đang thuộc tông môn"}],"tabs":{"tienTrinh":[{"chuong":"@c1783","loai":"nhắc tới","importance":"bridge","giaiDoan":"Lộ diện tông môn","text":"Kim Quảng Tông được giới thiệu là tông môn bậc trung tại Huyền Vũ cảnh, với Điền Thanh Diệp là một trong hai trưởng lão.","anchor":"hơn nữa còn là một trong hai trưởng lão của Kim Quảng Tông"}]},"capNhatToi":"@c1783","nguon":["@c1783"]},{"id":"loi-ve","name":"Lôi Vệ","cn":"","type":"doi-can-ve","typeLabel":"Đội luyện thể sĩ","diaBan":"Huyền Vũ Cảnh; Cửu Tiên Sơn","nhanVatChinh":["Phách Hoàng","Thủ lĩnh Lôi Vệ","Ba Lôi Vệ đi cùng thủ lĩnh"],"blurb":"Lực lượng luyện thể sĩ nổi danh tại Huyền Vũ Cảnh và thường theo bên cạnh Phách Hoàng.","detail":"Một tiểu đội gồm bốn Lôi Vệ được phái tới Cửu Tiên Sơn trước khi Phách Hoàng giá lâm. Họ phụ trách ổn định trật tự, kiểm tra người tác động cấm chế và dẫn các tu sĩ đủ tư cách vào cấm địa.","nguonGoc":"Lực lượng thuộc quyền Phách Hoàng tại Huyền Vũ Cảnh","lanhDaoHienThoi":"Phách Hoàng","quyMo":"Ít nhất một tiểu đội bốn người đang làm nhiệm vụ tại Cửu Tiên Sơn","thanhVien":[{"ten":"Thủ lĩnh Lôi Vệ","chucVu":"Thủ lĩnh tiểu đội","tuChuong":"@c1786","trangThai":"Đang làm nhiệm vụ"},{"ten":"Ba Lôi Vệ đi cùng thủ lĩnh","chucVu":"Thành viên tiểu đội","tuChuong":"@c1786","trangThai":"Đang làm nhiệm vụ"}],"lanhDaoMoc":[{"ten":"Phách Hoàng","tuChuong":"@c1786","denChuong":""}],"trangThai":"Đang duy trì trật tự tại Cửu Tiên Sơn","capNhatToi":"@c1786","tabs":{"tienTrinh":[{"chuong":"@c1786","loai":"nhắc tới","importance":"normal","giaiDoan":"Trấn thủ Cửu Tiên Sơn","text":"Một tiểu đội Lôi Vệ được Phách Hoàng phái tới Cửu Tiên Sơn để ổn định trật tự trước Vạn Bảo đại hội.","trangThaiMoc":"Đang làm nhiệm vụ","anchor":"Tiểu đội này của chúng ta, đến Cửu Tiên Sơn trước để chịu trách nhiệm ổn định trật tự nơi này"}]},"nguon":["@c1786"]},{"id":"bach-cot-mon","name":"Bạch Cốt môn","cn":"","type":"tong-mon","typeLabel":"Tông môn","diaBan":"Huyền Vũ cảnh","nhanVatChinh":["Vạn Cốt chân nhân"],"blurb":"Bạch Cốt môn là tông môn do Vạn Cốt chân nhân khai sáng từ vạn năm trước. Thế lực này hiện nằm trong nhóm mười tông môn đứng đầu Huyền Vũ cảnh.","detail":"Khởi đầu từ cơ nghiệp do một tán tu gây dựng, Bạch Cốt môn đã phát triển thành thế lực lớn tại Huyền Vũ cảnh. Vạn Cốt chân nhân được nhìn nhận là tổ sư khai phái của tông môn.","nguonGoc":"Do Vạn Cốt chân nhân khai sáng từ vạn năm trước.","lanhDaoHienThoi":"Vạn Cốt chân nhân","quyMo":"Một trong mười tông môn đứng đầu Huyền Vũ cảnh.","thanhVien":[{"ten":"Vạn Cốt chân nhân","chucVu":"Tổ sư khai phái","tuChuong":"@c1787","trangThai":"gan-bo"}],"lanhDaoMoc":[{"ten":"Vạn Cốt chân nhân","tuChuong":"@c1787","denChuong":""}],"trangThai":"hoat-dong","capNhatToi":"@c1787","tabs":{"tienTrinh":[{"chuong":"@c1787","loai":"nhắc tới","importance":"normal","giaiDoan":"Tông môn hàng đầu Huyền Vũ cảnh","text":"Bạch Cốt môn được xác nhận là thế lực do Vạn Cốt chân nhân khai sáng và hiện thuộc nhóm mười tông môn đứng đầu Huyền Vũ cảnh.","anchor":"Bạch Cốt môn ở trong Huyền Vũ cảnh của chúng ta cũng là một thế lực không nhỏ"}]},"nguon":["@c1787"]},{"id":"hac-vuc-trao-doi-hoi","name":"Hắc Vực trao đổi hội","cn":"","aliases":["Hắc Vực trao đổi đại hội"],"type":"hoi-giao-dich","typeLabel":"Hội giao dịch bí mật","diaBan":"Hắc Vực","nhanVatChinh":[],"blurb":"Hội giao dịch bí mật chủ yếu dành cho tu sĩ Hợp Thể và những người mang theo trọng bảo.","detail":"Hội chỉ lấy vật đổi vật, không truy xét thân phận hay lai lịch của người tham gia và được tổ chức một lần trước Vạn Bảo đại hội. Những mặt hàng khó công khai như tài liệu yêu thú bị cấm, trứng linh thú và cả tu sĩ bị cưỡng ép cũng có thể xuất hiện tại đây.","tonChi":"Giao dịch ẩn danh theo phương thức lấy vật đổi vật.","quyMo":"Chủ yếu gồm tu sĩ Hợp Thể cùng những người có trọng bảo.","quanHe":"Việc trao đổi tu sĩ bị cưỡng ép đi ngược cấm lệnh giữa Nhân tộc và Yêu tộc.","trangThai":"Đang chờ tổ chức","tabs":{"tienTrinh":[{"chuong":"@c1788","loai":"nhắc tới","importance":"normal","giaiDoan":"Quy củ được tiết lộ","text":"Vạn Cốt chân nhân tiết lộ cho Hàn Lập về phương thức lấy vật đổi vật và tính chất bí mật của hội.","anchor":"Mà ở trao đổi đại hội cũng chỉ lấy vật đổi vật, chỉ cử hành một lần"}]},"capNhatToi":"@c1788","nguon":["@c1788"]},{"id":"nhung-nguoi-to-chuc-hac-vuc-trao-doi-hoi","name":"Những người tổ chức Hắc Vực trao đổi hội","cn":"","aliases":[],"type":"nhom-tu-si","typeLabel":"Nhóm tổ chức bí ẩn","diaBan":"Hắc Vực","nhanVatChinh":[],"blurb":"Nhóm tu sĩ thần bí điều hành Hắc Vực trao đổi hội và bí mật thông báo phương thức tiến vào cho người tham dự.","detail":"Nhóm này có thực lực đủ mạnh để duy trì trật tự tại hội. Họ từng giết một tu sĩ Hợp Thể gây chuyện, khiến những người tham dự về sau không dám đắc tội.","quyMo":"Một số tu sĩ thần bí.","caoThuManhNhat":"Có thành viên hoặc lực lượng đủ sức giết tu sĩ Hợp Thể gây chuyện.","trangThai":"Đang hoạt động","tabs":{"tienTrinh":[{"chuong":"@c1788","loai":"nhắc tới","importance":"normal","giaiDoan":"Uy thế được xác lập","text":"Nhóm tổ chức được tiết lộ từng giết một tu sĩ Hợp Thể gây chuyện ngay tại hội giao dịch.","anchor":"đã từng có một lần ở ngay trong trao đổi đại hội, đã đánh chết một gã tu sĩ Hợp Thể kỳ gây chuyện"}]},"capNhatToi":"@c1788","nguon":["@c1788"]},{"id":"lien-minh-tan-tu-hop-the-nhan-yeu-du-kien","name":"Liên minh tán tu Hợp Thể Nhân–Yêu dự kiến","cn":"","type":"lien-minh","typeLabel":"Liên minh dự kiến","diaBan":"Chưa xác định","nhanVatChinh":["Vạn Cốt chân nhân","Hoa tiên tử"],"blurb":"Liên minh dự kiến do Vạn Cốt chân nhân và Hoa tiên tử hoạch định trước Ma Kiếp, nhằm liên kết các tán tu Hợp Thể kỳ của Nhân tộc và Yêu tộc để tăng khả năng sống sót. Tính đến mốc mới nhất, thế lực này vẫn ở giai đoạn lôi kéo thành viên.","detail":"Vạn Cốt chân nhân và Hoa tiên tử dự định lợi dụng Vạn Bảo đại hội để tiếp xúc, vận động các tán tu Hợp Thể kỳ tham gia liên minh. Hai người phân công theo tộc: Hoa tiên tử phụ trách phía Yêu tộc, còn Vạn Cốt chân nhân phụ trách phía Nhân tộc. Kế hoạch được chuẩn bị trước Ma Kiếp và chưa ghi nhận việc liên minh chính thức thành lập hay triển khai hoạt động khác. @c1789","nguonGoc":"Do Vạn Cốt chân nhân và Hoa tiên tử cùng hoạch định trước Ma Kiếp.","tonChi":"Liên kết tán tu Hợp Thể kỳ hai tộc để tránh bị Cổ Ma cao cấp lần lượt tiêu diệt.","lanhDaoHienThoi":["Vạn Cốt chân nhân","Hoa tiên tử"],"quyMo":"Dự kiến gồm các tán tu Hợp Thể kỳ của Nhân tộc và Yêu tộc.","quanHe":"Không muốn lệ thuộc Tam Hoàng hoặc các Yêu Vương.","trangThai":"đang vận động thành lập","thanhVien":[{"ten":"Vạn Cốt chân nhân","chucVu":"Người khởi xướng phía Nhân tộc","tuChuong":"@c1789","trangThai":"đang vận động"},{"ten":"Hoa tiên tử","chucVu":"Người khởi xướng phía Yêu tộc","tuChuong":"@c1789","trangThai":"đang vận động"}],"capNhatToi":"@c1789","tabs":{"tienTrinh":[{"chuong":"@c1789","loai":"lập","importance":"major","giaiDoan":"Đang vận động thành lập","text":"Vạn Cốt chân nhân và Hoa tiên tử phân công lôi kéo các tán tu Hợp Thể kỳ của Nhân tộc và Yêu tộc để chuẩn bị ứng phó Ma Kiếp.","anchor":"Cứ thêm một đạo hữu Hợp Thể kỳ gia nhập với chúng ta thì tỷ lệ sinh tồn trong Ma Kiếp lại lớn hơn một phần."}]},"nguon":["@c1789"],"dacDiem":"Một liên minh tán tu Hợp Thể kỳ liên tộc Nhân–Yêu đang trong giai đoạn vận động thành viên, với công việc lôi kéo được phân chia theo từng tộc."},{"id":"thien-ho-nhat-toc","name":"Thiên Hồ nhất tộc","cn":"","type":"yeu-toc","typeLabel":"Thế lực Hồ tộc","diaBan":"Không rõ","nhanVatChinh":["Thiên Hồ Vương","Hoa tiên tử"],"blurb":"Thế lực Hồ tộc mà Hoa tiên tử từng thoát ly.","detail":"Sau khi Hoa tiên tử thoát ly và hút chân dương của hàng trăm thanh niên yêu tộc, Thiên Hồ Vương đã đích thân truy sát nàng nhưng không thành công.","thanhVien":[{"ten":"Thiên Hồ Vương","chucVu":"Yêu Vương","tuChuong":"@c1790","trangThai":"đang thuộc"},{"ten":"Hoa tiên tử","chucVu":"Thành viên cũ","tuChuong":"@c1790","trangThai":"đã rời"}],"trangThai":"Tồn tại","capNhatToi":"@c1790","tabs":{"tienTrinh":[{"chuong":"@c1790","loai":"nhắc tới","importance":"normal","giaiDoan":"Hoa tiên tử thoát ly","text":"Hoa tiên tử được xác nhận từng thoát ly Thiên Hồ nhất tộc và sau đó bị Thiên Hồ Vương truy sát.","anchor":"trước kia đã từng thoát ly khỏi Thiên Hồ nhất tộc","trangThaiMoc":"Tồn tại"}]},"nguon":["@c1790"]},{"id":"tam-hoang-that-yeu-vuong","name":"Tam Hoàng Thất Yêu Vương","cn":"","type":"nhom-cuong-gia","typeLabel":"Nhóm cường giả Nhân Yêu","diaBan":"Hai tộc Nhân Yêu","nhanVatChinh":["Thiên Nguyên Thánh Hoàng","Động Thiên Thử Vương"],"blurb":"Danh xưng chung dành cho các cường giả đứng đầu hai tộc Nhân Yêu.","detail":"Tới thời điểm gần Vạn Bảo đại hội, trong nhóm này chỉ có Thiên Nguyên Thánh Hoàng và Động Thiên Thử Vương được xác nhận đang hiện diện tại Cửu Tiên Sơn.","thanhVien":[{"ten":"Thiên Nguyên Thánh Hoàng","chucVu":"Tam Hoàng","tuChuong":"@c1790","trangThai":"đang thuộc"},{"ten":"Động Thiên Thử Vương","chucVu":"Thất Yêu Vương","tuChuong":"@c1790","trangThai":"đang thuộc"}],"trangThai":"Tồn tại","capNhatToi":"@c1790","tabs":{"tienTrinh":[{"chuong":"@c1790","loai":"nhắc tới","importance":"bridge","giaiDoan":"Tập trung trước đại hội","text":"Thiên Nguyên Thánh Hoàng và Động Thiên Thử Vương là hai thành viên của nhóm được xác nhận đã tới Cửu Tiên Sơn.","anchor":"các nhân vật trong Tam Hoàng Thất Yêu Vương ngoại trừ Thiên Nguyên Thánh Hoàng cũng chỉ có Động Thiên Thử Vương","trangThaiMoc":"Tồn tại"}]},"nguon":["@c1790"]},{"id":"van-bao-dai-hoi","name":"Vạn Bảo đại hội","cn":"","type":"dai-hoi","typeLabel":"Đại hội giao dịch","diaBan":"Cửu Tiên Sơn","nhanVatChinh":[],"blurb":"Đại hội giao dịch quy mô lớn được tổ chức tại Cửu Tiên Sơn.","detail":"Khi còn gần một tháng trước ngày khai mạc, hơn nửa số cung điện thuộc Nghênh Tiên Cung đã có người ở. Người đến dự gồm nhiều tu sĩ Hợp Thể, thái thượng trưởng lão và bá chủ một phương.","quyMo":"Quy tụ nhiều tu sĩ Hợp Thể và thủ lĩnh các thế lực","trangThai":"Sắp khai mạc","capNhatToi":"@c1790","tabs":{"tienTrinh":[{"chuong":"@c1790","loai":"nhắc tới","importance":"normal","giaiDoan":"Khách dự hội tập trung","text":"Gần một tháng trước ngày khai mạc, hơn nửa số Nghênh Tiên Cung đã có người đến ở.","anchor":"Đến khi chỉ còn khoảng gần một tháng trước khi Vạn Bảo đại hội khai mạ thì vài tòa Nghênh Tiên Cung đã hơn một nửa có người ở.","trangThaiMoc":"Sắp khai mạc"}]},"nguon":["@c1790"]},{"id":"quynh-thu-nhat-toc","name":"Quỳnh Thử nhất tộc","cn":"","type":"yeu-toc","typeLabel":"Đại tộc Yêu tộc","diaBan":"Không rõ","nhanVatChinh":["Động Thiên Thử Vương"],"blurb":"Quỳnh Thử nhất tộc là một đại tộc quan trọng trong Yêu tộc và là thế lực hậu thuẫn cho địa vị Yêu Vương của Động Thiên Thử Vương.","detail":"Địa vị của Động Thiên Thử Vương được nâng đỡ bởi Quỳnh Thử nhất tộc, phản ánh vai trò của các đại tộc trong cơ cấu quyền lực Yêu tộc.","quyMo":"Đại tộc quan trọng trong Yêu tộc","thanhVien":[{"ten":"Động Thiên Thử Vương","chucVu":"Yêu Vương","tuChuong":"@c1791","trangThai":"Đang thuộc"}],"trangThai":"Đang tồn tại","tabs":{"tienTrinh":[{"chuong":"@c1791","loai":"nhắc tới","importance":"normal","giaiDoan":"Hậu thuẫn Yêu Vương","text":"Quỳnh Thử nhất tộc được xác nhận là đại tộc quan trọng đứng sau hậu thuẫn Động Thiên Thử Vương.","anchor":"Quỳnh Thử nhất tộc, là một đại tộc hết sức quan trọng trong yêu tộc","trangThaiMoc":"Đang tồn tại"}]},"capNhatToi":"@c1791","nguon":["@c1791"]},{"id":"he-thong-duoi-quyen-thien-dieu-linh-hoang-doi-truoc","name":"Hệ thống dưới quyền Thiên Diệu Linh Hoàng đời trước","cn":"","type":"khac","typeLabel":"Hệ thống thuộc hạ","diaBan":"Nhân tộc","nhanVatChinh":["Thiên Diệu Linh Hoàng","Liễu Thanh"],"blurb":"Hệ thống thuộc hạ của Thiên Diệu Linh Hoàng đời trước từng có hai tu sĩ Hợp Thể kỳ đắc lực.","detail":"Một trong hai thủ hạ là Liễu Thanh, người tinh thông Khôi Lỗi Chi Thuật. Người còn lại chưa rõ tên và tinh thông Biến Ảo Chi Đạo.","lanhDaoHienThoi":"Thiên Diệu Linh Hoàng đời trước","caoThuManhNhat":"Hai thủ hạ Hợp Thể kỳ","soCaoThu":"Hai thủ hạ đắc lực được nhắc tới","thanhVien":[{"ten":"Thiên Diệu Linh Hoàng","chucVu":"Lãnh đạo","tuChuong":"@c1791","trangThai":"Đời trước"},{"ten":"Liễu Thanh","chucVu":"Thủ hạ đắc lực","tuChuong":"@c1791","trangThai":"Không rõ"}],"lanhDaoMoc":[{"ten":"Thiên Diệu Linh Hoàng","tuChuong":"@c1791","denChuong":""}],"trangThai":"Không rõ","tabs":{"tienTrinh":[{"chuong":"@c1791","loai":"nhắc tới","importance":"normal","giaiDoan":"Thuộc hạ được hé lộ","text":"Hệ thống dưới quyền Thiên Diệu Linh Hoàng đời trước được tiết lộ từng có hai thủ hạ Hợp Thể kỳ đắc lực.","anchor":"Thiên Diệu Linh Hoàng đời trước có hai gã thủ hạ đắc lực","trangThaiMoc":"Không rõ"}]},"capNhatToi":"@c1791","nguon":["@c1791"]},{"id":"vu-hai-quan","name":"Vụ Hải Quan","cn":"","type":"tong-mon","typeLabel":"Thế lực truyền thừa","diaBan":"Vụ Hải Quan","nhanVatChinh":["Khí Linh Tử"],"blurb":"Vụ Hải Quan là nguồn gốc của pháp khí và công pháp truyền thừa đang nằm trong cơ thể Khí Linh Tử.","detail":"Hàn Lập định hướng để Khí Linh Tử tiếp tục kế thừa Vụ Hải nhất mạch. Nếu tu luyện đại thành, hắn có thể trở lại đảm nhiệm chức Vụ Hải Quan chi chủ.","nguonGoc":"Nguồn gốc của Truyền thừa Khí vật và công pháp bí thuật do Khí Linh Tử kế thừa.","lanhDaoHienThoi":"Chưa rõ","trangThai":"Chờ người kế thừa tu luyện đại thành","thanhVien":[{"ten":"Khí Linh Tử","chucVu":"Người kế thừa","tuChuong":"@c1795","trangThai":"đang kế thừa"}],"capNhatToi":"@c1795","tabs":{"tienTrinh":[{"chuong":"@c1795","loai":"nhắc tới","importance":"normal","giaiDoan":"Xác lập người kế thừa","text":"Khí Linh Tử được xác định là người kế thừa Vụ Hải nhất mạch và có thể đảm nhiệm Vụ Hải Quan chi chủ sau khi tu luyện đại thành.","anchor":"Chờ ngươi tu luyện đại thành thì có thể một lần nữa đảm đương Vụ Hải Quan chi chủ","trangThaiMoc":"Chờ người kế thừa tu luyện đại thành"}]},"nguon":["@c1795"]},{"id":"huyen-vu-thanh","name":"Huyền Vũ thành","cn":"","type":"thanh-tri","typeLabel":"Thế lực thành trì","diaBan":"Thành Huyền Vũ","nhanVatChinh":["Bành Quyết"],"blurb":"Thế lực thành trì có Bành Quyết giữ chức phó thành chủ. Ông đồng thời đại diện quản lý công việc phía Nhân tộc tại đại hội.","detail":"Huyền Vũ thành được xác nhận có cơ cấu thành chủ và phó thành chủ. Bành Quyết là một phó thành chủ của thế lực này.","lanhDaoHienThoi":"Chưa rõ thành chủ; Bành Quyết giữ chức phó thành chủ","thanhVien":[{"ten":"Bành Quyết","chucVu":"Phó thành chủ","tuChuong":"@c1796","trangThai":"Đương nhiệm"}],"tabs":{"tienTrinh":[{"chuong":"@c1796","loai":"nhắc tới","importance":"normal","giaiDoan":"Xác nhận phó thành chủ","text":"Bành Quyết tự giới thiệu là phó thành chủ Huyền Vũ thành và là quản sự phụ trách phía Nhân tộc tại đại hội.","anchor":"tại hạ là Bành Quyết, Huyền Vũ thành phó chủ"}]},"capNhatToi":"@c1796","nguon":["@c1796"]},{"id":"hac-phuong-cung","name":"Hắc Phượng Cung","cn":"","type":"cung","typeLabel":"Cung","diaBan":"Có viêm vực dùng làm nơi trách phạt","nhanVatChinh":["Tiêu Quán","Tiểu Hồng"],"blurb":"Cơ sở gắn với Hắc Phượng tộc và Tiêu Quán. Bên trong có viêm vực, nơi Tiểu Hồng bị phạt diện bích một nghìn năm.","detail":"Hắc Phượng Cung có một khu vực gọi là viêm vực được dùng để thi hành hình phạt. Tiêu Quán đã buộc Tiểu Hồng diện bích tại đây vì tự tiện tham gia mưu tính liên quan đến Thiên Phượng chân huyết.","lanhDaoHienThoi":"Tiêu Quán","thanhVien":[{"ten":"Tiêu Quán","chucVu":"Người quản lĩnh","tuChuong":"@c1797","trangThai":"đương nhiệm"},{"ten":"Tiểu Hồng","chucVu":"Người chịu phạt","tuChuong":"@c1797","trangThai":"diện bích tại viêm vực"}],"trangThai":"Hoạt động","capNhatToi":"@c1797","tabs":{"tienTrinh":[{"chuong":"@c1797","loai":"nhắc tới","importance":"normal","giaiDoan":"Trách phạt Tiểu Hồng","text":"Tiểu Hồng bị Tiêu Quán phạt diện bích một nghìn năm tại viêm vực trong Hắc Phượng Cung.","anchor":"đã bị ta trách phạt ở viêm vực trong Hắc Phượng Cung diện bích ngàn năm.","trangThaiMoc":"Tiểu Hồng đang chịu phạt"}]},"nguon":["@c1797"]},{"id":"thiet-lac-toc","name":"Thiết Lặc tộc","cn":"","aliases":[],"type":"chung-toc","typeLabel":"Dị tộc","diaBan":"Thiên Nguyên đại lục","nhanVatChinh":[],"blurb":"Một tộc từng hoành hành trên Thiên Nguyên đại lục từ mấy chục vạn năm trước. Kình Thiên chiến thuyền từng là đỉnh giai chiến thuyền của tộc này.","detail":"Thiết Lặc tộc từng sử dụng Kình Thiên chiến thuyền để vận chuyển hơn nghìn người và tăng mạnh chiến lực tập thể. Trong chương này, tộc chỉ được nhắc qua lịch sử của chiến thuyền.","tranPhai":["Kình Thiên chiến thuyền"],"trangThai":"Không rõ","capNhatToi":"@c1800","tabs":{"tienTrinh":[{"chuong":"@c1800","loai":"nhắc tới","importance":"bridge","giaiDoan":"Lịch sử Kình Thiên chiến thuyền","text":"Thiết Lặc tộc được nhắc là thế lực từng sử dụng Kình Thiên chiến thuyền và hoành hành trên Thiên Nguyên đại lục.","anchor":"nó là đỉnh giai chiến thuyền của Thiết Lặc tộc từng hoành hành một thời"}]},"nguon":["@c1800"]},{"id":"kim-cuong-yeu-vien-nhat-toc","name":"Kim Cương Yêu Viên nhất tộc","cn":"","type":"yeu-toc","typeLabel":"Yêu tộc","diaBan":"Quanh Thánh đảo","nhanVatChinh":[],"blurb":"Yêu tộc được đồn quanh năm bảo hộ Thánh đảo và sở hữu thiên phú Cửu Anh chân hỏa.","detail":"Lũng gia lão tổ suy đoán Kim mao Cự viên có tám, chín phần thuộc tộc này, nhưng lai lịch ấy chưa được xác nhận trực tiếp.","tranPhai":"Cửu Anh chân hỏa","quanHe":"Được đồn là lực lượng bảo hộ Thánh đảo.","trangThai":"Đang hoạt động","tabs":{"tienTrinh":[{"chuong":"@c1807","loai":"nhắc tới","importance":"bridge","giaiDoan":"Suy đoán về người bảo hộ","text":"Kim Cương Yêu Viên nhất tộc được nhắc đến như yêu binh quanh năm bảo hộ Thánh đảo.","anchor":"có một loài yêu binh quanh năm đều bảo hộ Thánh đảo, nghe đồn chính là Kim Cương Viên Yêu nhất tộc"}]},"capNhatToi":"@c1807","nguon":["@c1807"]},{"id":"thien-ho-toc","name":"Thiên Hồ Tộc","cn":"","type":"yeu-toc","typeLabel":"Yêu tộc","diaBan":"Có điếm phô tại Thiên Uyên Thành","nhanVatChinh":["Tần Tố Nhi","Mị Linh","Hồ Vương"],"blurb":"Thiên Hồ Tộc là tộc quần của Tần Tố Nhi và Mị Linh, do Hồ Vương đương nhiệm đứng đầu.","detail":"Tộc sở hữu Tâm Huyễn đại pháp cùng các pháp trận có thể tăng cường huyễn thuật và mê mị thuật. Điếm phô của tộc tại Thiên Uyên Thành được tỷ muội Tần thị dùng làm nơi giao dịch tài liệu yêu thú với Hàn Lập.","lanhDaoHienThoi":"Hồ Vương","tranPhai":["Tâm Huyễn đại pháp","Pháp trận tăng phúc huyễn thuật"],"thanhVien":[{"ten":"Tần Tố Nhi","chucVu":"Tộc nhân","tuChuong":"@c1809","trangThai":"Đang thuộc tộc"},{"ten":"Mị Linh","chucVu":"Tộc nhân","tuChuong":"@c1809","trangThai":"Đang thuộc tộc"},{"ten":"Hồ Vương","chucVu":"Hồ Vương đương nhiệm","tuChuong":"@c1809","trangThai":"Đang lãnh đạo"}],"lanhDaoMoc":[{"ten":"Hồ Vương","tuChuong":"@c1809","denChuong":""}],"trangThai":"Đang hoạt động","capNhatToi":"@c1809","tabs":{"tienTrinh":[{"chuong":"@c1809","loai":"nhắc tới","importance":"normal","giaiDoan":"Giao dịch tại Thiên Uyên Thành","text":"Điếm phô của Thiên Hồ Tộc được dùng làm nơi tỷ muội Tần thị giao dịch tài liệu yêu thú với Hàn Lập.","anchor":"Nơi này là bổn điếm của Thiên Hồ Nhất Tộc","trangThaiMoc":"Đang hoạt động"}]},"nguon":["@c1809"]},{"id":"hac-vuc-hoi","name":"Hắc Vực","cn":"","aliases":["Hắc Vực hội"],"type":"to-chuc","typeLabel":"Tổ chức","diaBan":"Không gian phía dưới biển hắc khí, Hắc Vực đại điện và hội trường Trao đổi đại hội","nhanVatChinh":["Hắc bào nhân","Hắc sa thị nữ cầm đầu","Hắc sa thị nữ số Chín","Hắc sa thị nữ số Mười một","Hắc sa thị nữ dẫn lão giả"],"blurb":"Tổ chức bí mật điều hành khu vực Hắc Vực và đứng ra tổ chức Trao đổi đại hội.","detail":"Hắc Vực bố trí Khiên Dẫn sứ giả đưa khách xuyên qua biển hắc khí, đồng thời sắp xếp đội hắc sa thị nữ tiếp đón tại đại điện. Tổ chức này dự định đưa một số kỳ trân ra trao đổi trước khi đại hội chính thức bắt đầu.","quyMo":"Có hệ thống sứ giả dẫn đường, đội thị nữ tiếp khách và hội trường chứa khoảng năm sáu trăm thạch đình.","quanHe":"Tiếp đón các tu sĩ tham dự Trao đổi đại hội.","trangThai":"Đang tổ chức Trao đổi đại hội","thanhVien":[{"ten":"Hắc bào nhân","chucVu":"Khiên Dẫn sứ giả","tuChuong":"@c1812","trangThai":"đang hoạt động"},{"ten":"Hắc sa thị nữ cầm đầu","chucVu":"Điều phối thị nữ tiếp khách","tuChuong":"@c1812","trangThai":"đang hoạt động"},{"ten":"Hắc sa thị nữ số Chín","chucVu":"Thị nữ dẫn đường","tuChuong":"@c1812","trangThai":"đang hoạt động"},{"ten":"Hắc sa thị nữ số Mười một","chucVu":"Thị nữ dẫn đường","tuChuong":"@c1812","trangThai":"đang hoạt động"},{"ten":"Hắc sa thị nữ dẫn lão giả","chucVu":"Thị nữ dẫn đường","tuChuong":"@c1812","trangThai":"đang hoạt động"}],"capNhatToi":"@c1812","tabs":{"tienTrinh":[{"chuong":"@c1812","loai":"nhắc tới","importance":"normal","giaiDoan":"Tổ chức Trao đổi đại hội","text":"Hắc Vực đưa khách vào hội trường, bố trí thị nữ tiếp đón và chuẩn bị kỳ trân để mở màn hoạt động trao đổi.","anchor":"Hắc Vực hội các ngươi trước tiên xuất ra một số kỳ trân vật trao đổi cùng chúng ta!","trangThaiMoc":"Đang chuẩn bị mở màn Trao đổi đại hội"}]},"nguon":["@c1812"]},{"id":"hac-vuc","name":"Hắc Vực","cn":"","aliases":[],"type":"to-chuc","typeLabel":"Tổ chức bí ẩn","diaBan":"Hắc Vực","nhanVatChinh":["Kim Diện Nhân"],"blurb":"Thế lực tổ chức hội trao đổi và cung cấp nhiều vật phẩm, tài liệu cùng người làm hàng hóa giao dịch. Một trưởng lão của Hắc Vực từng thử luyện chế phôi thai kỳ bảo nhưng không thể hoàn thành.","detail":"Trong chương này, Hắc Vực hoàn tất giao dịch Tề Thiên La và phôi thai kỳ bảo với Hàn Lập, tổ chức ba đợt trao đổi tài liệu khan hiếm, đưa nhóm bảy nữ tu ra đổi và dùng hoàng sắc Cổ phiên làm món áp trục thứ hai.","quyMo":"Có trưởng lão và đủ nguồn lực tổ chức hội trao đổi quy mô lớn.","thanhVien":[{"ten":"Kim Diện Nhân","chucVu":"Người chủ trì đại hội","tuChuong":"@c1816","trangThai":"đang hoạt động"}],"trangThai":"Đang tổ chức trao đổi tự do","capNhatToi":"@c1816","tabs":{"tienTrinh":[{"chuong":"@c1816","loai":"nhắc tới","importance":"normal","giaiDoan":"Tổ chức nhiều giao dịch","text":"Hắc Vực tổ chức liên tiếp nhiều đợt trao đổi, hoàn tất vụ đổi với Hàn Lập và đưa hoàng sắc Cổ phiên ra làm món áp trục thứ hai.","anchor":"bảo vật này chính là vật một trưởng lão Hắc Vực chúng ta từng luyện chế","trangThaiMoc":"Đang tổ chức hội trao đổi"},{"chuong":"@c1817","loai":"mở rộng/mất địa bàn","importance":"normal","giaiDoan":"Mở trao đổi tự do","text":"Hắc Vực kết thúc phần trao đổi của mình và mở giai đoạn để người tham dự tự triển lãm vật phẩm.","anchor":"Về phần quy củ thì vẫn như lần trước, mỗi lần nhiều nhất chỉ có ba người lên triển lãm vật phẩm.","trangThaiMoc":"Đại hội bước sang trao đổi tự do"}]},"nguon":["@c1816","@c1817"]},{"id":"nhan-yeu-luong-toc","name":"Nhân yêu lưỡng tộc","cn":"","type":"chung-toc","typeLabel":"Liên hợp chủng tộc","diaBan":"Không rõ","nhanVatChinh":["Các lão quái Hợp Thể kỳ nhân yêu lưỡng tộc"],"blurb":"Hai quần thể Nhân tộc và Yêu tộc đang chuẩn bị ứng phó Ma kiếp. Từ thời thượng cổ, lưỡng tộc đã nghiêm cấm luyện chế Nghiệt Vân vì quá trình này tổn hại thiên địa.","detail":"Trước nguy cơ Ma kiếp, các tu sĩ thuộc nhân yêu lưỡng tộc ưu tiên dùng tài liệu quý hiếm đổi lấy bảo vật thành phẩm có thể sử dụng ngay. Quy định cấm luyện chế Nghiệt Vân của lưỡng tộc vẫn khiến cấm vật này trở nên đặc biệt nhạy cảm.","tonChi":"Chuẩn bị lực lượng và bảo vật để ứng phó Ma kiếp.","quanHe":"Cùng duy trì lệnh cấm luyện chế Nghiệt Vân.","trangThai":"Đồng minh công thủ","tabs":{"tienTrinh":[{"chuong":"@c1818","loai":"nhắc tới","importance":"bridge","giaiDoan":"Lệnh cấm Nghiệt Vân","text":"Nhân yêu lưỡng tộc được xác nhận đã nghiêm cấm luyện chế Nghiệt Vân từ thời thượng cổ.","anchor":"Cho nên từ thời kỳ thượng cổ, nghiệt vân chính là một trong những cấm vật mà lưỡng tộc nghiêm cấm luyện chế.","trangThaiMoc":"Duy trì lệnh cấm luyện chế Nghiệt Vân"},{"chuong":"@c1837","loai":"liên minh","importance":"normal","giaiDoan":"Tham gia Ngàn năm minh ước","text":"Nhân Yêu lưỡng tộc đình chiến với các dị tộc đối địch và chuyển sang quan hệ đồng minh công thủ.","anchor":"Trong vòng ngàn năm, các tộc không được khai chiến lẫn nhau, ngược lại tuân thủ ước định đồng minh công thủ.","trangThaiMoc":"Tham gia minh ước"},{"chuong":"@c1887","loai":"nhắc tới","importance":"normal","giaiDoan":"Được thảo luận tại hội nghị về nguy cơ Thánh Tổ hàng lâm","text":"Ngân Quang tiên tử cảnh báo nếu hơn mười Thánh Tổ cùng cấp hàng lâm thì Nhân Yêu lưỡng tộc không đủ sức chống đỡ.","anchor":"Nhân Yêu lưỡng tộc chúng ta căn bản không có cách nào ngăn cản nữa"}]},"capNhatToi":"@c1818","nguon":["@c1818","@c1837","@c1887","@c1995"]},{"id":"bang-phuong-toc","name":"Băng Phượng tộc","cn":"","aliases":[],"type":"chung-toc","typeLabel":"Chủng tộc","diaBan":"Không rõ","nhanVatChinh":["Băng Phượng"],"blurb":"Chủng tộc của Băng Phượng, sở hữu bí thuật truyền thừa liên quan đến Thiên Phượng nguyên âm.","detail":"Băng Phượng tộc có truyền thừa bí mật cho phép tộc nhân đưa Thiên Phượng nguyên âm chi khí ra ngoài cơ thể mà không cần song tu hoặc dùng phương pháp lô đỉnh.","tranPhai":["Bí thuật dẫn xuất Thiên Phượng nguyên âm"],"thanhVien":[{"ten":"Băng Phượng","chucVu":"Tộc nhân","tuChuong":"@c1821","trangThai":"còn liên hệ"}],"tabs":{"tienTrinh":[{"chuong":"@c1821","loai":"nhắc tới","importance":"normal","giaiDoan":"Hé lộ truyền thừa","text":"Băng Phượng tiết lộ bí thuật truyền thừa của tộc có thể đưa Thiên Phượng nguyên âm ra ngoài cơ thể mà không cần song tu hoặc dùng phương pháp lô đỉnh.","anchor":"Bộ tộc chúng ta Băng Phượng có truyền thừa bí mật, không cần dùng phương pháp song tu lô đỉnh vẫn có thể đem Thiên Phượng nguyên âm chi khí bên trong bức ra ngoài cơ thể."}]},"capNhatToi":"@c1821","nguon":["@c1821"]},{"id":"lam-thuy-tong","name":"Lam Thủy Tông","cn":"","aliases":[],"type":"tong-mon","typeLabel":"Tông môn","diaBan":"Thiên Nguyên Thành","nhanVatChinh":["Cẩm bào đại hán"],"blurb":"Ngoại môn tông môn có liên hệ với Thiên Nguyên Thành, sở hữu Lam Cực Châu và Bạch Thủy Phiên làm trấn tông chi bảo. Tông chủ cùng đoàn vận chuyển tài liệu bị Lục Dực sát hại, còn nhị bảo bị phá hủy và luyện hóa.","detail":"Lam Thủy Tông có công pháp được nhận xét là bình thường nhưng sở hữu hai bảo vật luyện từ bốn mươi chín loại tài liệu chí hàn. Trong chuyến vận chuyển có Huyền Âm Tinh Bích, đoàn người của tông môn bị Lục Dực tiêu diệt và tông chủ mất cả Nguyên Anh.","nguonGoc":"Ngoại môn tông môn tại Thiên Nguyên Thành","lanhDaoHienThoi":"Tông chủ đã tử vong","tranPhai":"Lam Cực Châu và Bạch Thủy Phiên","quanHe":"Có liên hệ với Thiên Nguyên Thành","trangThai":"Tông chủ cùng đoàn vận chuyển bị giết, hai trấn tông chi bảo bị phá hủy","thanhVien":[{"ten":"Cẩm bào đại hán","chucVu":"Tông chủ","tuChuong":"@c1824","trangThai":"Đã tử vong"}],"lanhDaoMoc":[{"ten":"Cẩm bào đại hán","tuChuong":"@c1824","denChuong":"@c1824"}],"tabs":{"tienTrinh":[{"chuong":"@c1824","loai":"suy","importance":"normal","giaiDoan":"Mất tông chủ và nhị bảo","trangThaiMoc":"Tông chủ cùng đoàn vận chuyển bị giết, nhị bảo bị phá hủy","text":"Tông chủ Lam Thủy Tông cùng đoàn vận chuyển bị Lục Dực sát hại, còn Lam Cực Châu và Bạch Thủy Phiên bị phá hủy rồi luyện hóa.","anchor":"Lam Thủy Tông là chính là ngoại môn tông môn ở Thiên Nguyên Thành."}]},"capNhatToi":"@c1824","nguon":["@c1824"]},{"id":"lao-gia","name":"Lao gia","cn":"","type":"gia-toc","typeLabel":"Chân Linh thế gia","diaBan":"Chưa rõ","nhanVatChinh":["Lao gia lão tổ","Lao Ai"],"blurb":"Một Chân Linh thế gia tham dự đại điển và nhắm vào vị trí của Cốc gia.","detail":"Lao gia coi sự vắng mặt của Thiên Lê tiên tử là cơ hội. Gia tộc dự định giữ sức khi gặp các thế gia khác nhưng sẽ dốc toàn lực, kể cả chấp nhận tổn hao nguyên khí, khi đến lượt khiêu chiến Cốc gia.","lanhDaoHienThoi":"Lao gia lão tổ","quanHe":"Đối địch với Cốc gia trong cuộc tỷ thí xếp hạng; phối hợp kế hoạch với Phong gia.","trangThai":"Đang khiêu chiến vị trí của Cốc gia","thanhVien":[{"ten":"Lao gia lão tổ","chucVu":"Lão tổ","tuChuong":"@c1826","trangThai":"Đang tại vị"},{"ten":"Lao Ai","chucVu":"Đại biểu Hợp Thể","tuChuong":"@c1831","trangThai":"đang hoạt động"}],"lanhDaoMoc":[{"ten":"Lao gia lão tổ","tuChuong":"@c1826","denChuong":""}],"capNhatToi":"@c1826","tabs":{"tienTrinh":[{"chuong":"@c1826","loai":"khai chiến","importance":"normal","giaiDoan":"Nhắm vào Cốc gia","text":"Lao gia quyết định giữ sức trước các đối thủ khác và dốc toàn lực khiêu chiến Cốc gia.","anchor":"Chính là cơ hội tốt cho Lao gia chúng ta!"},{"chuong":"@c1831","loai":"khai chiến","importance":"normal","giaiDoan":"Thách đấu Cốc gia","text":"Kế hoạch đưa Lao gia vào Ngũ đại thế gia bị rối loạn, nhưng Lao Ai vẫn đại diện gia tộc công khai khiêu chiến Cốc gia.","anchor":"Hiển nhiên vừa rồi Hàn Lập thể hiện thực lực ở trên Vạn Linh Đài, nhất thời khiến kế hoạch hạ bệ Cốc gia để cho Lao gia tiến vào Ngũ đại thế gia trở nên rối loạn","trangThaiMoc":"Công khai khiêu chiến Cốc gia"}]},"nguon":["@c1826","@c1831"]},{"id":"ngu-dai-chan-linh-the-gia","name":"Ngũ đại Chân Linh thế gia","cn":"","aliases":["Ngũ đại thế gia"],"type":"gia-toc-lien-minh","typeLabel":"Nhóm Chân Linh thế gia","diaBan":"Nhân tộc","nhanVatChinh":["Lũng gia lão tổ","Nam tử tóc dài áo xanh lục","Lâm tiên tử","Diệp tiên tử"],"blurb":"Năm đại gia tộc đứng đầu hệ thống Chân Linh thế gia. Thứ hạng cũ của họ bị bãi bỏ tại Chân Linh đại điển và phải được xác lập lại bằng xa luân chiến.","detail":"Ngũ đại gia tộc phải giao đấu vòng tròn để xác định thứ hạng mới trước khi những Chân Linh thế gia khác được phép khiêu chiến. Kết quả xếp hạng liên quan đến việc phân chia Tiềm Linh Lệnh, tài nguyên và lợi ích.","quyMo":"Năm đại gia tộc","quanHe":"Các thành viên cạnh tranh thứ hạng bằng xa luân chiến.","trangThai":"hoàn tất tỷ thí xếp hạng","capNhatToi":"@c1827","tabs":{"tienTrinh":[{"chuong":"@c1827","loai":"nhắc tới","importance":"normal","giaiDoan":"Bãi bỏ thứ hạng cũ","text":"Thứ hạng cũ của năm đại gia tộc bị bãi bỏ và họ phải tiến hành xa luân chiến để xác lập trật tự mới.","anchor":"xếp hạng của ngũ đại gia tộc chúng ta khi trước hiện giờ đã bị bãi bỏ","trangThaiMoc":"Đang xếp lại thứ hạng"},{"chuong":"@c1832","loai":"nhắc tới","importance":"normal","giaiDoan":"Kết thúc xếp hạng","trangThaiMoc":"Phân phát lệnh bài và thương nghị tài nguyên","text":"Ngũ đại Chân Linh thế gia hoàn tất đợt tỷ thí xếp hạng, sau đó phân phát lệnh bài và thương nghị phân chia tài nguyên theo bài danh.","anchor":"Sau mấy trường đấu pháp nữa, toàn bộ đợt tỷ thí xếp danh cũng kết thúc."}]},"nguon":["@c1827","@c1832"]},{"id":"lam-gia","name":"Lâm gia","cn":"","type":"gia-toc","typeLabel":"Chân Linh thế gia","diaBan":"Không rõ","nhanVatChinh":["Lâm đạo hữu","Nam tử tóc dài đội vòng bạc"],"blurb":"Thế gia xếp hạng ba trong Ngũ đại Chân Linh thế gia. Lâm gia thắng trận đầu vì Phong gia chủ động nhận thua.","detail":"Đại trưởng lão Lâm gia sở hữu Mộc Thận đại pháp, khiến hai tu sĩ Hợp Thể đại diện Phong gia tự nhận không thể phá giải và từ bỏ giao đấu.","quyMo":"Xếp hạng ba trong Ngũ đại Chân Linh thế gia.","caoThuManhNhat":"Lâm đạo hữu","trangThai":"Giữ nguyên vị trí sau khi thua Diệp gia","thanhVien":[{"ten":"Lâm đạo hữu","chucVu":"Đại trưởng lão","tuChuong":"@c1828","trangThai":"Đang tại vị"}],"capNhatToi":"@c1828","tabs":{"tienTrinh":[{"chuong":"@c1828","loai":"nhắc tới","importance":"normal","giaiDoan":"Thắng Phong gia","text":"Lâm gia thắng trận đầu mà không cần giao đấu do Phong gia chủ động nhận thua.","anchor":"Đại trưởng lão của thế gia xếp hạng thứ ba trong Ngũ đại thế gia - Lâm gia"},{"chuong":"@c1831","loai":"khai chiến","importance":"normal","giaiDoan":"Thua Diệp gia","text":"Đại biểu Lâm gia bị đại biểu Diệp gia bức khỏi quang tráo và phải nhận thua.","anchor":"cuối cùng vẫn bị thiếu nữ bức ra ngoài quang tráo, chỉ có thể mặt nặng như đeo đá nhận thua","trangThaiMoc":"Thua Diệp gia"}]},"nguon":["@c1828","@c1831"]},{"id":"ngan-nam-minh-uoc","name":"Ngàn năm minh ước","cn":"","type":"lien-minh","typeLabel":"Minh ước liên tộc","diaBan":"","nhanVatChinh":[],"blurb":"Ngàn năm minh ước là thỏa thuận đình chiến được thiết lập sau tuyên bố của Thánh Đảo giữa Nhân tộc, Yêu tộc và các dị tộc vốn đối địch. Minh ước duy trì hòa hoãn trong một nghìn năm, đồng thời ràng buộc các bên bằng nghĩa vụ đồng minh công thủ.","detail":"Sau tuyên bố đình chiến của Thánh Đảo, Nhân Yêu lưỡng tộc cùng các dị tộc đối địch thiết lập Ngàn năm minh ước. Trong thời hạn một nghìn năm, các tộc tham gia không được khai chiến với nhau và phải thực hiện cam kết hỗ trợ lẫn nhau theo nghĩa vụ đồng minh công thủ. @c1837","nguonGoc":"Được thiết lập sau tuyên bố đình chiến của Thánh Đảo.","tonChi":"Ngăn chiến tranh giữa các tộc và duy trì nghĩa vụ đồng minh công thủ.","quyMo":"Nhân Yêu lưỡng tộc cùng các dị tộc vốn đối địch.","trangThai":"Có hiệu lực","tabs":{"tienTrinh":[{"chuong":"@c1837","loai":"lập","importance":"major","giaiDoan":"Minh ước được thiết lập","text":"Nhân Yêu lưỡng tộc và các dị tộc đối địch thiết lập thời hạn đình chiến một nghìn năm, đồng thời cam kết hỗ trợ nhau theo thỏa thuận công thủ.","anchor":"Trong vòng ngàn năm, các tộc không được khai chiến lẫn nhau, ngược lại tuân thủ ước định đồng minh công thủ.","trangThaiMoc":"Có hiệu lực"}]},"capNhatToi":"@c1837","nguon":["@c1837"],"dacDiem":"Minh ước đình chiến liên tộc có thời hạn một nghìn năm, kết hợp điều khoản không khai chiến với nghĩa vụ hỗ trợ lẫn nhau.","congNang":["Ngăn các tộc tham gia khai chiến với nhau trong thời hạn một nghìn năm. @c1837","Ràng buộc các bên tham gia bằng cam kết hỗ trợ lẫn nhau và nghĩa vụ đồng minh công thủ. @c1837"]},{"id":"the-luc-thuoc-linh-hoang","name":"Thế lực thuộc Linh hoàng","cn":"","type":"chinh-quyen","typeLabel":"Thế lực trực thuộc","diaBan":"Thiên Linh Cảnh","nhanVatChinh":["Nữ tu thần bí"],"blurb":"Các thế lực trực thuộc ngôi Linh hoàng tại Thiên Linh Cảnh. Sau khi nữ tu thần bí chiến thắng tại Đại Bỉ và đoạt ngôi Linh hoàng, các thế lực này được nàng tiếp nhận.","detail":"Đây là các thế lực thuộc quyền Linh hoàng tại Thiên Linh Cảnh. Sau chiến thắng của nữ tu thần bí tại Đại Bỉ, quyền lãnh đạo được chuyển giao và các thế lực này do nàng tiếp nhận. @c1837","lanhDaoHienThoi":"Nữ tu thần bí","trangThai":"Ổn định","thanhVien":[{"ten":"Nữ tu thần bí","chucVu":"Linh hoàng","tuChuong":"@c1837","trangThai":"Đang lãnh đạo"}],"lanhDaoMoc":[{"ten":"Nữ tu thần bí","tuChuong":"@c1837","denChuong":""}],"tabs":{"tienTrinh":[{"chuong":"@c1837","loai":"đổi lãnh đạo","importance":"major","giaiDoan":"Linh hoàng mới kế vị","text":"Các thế lực thuộc Linh hoàng được nữ tu thần bí tiếp nhận sau khi nàng chiến thắng tại Đại Bỉ.","anchor":"Linh hoàng mới kế vị đã vô cùng thuận lợi thu nhận các thế lực thuộc Linh hoàng.","trangThaiMoc":"Ổn định dưới quyền Linh hoàng mới"}]},"capNhatToi":"@c1837","nguon":["@c1837"],"dacDiem":"Trực thuộc người nắm giữ ngôi Linh hoàng tại Thiên Linh Cảnh."},{"id":"yeu-toc-that-yeu","name":"Yêu tộc Thất Yêu","cn":"","type":"chung-toc","typeLabel":"Liên minh chủng tộc","diaBan":"Lãnh địa Thất Yêu","nhanVatChinh":[],"blurb":"Bảy nhánh Yêu tộc cùng bước vào giai đoạn chuẩn bị đối phó Ma kiếp.","detail":"Trong hơn trăm năm, lãnh địa Yêu tộc Thất Yêu có diễn biến chuẩn bị tương tự khu vực Nhân tộc, nhưng quá trình diễn ra chậm nên chưa gây hỗn loạn lớn.","trangThai":"Đang chuẩn bị Ma kiếp","capNhatToi":"@c1838","tabs":{"tienTrinh":[{"chuong":"@c1838","loai":"nhắc tới","importance":"normal","giaiDoan":"Chuẩn bị Ma kiếp","text":"Yêu tộc Thất Yêu triển khai công tác chuẩn bị đối phó Ma kiếp với cục diện tương tự Nhân tộc.","anchor":"Mà trong lãnh địa của Yêu tộc Thất Yêu, cục diện đại thể cũng tương tự như Nhân tộc.","trangThaiMoc":"Đang chuẩn bị"}]},"nguon":["@c1838"]},{"id":"lien-minh-nhan-yeu-luong-toc-va-cac-toc-phu-can","name":"Liên minh Nhân Yêu lưỡng tộc và các tộc phụ cận","cn":"","type":"lien-minh","typeLabel":"Liên minh các tộc","diaBan":"Khu vực Nhân Yêu lưỡng tộc và các vùng phụ cận","nhanVatChinh":[],"blurb":"Liên minh được hình thành từ minh ước giữa Nhân tộc, Yêu tộc và một số tộc phụ cận trong thời kỳ chuẩn bị đối phó ma kiếp. Đây là sự liên kết giữa nhiều tộc nhằm ứng phó biến cố sắp tới.","detail":"Nhân tộc và Yêu tộc cùng một số tộc phụ cận đã ký kết minh ước khi các bên chuẩn bị đối phó ma kiếp, qua đó hình thành một liên minh đa tộc. Hồ sơ chưa ghi nhận thêm về cơ cấu, hoạt động hay diễn biến cụ thể của liên minh sau khi minh ước được thiết lập. @c1841","nguonGoc":"Hình thành từ minh ước giữa Nhân Yêu lưỡng tộc và một số tộc phụ cận.","tonChi":"Phối hợp ứng phó tình thế trước ma kiếp.","quanHe":"Liên kết Nhân Yêu lưỡng tộc với một số tộc lân cận.","trangThai":"Đã ký kết minh ước","thanhVien":[],"lanhDaoMoc":[],"tabs":{"tienTrinh":[{"chuong":"@c1841","loai":"liên minh","importance":"major","giaiDoan":"Ký kết minh ước","text":"Nhân Yêu lưỡng tộc cùng một số tộc phụ cận ký kết minh ước trong thời kỳ chuẩn bị đối phó ma kiếp.","anchor":"Nhân Yêu lưỡng tộc chúng ta cùng mấy tộc phụ cận ký kết minh ước","trangThaiMoc":"Đã thành lập liên minh"}]},"capNhatToi":"@c1841","nguon":["@c1841"],"dacDiem":"Liên minh đa tộc gồm Nhân tộc, Yêu tộc và một số tộc phụ cận, được thiết lập trong bối cảnh chuẩn bị ứng phó ma kiếp.","congNang":["Liên kết Nhân Yêu lưỡng tộc và một số tộc phụ cận bằng minh ước để cùng chuẩn bị đối phó ma kiếp. @c1841"]},{"id":"luc-chi-toc","name":"Lục Chi tộc","cn":"","type":"chung-toc","typeLabel":"Chủng tộc","diaBan":"Hạp cốc trên Phong Nguyên đại lục","nhanVatChinh":["Đại trưởng lão Lục Chi tộc","Tu sĩ Hợp Thể trung kỳ Lục Chi tộc","Ba tu sĩ Hợp Thể sơ kỳ Lục Chi tộc"],"blurb":"Lục Chi tộc là một tiểu tộc ẩn thế, cư trú trong một hạp cốc trên Phong Nguyên đại lục. Tộc từng bị bạch y nữ tử và hắc bào đại hán xâm nhập, tổn thất hơn nghìn tộc nhân và phải giao Thánh Tinh Chi Hoa để tránh bị tiêu diệt.","detail":"Lục Chi tộc vốn là một tiểu tộc sống ẩn thế trong hạp cốc trên Phong Nguyên đại lục. Khi bạch y nữ tử và hắc bào đại hán xâm nhập, tộc mất hơn nghìn người; trước nguy cơ bị bạch y nữ tử tiêu diệt, họ buộc phải giao ra Thánh Tinh Chi Hoa để bảo toàn phần còn lại của tộc @c1842.","nguonGoc":"Tiểu tộc ẩn thế trên Phong Nguyên đại lục","lanhDaoHienThoi":"Đại trưởng lão Lục Chi tộc","quyMo":"Tiểu tộc","tranPhai":"Thánh Tinh Chi Hoa","trangThai":"Suy yếu sau khi mất hơn nghìn tộc nhân và bảo vật trấn tộc","thanhVien":[{"ten":"Đại trưởng lão Lục Chi tộc","chucVu":"Đại trưởng lão","tuChuong":"@c1842","trangThai":"đang tại vị"},{"ten":"Tu sĩ Hợp Thể trung kỳ Lục Chi tộc","chucVu":"Cường giả Hợp Thể trung kỳ","tuChuong":"@c1842","trangThai":"còn sống"},{"ten":"Ba tu sĩ Hợp Thể sơ kỳ Lục Chi tộc","chucVu":"Cường giả Hợp Thể sơ kỳ","tuChuong":"@c1842","trangThai":"còn sống"}],"lanhDaoMoc":[{"ten":"Đại trưởng lão Lục Chi tộc","tuChuong":"@c1842","denChuong":""}],"tabs":{"tienTrinh":[{"chuong":"@c1842","loai":"suy","importance":"major","giaiDoan":"Mất người và bảo vật","text":"Lục Chi tộc mất hơn nghìn tộc nhân và buộc phải giao Thánh Tinh Chi Hoa để tránh bị bạch y nữ tử tiêu diệt.","anchor":"ít nhất cũng không bị họa diệt tộc","trangThaiMoc":"Suy yếu"}]},"capNhatToi":"@c1842","nguon":["@c1842"],"dacDiem":"Tiểu tộc sống ẩn thế trong hạp cốc trên Phong Nguyên đại lục."},{"id":"luc-luong-thu-ve-dia-uyen","name":"Lực lượng thủ vệ Địa Uyên","cn":"","type":"to-chuc-quan-su","typeLabel":"Lực lượng thủ vệ","diaBan":"Đại thành trấn thủ Địa Uyên và lối ra vào Địa Uyên","nhanVatChinh":["Kim Phong","Tần trưởng lão","Thủ vệ Luyện Hư trung kỳ cầm đầu cửa thành"],"blurb":"Lực lượng phụ trách canh giữ đại thành, khoáng mạch và lối ra vào Địa Uyên.","detail":"Sau khi một kẻ thần thông cao cường cướp sạch quáng thạch quý hiếm tại khoáng mỏ, Kim Phong điều nhiều người chấp pháp xuống Địa Uyên truy tìm. Ông đồng thời tự mình trấn giữ lối ra vào duy nhất để ngăn thủ phạm thoát ra.","lanhDaoHienThoi":"Kim Phong","capBac":"Kim Phong giữ chức Thủ vệ thống lĩnh","quanHe":"Phối hợp với các tộc có quyền ra vào Địa Uyên theo ước định","trangThai":"Đang truy lùng kẻ cướp khoáng mỏ","thanhVien":[{"ten":"Kim Phong","chucVu":"Thủ vệ thống lĩnh","tuChuong":"@c1847","trangThai":"Đang giữ chức"},{"ten":"Tần trưởng lão","chucVu":"Người trấn thủ khoáng mạch","tuChuong":"@c1847","trangThai":"Đang hoạt động"},{"ten":"Thủ vệ Luyện Hư trung kỳ cầm đầu cửa thành","chucVu":"Cầm đầu thủ vệ cửa thành","tuChuong":"@c1847","trangThai":"Đang làm nhiệm vụ"}],"tabs":{"tienTrinh":[{"chuong":"@c1847","loai":"khai chiến","importance":"normal","giaiDoan":"Truy lùng kẻ cướp khoáng mỏ","text":"Lực lượng thủ vệ Địa Uyên được huy động truy tìm kẻ cướp, còn Kim Phong trực tiếp canh giữ cửa ra vào duy nhất.","anchor":"Nơi này là địa điểm duy nhất ra vào Địa Uyên.","trangThaiMoc":"Đang phong tỏa và truy lùng"}]},"capNhatToi":"@c1847","nguon":["@c1847"]},{"id":"chap-phap-doi","name":"Chấp pháp đội","cn":"","type":"doi-ngu","typeLabel":"Đội ngũ chấp pháp","diaBan":"Tầng thứ hai của Địa Uyên","nhanVatChinh":["Minh Chấn","Phi Linh nhân cánh xám","Nữ tử sừng trắng cánh tím","Bốn thành viên còn lại của chấp pháp đội"],"blurb":"Đội ngũ của Phi Linh tộc làm nhiệm vụ phong tỏa đường ra vào tầng hai của Địa Uyên.","detail":"Sáu tu sĩ Luyện Hư mai phục quanh cửa tầng hai để truy bắt kẻ đã cướp sạch khoáng mạch và có thể đang lẩn trốn tại các tầng sâu hơn.","quyMo":"Sáu tu sĩ Luyện Hư tại cửa tầng hai","thanhVien":[{"ten":"Minh Chấn","chucVu":"Thành viên dẫn đầu nhóm mai phục","tuChuong":"@c1848","trangThai":"đang làm nhiệm vụ"},{"ten":"Phi Linh nhân cánh xám","chucVu":"Thành viên","tuChuong":"@c1848","trangThai":"đang làm nhiệm vụ"},{"ten":"Nữ tử sừng trắng cánh tím","chucVu":"Thành viên duy trì kỷ luật","tuChuong":"@c1848","trangThai":"đang làm nhiệm vụ"},{"ten":"Bốn thành viên còn lại của chấp pháp đội","chucVu":"Thành viên","tuChuong":"@c1848","trangThai":"đang làm nhiệm vụ"}],"trangThai":"Đang phong tỏa tầng hai","tabs":{"tienTrinh":[{"chuong":"@c1848","loai":"nhắc tới","importance":"normal","giaiDoan":"Phong tỏa tầng hai","text":"Chấp pháp đội bố trí sáu tu sĩ Luyện Hư quanh cửa tầng hai để truy bắt kẻ cướp khoáng mạch.","anchor":"Hiện tại cả tầng hai đều đã bị chấp pháp đội phong tỏa","trangThaiMoc":"Phong tỏa đường ra vào tầng hai"}]},"capNhatToi":"@c1848","nguon":["@c1848"]},{"id":"ngan-lang-toc","name":"Ngân Lang Tộc","cn":"","type":"chung-toc","typeLabel":"Tộc quần","diaBan":"Nơi ẩn cư không được nêu rõ","nhanVatChinh":["Ngân Quang tiên tử","Ngân Nguyệt","Thiên Khuê Lang Vương"],"blurb":"Tộc quần ẩn cư bí mật và ít tiếp xúc với bên ngoài. Ngân Quang tiên tử là một trong hai tu sĩ Hợp Thể của tộc.","detail":"Do Ngân Lang Tộc ít giao tiếp với ngoại giới, tin tức về Ngân Nguyệt rất khó dò hỏi từ bên ngoài.","quyMo":"Có hai tu sĩ Hợp Thể","caoThuManhNhat":"Không rõ","soCaoThu":"Hai tu sĩ Hợp Thể","thanhVien":[{"ten":"Ngân Quang tiên tử","chucVu":"Tu sĩ Hợp Thể","tuChuong":"@c1874","trangThai":"đang thuộc tộc"},{"ten":"Ngân Nguyệt","chucVu":"Thành viên","tuChuong":"@c1874","trangThai":"đang thuộc tộc"}],"trangThai":"Ẩn cư","capNhatToi":"@c1874","tabs":{"tienTrinh":[{"chuong":"@c1874","loai":"nhắc tới","importance":"normal","giaiDoan":"Hé lộ lực lượng Hợp Thể","text":"Ngân Lang Tộc được xác nhận có hai tu sĩ Hợp Thể, trong đó có Ngân Quang tiên tử.","anchor":"Ngân Quang đạo hữu đây chính là một trong hai Hợp Thể kỳ tu sĩ của Ngân Lang Tộc","trangThaiMoc":"Ẩn cư và ít tiếp xúc ngoại giới"}]},"nguon":["@c1874"]},{"id":"lien-minh-cac-the-gia-tai-cu-diem-lung-gia","name":"Liên minh các thế gia tại cứ điểm Lũng gia","cn":"","type":"lien-minh","typeLabel":"Liên minh thế gia","diaBan":"Sơn mạch cứ điểm Lũng gia","nhanVatChinh":["Lũng gia lão tổ"],"blurb":"Liên minh gồm hơn mười thế gia do Lũng gia đứng ra liên kết để xây dựng cứ điểm chống Ma tộc.","detail":"Các thế gia có quy mô và xuất thân không đồng nhất, trong đó có những nhà không thuộc Chân Linh thế gia. Họ dựng hơn mười thành trì cùng nhiều pháp trận thành một hệ thống phòng thủ riêng.","nguonGoc":"Do Lũng gia liên kết hơn mười thế gia để chống Ma tộc","quyMo":"Hơn mười thế gia","lanhDaoHienThoi":"Lũng gia lão tổ","caoThuManhNhat":"Lũng gia lão tổ","thanhVien":[{"ten":"Lũng gia lão tổ","chucVu":"Chỗ dựa chiến lực chủ chốt","tuChuong":"@c1874","trangThai":"dự định rời cứ điểm"}],"trangThai":"Đang chuẩn bị chống Ma tộc","capNhatToi":"@c1874","tabs":{"tienTrinh":[{"chuong":"@c1874","loai":"liên minh","importance":"normal","giaiDoan":"Xây dựng cứ điểm phòng thủ","text":"Hơn mười thế gia do Lũng gia liên kết đã xây dựng một cứ điểm riêng để chống Ma tộc.","anchor":"Nơi đây chính là cứ điểm chống cự Ma tộc do Lũng gia liên hệ cùng mười mấy thế gia khác xây dựng.","trangThaiMoc":"Đang chuẩn bị cho Ma Kiếp"}]},"nguon":["@c1874"]},{"id":"ma-buc-toc","name":"Ma Bức Tộc","cn":"","type":"chung-toc","typeLabel":"Chủng tộc Ma tộc","diaBan":"Chưa rõ","nhanVatChinh":[],"blurb":"Một trong những tộc được xếp vào nhóm đầu tiên tiến vào Linh Giới theo lệnh của thánh tổ.","detail":"Mông Man xác nhận Ma Bức Tộc cùng Lôi Ngưu tộc thuộc lực lượng đầu tiên vượt giới. Chương chưa xác nhận trực tiếp Ma Bức Tộc và Huyết Bức nhất tộc là cùng một tên gọi.","quanHe":"Cùng Lôi Ngưu tộc thuộc nhóm đầu tiến vào Linh Giới","trangThai":"Đã tiến vào Linh Giới","capNhatToi":"@c1878","tabs":{"tienTrinh":[{"chuong":"@c1878","loai":"mở rộng/mất địa bàn","importance":"normal","giaiDoan":"Tiến vào Linh Giới","text":"Ma Bức Tộc được xếp cùng Lôi Ngưu tộc trong nhóm đầu tiên tiến vào Linh Giới.","anchor":"cùng Ma Bức Tộc các ngươi sẽ là nhóm đầu tiên tiến vào Linh Giới","trangThaiMoc":"Đã bắt đầu vượt giới"}]},"nguon":["@c1878"]},{"id":"huyet-buc-nhat-toc","name":"Huyết Bức nhất tộc","cn":"","type":"chung-toc","typeLabel":"Chủng tộc Ma tộc","diaBan":"Chưa rõ","nhanVatChinh":["Bức Liệt","Ngũ Bức"],"blurb":"Tộc của Bức Liệt và Ngũ Bức, nổi bật về tốc độ. Bức Liệt dự định dùng ưu thế này để quét sạch tu sĩ Nhân tộc quanh vùng.","detail":"Bức Liệt đại diện Huyết Bức nhất tộc lập cược với Mông Man, lấy số tu sĩ Nhân tộc bị tiêu diệt trong ba ngày làm kết quả phân thắng bại. Chương chưa xác nhận trực tiếp tên gọi này đồng nhất với Ma Bức Tộc.","caoThuManhNhat":"Bức Liệt","quanHe":"Cạnh tranh với Lôi Ngưu tộc trong việc săn giết tu sĩ Nhân tộc","trangThai":"Đang hoạt động tại Linh Giới","thanhVien":[{"ten":"Bức Liệt","chucVu":"Đại thống lĩnh","tuChuong":"@c1878","trangThai":"Đang hoạt động"},{"ten":"Ngũ Bức","chucVu":"Thuộc hạ của Đại thống lĩnh","tuChuong":"@c1878","trangThai":"Đang hoạt động"}],"capNhatToi":"@c1878","tabs":{"tienTrinh":[{"chuong":"@c1878","loai":"khai chiến","importance":"normal","giaiDoan":"Cược săn giết Nhân tộc","text":"Bức Liệt dự định dựa vào tốc độ của Huyết Bức nhất tộc để quét sạch tu sĩ Nhân tộc quanh vùng và lập cược với Lôi Ngưu tộc.","anchor":"Với tốc độ của Huyết Bức nhất tộc chúng ta, chỉ cần mấy ngày là có thể quét sạch mọi tu sĩ nhân tộc chung quanh","trangThaiMoc":"Đang săn giết tu sĩ Nhân tộc"}]},"nguon":["@c1878"]},{"id":"loi-nguu-toc","name":"Lôi Ngưu tộc","cn":"","type":"chung-toc","typeLabel":"Chủng tộc Ma tộc","diaBan":"Chưa rõ","nhanVatChinh":["Mông Man"],"blurb":"Chủng tộc Ma tộc có thành viên mang hình cự ngưu xanh với hoa văn bạc. Tộc này nhận lệnh của thánh tổ và thuộc nhóm đầu tiên tiến vào Linh Giới.","detail":"Mông Man cho biết tộc nhân Lôi Ngưu tộc đã phá giới tiến vào Linh Giới. Hắn đại diện tộc chấp nhận cuộc cược săn giết tu sĩ Nhân tộc với Bức Liệt.","caoThuManhNhat":"Mông Man","quanHe":"Cạnh tranh với Huyết Bức nhất tộc và cùng Ma Bức Tộc tiến vào Linh Giới","trangThai":"Đã phá giới tiến vào Linh Giới","thanhVien":[{"ten":"Mông Man","chucVu":"Vai trò chưa rõ","tuChuong":"@c1878","trangThai":"Đang hoạt động"}],"capNhatToi":"@c1878","tabs":{"tienTrinh":[{"chuong":"@c1878","loai":"mở rộng/mất địa bàn","importance":"normal","giaiDoan":"Phá giới tiến vào","text":"Lôi Ngưu tộc nhận lệnh của thánh tổ và đã bắt đầu phá giới tiến vào Linh Giới.","anchor":"Hiện tại của ta tộc nhân cũng đã phá giới mà vào","trangThaiMoc":"Đã tiến vào Linh Giới"}]},"nguon":["@c1878"]},{"id":"dai-quan-ma-toc-vuot-gioi","name":"Đại quân Ma tộc vượt giới","cn":"","aliases":[],"type":"quan-doi","typeLabel":"Đại quân xâm nhập","diaBan":"Linh Giới","nguonGoc":"Ma tộc vượt giới tiến vào Linh Giới.","tonChi":"Triển khai lực lượng Ma tộc quy mô lớn tại Linh Giới.","quyMo":"Hàng trăm cự tháp, mỗi tháp chứa hơn trăm chiến chu cùng nhiều giáp sĩ và ma nhân.","tranPhai":["Cự tháp hình tam giác","Chiến chu màu đen"],"trangThai":"Đã hàng lâm và bắt đầu triển khai","nhanVatChinh":["Ma tộc giáp sĩ có cánh","Ma nhân hai đầu bốn tay"],"thanhVien":[{"ten":"Ma tộc giáp sĩ có cánh","chucVu":"Giáp sĩ","tuChuong":"@c1879","trangThai":"Đang hoạt động"},{"ten":"Ma nhân hai đầu bốn tay","chucVu":"Ma nhân chiến đấu","tuChuong":"@c1879","trangThai":"Đang hoạt động"}],"blurb":"Đại quân Ma tộc vượt giới là lực lượng xâm nhập quy mô lớn của Ma tộc tiến vào Linh Giới. Lực lượng này sử dụng hàng trăm cự tháp để hàng lâm, sau đó triển khai chiến chu, giáp sĩ có cánh và đông đảo ma nhân chiến đấu.","detail":"Sau các đợt ma thú tiên phong, hàng trăm cự tháp hình tam giác của Ma tộc hàng lâm xuống Linh Giới, liên tục triển khai chiến chu và quân sĩ. Sự xuất hiện của đại quân đánh dấu cuộc xâm nhập có tổ chức của Ma tộc vào Linh Giới và trực tiếp mở màn giao chiến tại đây. @c1879","capNhatToi":"@c1879","tabs":{"tienTrinh":[{"chuong":"@c1879","loai":"khai chiến","importance":"major","giaiDoan":"Vượt giới hàng lâm","text":"Đại quân Ma tộc dùng hàng trăm cự tháp tiến vào Linh Giới rồi triển khai chiến chu, giáp sĩ có cánh và đông đảo ma nhân.","anchor":"Tiếp theo từ bên trong bắn ra hàng trăm ma vật vô cùng khổng lồ","trangThaiMoc":"Đã hàng lâm Linh Giới"}]},"nguon":["@c1879"],"uyLuc":"Quy mô mạnh nhất đã thể hiện là hàng trăm cự tháp đồng thời hàng lâm Linh Giới, triển khai một đại quân gồm nhiều chiến chu và đông đảo quân sĩ. @c1879","dacDiem":"Lực lượng xâm nhập có tổ chức, lấy hàng trăm cự tháp hình tam giác làm phương tiện vượt giới và triển khai quân; thành phần gồm chiến chu, giáp sĩ có cánh cùng đông đảo ma nhân chiến đấu.","congNang":["Sử dụng hàng trăm cự tháp để vượt giới, đưa lực lượng Ma tộc tiến vào Linh Giới. @c1879","Từ các cự tháp triển khai chiến chu, giáp sĩ có cánh và đông đảo ma nhân chiến đấu. @c1879"]},{"id":"toc-tam-nhan-ma-mang-cua-ve-huynh","name":"Tộc Tam Nhãn Ma Mãng của Vệ huynh","cn":"","aliases":[],"type":"ma-thu-toc","typeLabel":"Tộc ma mãng","diaBan":"Linh Giới","lanhDaoHienThoi":"Vệ huynh","quyMo":"Khoảng năm sáu nghìn Tam Nhãn Ma Mãng.","caoThuManhNhat":"Bổn mạng thần mãng của Vệ huynh","quanHe":"Liên thủ tạm thời với Trùng tộc của Hồn Châu.","trangThai":"Đang hành động tại Linh Giới","nhanVatChinh":["Vệ huynh","Bổn mạng thần mãng của Vệ huynh"],"thanhVien":[{"ten":"Vệ huynh","chucVu":"Thủ lĩnh","tuChuong":"@c1879","trangThai":"Đang lãnh đạo"},{"ten":"Bổn mạng thần mãng của Vệ huynh","chucVu":"Bổn mạng thần mãng","tuChuong":"@c1879","trangThai":"Đang hoạt động"}],"lanhDaoMoc":[{"ten":"Vệ huynh","tuChuong":"@c1879","denChuong":""}],"blurb":"Lực lượng gồm khoảng năm sáu nghìn Tam Nhãn Ma Mãng do Vệ huynh thống lĩnh. Sau khi xuất hiện tại Linh Giới, họ liên thủ với trùng tộc của Hồn Châu.","detail":"Đàn Tam Nhãn Ma Mãng đi cùng bổn mạng thần mãng đã tiến giai của Vệ huynh. Sau khi đạt thỏa thuận với Hồn Châu, toàn bộ đàn mãng xà đồng loạt độn xuống đất.","capNhatToi":"@c1879","tabs":{"tienTrinh":[{"chuong":"@c1879","loai":"liên minh","importance":"normal","giaiDoan":"Phối hợp với trùng tộc","text":"Tộc Tam Nhãn Ma Mãng liên thủ với trùng tộc của Hồn Châu rồi đồng loạt độn xuống đất.","anchor":"Đám Tam Nhãn Cự Mãng vây quanh ào ào kích bắn xuống mặt đất","trangThaiMoc":"Liên thủ tạm thời"}]},"nguon":["@c1879"]},{"id":"trung-toc-cua-hon-chau","name":"Trùng tộc của Hồn Châu","cn":"","aliases":[],"type":"ma-trung-toc","typeLabel":"Trùng tộc","diaBan":"Linh Giới","lanhDaoHienThoi":"Hồn Châu","quyMo":"Khoảng bảy tám chục vạn ma trùng.","quanHe":"Liên thủ tạm thời với Tộc Tam Nhãn Ma Mãng của Vệ huynh.","trangThai":"Đang hành động tại Linh Giới","nhanVatChinh":["Hồn Châu","Quái trùng khổng lồ của Hồn Châu"],"thanhVien":[{"ten":"Hồn Châu","chucVu":"Thủ lĩnh","tuChuong":"@c1879","trangThai":"Đang lãnh đạo"},{"ten":"Quái trùng khổng lồ của Hồn Châu","chucVu":"Tọa kỵ","tuChuong":"@c1879","trangThai":"Đang hoạt động"}],"lanhDaoMoc":[{"ten":"Hồn Châu","tuChuong":"@c1879","denChuong":""}],"blurb":"Trùng tộc do Hồn Châu thống lĩnh, gồm khoảng bảy tám chục vạn ma trùng hình bọ ngựa. Lực lượng này liên thủ với đàn Tam Nhãn Ma Mãng trong hành trình tại Linh Giới.","detail":"Theo lệnh Hồn Châu, số lượng ma trùng khổng lồ tụ thành trùng hải và đuổi theo lực lượng của Vệ huynh xuống mặt đất.","capNhatToi":"@c1879","tabs":{"tienTrinh":[{"chuong":"@c1879","loai":"liên minh","importance":"normal","giaiDoan":"Triệu tập trùng hải","text":"Hồn Châu triệu tập khoảng bảy tám chục vạn ma trùng và dẫn chúng phối hợp với lực lượng Tam Nhãn Ma Mãng.","anchor":"Số lượng chừng bảy tám chục vạn","trangThaiMoc":"Liên thủ tạm thời"}]},"nguon":["@c1879"]},{"id":"gia-luan-chien-ma","name":"Già Luân Chiến Ma","cn":"","type":"quan-doi","typeLabel":"Lực lượng tinh nhuệ Ma tộc","diaBan":"Khu vực quanh Thiên Uyên Thành","nhanVatChinh":["Huyết Quang"],"blurb":"Một trong ba lực lượng tinh nhuệ được Huyết Quang điều đi càn quét các cứ điểm Nhân tộc quanh Thiên Uyên Thành.","detail":"Già Luân Chiến Ma nhận nhiệm vụ phối hợp với Huyết Quang Tinh Vệ và Vạn Tượng Ma Kỵ tiêu diệt toàn bộ các cứ điểm Nhân tộc còn lại trong khu vực.","lanhDaoHienThoi":"Huyết Quang","trangThai":"Đang hiện diện trong đại quân công thành Ỷ Thiên thành","quanHe":"Phối hợp với Huyết Quang Tinh Vệ và Vạn Tượng Ma Kỵ.","tabs":{"tienTrinh":[{"chuong":"@c1886","loai":"mở rộng/mất địa bàn","importance":"normal","giaiDoan":"Chiến dịch càn quét cứ điểm","text":"Già Luân Chiến Ma được điều động tham gia chiến dịch quét sạch các cứ điểm Nhân tộc quanh Thiên Uyên Thành.","anchor":"hãy phái ra Già Luân Chiến Ma, Huyết Quang Tinh Vệ cùng Vạn Tượng Ma Kỵ"},{"chuong":"@c1899","loai":"nhắc tới","importance":"normal","giaiDoan":"Lộ diện ngoài thành","text":"Vài nghìn Gia Luân chiến ma xuất hiện trong đội hình Ma tộc và được nhận diện là lực lượng đặc biệt nguy hiểm.","anchor":"đám chiến ma này cho dù trong các lực lượng tinh nhuệ của ma tộc cũng là bài danh trong năm thứ hạng đầu","trangThaiMoc":"Hiện diện tại chiến trường"}]},"capNhatToi":"@c1886","nguon":["@c1886","@c1899"],"aliases":["Già Luân chiến ma"]},{"id":"huyet-quang-tinh-ve","name":"Huyết Quang Tinh Vệ","cn":"","type":"than-ve","typeLabel":"Đội thân vệ Ma tộc","diaBan":"Khu vực quanh Thiên Uyên Thành","nhanVatChinh":["Huyết Quang"],"blurb":"Đội vệ binh thân tín trực tiếp bảo vệ Huyết Quang. Dù giữ vai trò hộ vệ chủ soái, đội vẫn được điều đi càn quét cứ điểm vì một dụng ý chưa được tiết lộ.","detail":"Huyết Quang bác bỏ lời can gián của thuộc hạ và kiên quyết phái Huyết Quang Tinh Vệ rời bên cạnh mình để tham gia chiến dịch càn quét.","lanhDaoHienThoi":"Huyết Quang","tonChi":"Bảo vệ và chấp hành mệnh lệnh trực tiếp của Huyết Quang.","trangThai":"Được điều khỏi chủ soái để càn quét cứ điểm","thanhVien":[{"ten":"Huyết Quang","chucVu":"Chủ nhân và người chỉ huy","tuChuong":"@c1886","trangThai":"đang lãnh đạo"}],"tabs":{"tienTrinh":[{"chuong":"@c1886","loai":"mở rộng/mất địa bàn","importance":"normal","giaiDoan":"Rời vị trí hộ vệ","text":"Huyết Quang Tinh Vệ được điều rời khỏi Huyết Quang để tham gia càn quét các cứ điểm Nhân tộc lân cận.","anchor":"Huyết Quang Tinh Vệ kia lại chính là đội vệ binh thân tín bên cạnh Đại Nhân"}]},"capNhatToi":"@c1886","nguon":["@c1886"]},{"id":"van-tuong-ma-ky","name":"Vạn Tượng Ma Kỵ","cn":"","type":"quan-doi","typeLabel":"Lực lượng tinh nhuệ Ma tộc","diaBan":"Khu vực quanh Thiên Uyên Thành","nhanVatChinh":["Huyết Quang"],"blurb":"Đội quân tinh nhuệ Ma tộc được huy động trong chiến dịch đánh chiếm các cứ điểm Nhân tộc phụ cận Thiên Uyên Thành.","detail":"Vạn Tượng Ma Kỵ phối hợp với Già Luân Chiến Ma và Huyết Quang Tinh Vệ để quét sạch những cứ điểm còn lại theo mệnh lệnh của Huyết Quang.","lanhDaoHienThoi":"Huyết Quang","trangThai":"Đang tham chiến","quanHe":"Phối hợp với Già Luân Chiến Ma và Huyết Quang Tinh Vệ.","tabs":{"tienTrinh":[{"chuong":"@c1886","loai":"mở rộng/mất địa bàn","importance":"normal","giaiDoan":"Chiến dịch càn quét cứ điểm","text":"Vạn Tượng Ma Kỵ được huy động để quét sạch các cứ điểm Nhân tộc quanh Thiên Uyên Thành.","anchor":"Huyết Quang Tinh Vệ cùng Vạn Tượng Ma Kỵ càn quét hết tất cả cứ điểm"},{"chuong":"@c1902","loai":"khai chiến","importance":"normal","giaiDoan":"Làm mồi nhử","text":"Một bộ phận Vạn Tượng Ma Kỵ được hai Ma Tôn dẫn đi công thành nhằm nhử tu sĩ Hợp Thể của Ỷ Thiên thành ra ngoài.","anchor":"vừa bắt đầu tựa như mới vừa rồi công thành một loại, chỉ dẫn theo một phần nhỏ vạn tượng ma kỵ hiện thân","trangThaiMoc":"Tham gia kế dụ địch"}]},"capNhatToi":"@c1886","nguon":["@c1886","@c1902"],"aliases":["Vạn trượng ma kỵ","Vạn Tượng Ma Kỵ"]},{"id":"tu-dai-tong-mon","name":"Tứ Đại Tông Môn","cn":"","type":"lien-minh","typeLabel":"Liên minh tông môn Nhân tộc","diaBan":"Ỷ Thiên Thành","nhanVatChinh":["Hai Thái Thượng trưởng lão của Tứ Đại Tông Môn"],"blurb":"Tứ Đại Tông Môn là liên minh gồm bốn tông môn Nhân tộc, có vai trò xây dựng và trấn giữ Ỷ Thiên Thành. Vốn thuộc nhóm thế lực lớn nhất của Nhân tộc, liên minh bị suy yếu nghiêm trọng sau khi hai Thái Thượng trưởng lão vẫn lạc trong cuộc tiến công của Ma tộc.","detail":"Tứ Đại Tông Môn do bốn tông môn Nhân tộc hợp thành, cùng xây dựng và trấn giữ Ỷ Thiên Thành. Khi đại quân Ma tộc tiến công, hơn mười cao thủ đối phương dùng mưu dụ các Thái Thượng trưởng lão ra ngoài rồi đánh lén. Hai Thái Thượng trưởng lão vẫn lạc khiến chiến lực cao cấp của liên minh giảm sút, tổn thất buộc họ phải cầu viện Thiên Uyên Thành. @c1886","quyMo":"Thuộc nhóm mười thế lực lớn nhất Nhân tộc.","caoThuManhNhat":"Các Thái Thượng trưởng lão","trangThai":"Đang phòng thủ Ỷ Thiên Thành và cầu viện","thanhVien":[{"ten":"Hai Thái Thượng trưởng lão của Tứ Đại Tông Môn","chucVu":"Thái Thượng trưởng lão","tuChuong":"@c1886","trangThai":"đã vẫn lạc"}],"tabs":{"tienTrinh":[{"chuong":"@c1886","loai":"khai chiến","importance":"major","giaiDoan":"Phòng thủ Ỷ Thiên Thành","trangThaiMoc":"Hai Thái Thượng trưởng lão vẫn lạc","text":"Tứ Đại Tông Môn chịu tổn thất lớn khi hai Thái Thượng trưởng lão bị Ma tộc dụ ra ngoài đánh lén và phải cầu viện Thiên Uyên Thành.","anchor":"Thế lực liên thủ của Tứ Đại Tông Môn Ỷ Thiên Môn trong Nhân tộc chúng ta mà nói có thể xếp trong nhóm mười thế lực lớn nhất"}]},"capNhatToi":"@c1886","nguon":["@c1886"],"dacDiem":"Liên minh bốn tông môn lớn của Nhân tộc, gắn với việc xây dựng và trấn giữ Ỷ Thiên Thành."},{"id":"khinh-thien-mon","name":"Khinh Thiên Môn","cn":"","type":"tong-mon","typeLabel":"Tông môn Nhân tộc","diaBan":"Khu vực Ỷ Thiên Thành","nhanVatChinh":[],"blurb":"Một tông môn Nhân tộc thuộc tuyến phòng thủ quanh Ỷ Thiên Thành. Thành trì của tông môn đang bị đại quân Ma tộc liên hợp tiến công.","detail":"Khinh Thiên Môn từng đẩy lùi một đợt tiến công nhưng sau đó tiếp tục nằm trong nhóm các tông môn bị đại quân Ma tộc đánh mạnh và phải cầu viện Thiên Uyên Thành.","trangThai":"Đang bị đại quân Ma tộc tiến công","tabs":{"tienTrinh":[{"chuong":"@c1886","loai":"khai chiến","importance":"normal","giaiDoan":"Phòng thủ thành trì","trangThaiMoc":"Bị quân Ma tộc liên hợp tiến công","text":"Khinh Thiên Môn nằm trong số các tông môn có thành trì bị đại quân Ma tộc tấn công liên hợp.","anchor":"Ma tộc lại phái ra đại quân tấn công liên hợp Thành trì của Tứ Đại Tông Môn trong đó có Khinh Thiên Môn"}]},"capNhatToi":"@c1886","nguon":["@c1886"]},{"id":"thien-hoang-tong","name":"Thiên Hoàng Tông","cn":"","type":"tong-mon","typeLabel":"Tông môn Nhân tộc","diaBan":"Khu vực Ỷ Thiên Thành","nhanVatChinh":["Lâm Loan tiên tử"],"blurb":"Một tông môn Nhân tộc được nhắc đến trong nhóm thế lực đang chống lại cuộc tiến công liên hợp của đại quân Ma tộc.","detail":"Thiên Hoàng Tông cùng Khinh Thiên Môn và các tông môn khác lâm vào thế nguy cấp, khiến Thiên Uyên Thành phải cân nhắc đưa quân cứu viện.","trangThai":"Tham gia phòng thủ Ỷ Thiên thành","tabs":{"tienTrinh":[{"chuong":"@c1886","loai":"khai chiến","importance":"normal","giaiDoan":"Phòng thủ thành trì","trangThaiMoc":"Bị quân Ma tộc liên hợp tiến công","text":"Thiên Hoàng Tông nằm trong nhóm thế lực Nhân tộc đang chịu cuộc tiến công của đại quân Ma tộc.","anchor":"trong đó có Khinh Thiên Môn cùng Thiên Hoàng Tông"},{"chuong":"@c1902","loai":"nhắc tới","importance":"bridge","giaiDoan":"Tham gia giữ thành","text":"Thiên Hoàng tông có thái thượng trưởng lão Lâm Loan tham gia chủ trì phòng thủ Ỷ Thiên thành.","anchor":"Tên này Thiên hoàng tông thái thượng trưởng lão vừa mở miệng, thanh âm lại không ngờ uyển chuyển dễ nghe êm tai","trangThaiMoc":"Đang tham gia phòng thủ"}]},"capNhatToi":"@c1886","nguon":["@c1886","@c1902"],"thanhVien":[{"ten":"Lâm Loan tiên tử","chucVu":"Thái thượng trưởng lão","tuChuong":"@c1902","trangThai":"Đang tại vị"}]},{"id":"y-thien-mon","name":"Ỷ Thiên Môn","cn":"","type":"tong-mon","typeLabel":"Thế lực Nhân tộc","diaBan":"Ỷ Thiên Thành","nhanVatChinh":[],"blurb":"Thế lực Nhân tộc được nhắc trong mạch mô tả liên minh Tứ Đại Tông Môn tại Ỷ Thiên Thành. Liên quân này thuộc nhóm mười thế lực lớn nhất Nhân tộc.","detail":"Ỷ Thiên Môn gắn với tuyến phòng thủ tại Ỷ Thiên Thành, nơi đang lâm nguy sau khi chiến lực cao cấp của Tứ Đại Tông Môn bị tổn thất.","quyMo":"Nằm trong liên quân thuộc nhóm mười thế lực lớn nhất Nhân tộc.","trangThai":"Đang đối phó cuộc tiến công của Ma tộc","tabs":{"tienTrinh":[{"chuong":"@c1886","loai":"khai chiến","importance":"normal","giaiDoan":"Khủng hoảng Ỷ Thiên Thành","trangThaiMoc":"Tuyến phòng thủ suy yếu","text":"Ỷ Thiên Môn được nhắc trong liên quân Tứ Đại Tông Môn đang chống lại cuộc tiến công của Ma tộc tại Ỷ Thiên Thành.","anchor":"Thế lực liên thủ của Tứ Đại Tông Môn Ỷ Thiên Môn trong Nhân tộc chúng ta"}]},"capNhatToi":"@c1886","nguon":["@c1886"]},{"id":"thien-vuong-tong","name":"Thiên Vương Tông","type":"tong-mon","typeLabel":"Tông môn","diaBan":"Khu vực Ỷ Thiên Thành","nhanVatChinh":["Lâm tiên tử"],"blurb":"Tông môn có Lâm tiên tử, hảo hữu lâu năm của Ngân Quang tiên tử, đang ở tuyến Ỷ Thiên Thành.","detail":"Thiên Vương Tông là tông môn có tu sĩ đang trấn giữ tại Ỷ Thiên Thành. Lâm tiên tử thuộc tông phái này là hảo hữu kết giao nhiều năm của Ngân Quang tiên tử, trở thành lý do chính Ngân Quang tự nguyện cứu viện.","nguon":["@c1887"]},{"id":"co-ma-nhat-toc","name":"Cổ ma nhất tộc","type":"chung-toc","typeLabel":"Chủng tộc","diaBan":"Ma giới","nhanVatChinh":[],"blurb":"Chủng tộc chính của Ma tộc, phải huy động đại quân Ma thú cấp thấp từ Ma giới sang Linh giới, quá trình hao phí nhiều tinh lực.","detail":"Cổ ma nhất tộc thu thập, hàng phục và đưa số lượng lớn Ma thú cấp thấp từ Ma giới vượt giới diện sang Linh giới. Hàn Lập nhận định quá trình này hao phí không ít tinh lực, nên nguồn Ma thú của đối phương không nhất thiết vô tận.","tabs":{"tienTrinh":[{"chuong":"@c1887","loai":"nhắc tới","importance":"normal","giaiDoan":"Hàn Lập phân tích gánh nặng hậu cần","text":"Hàn Lập nhận định việc thu phục và vận chuyển vô số Ma thú cấp thấp từ Ma giới cũng hao phí Cổ ma nhất tộc không ít tinh lực.","anchor":"chỉ e cũng hao phí Cổ ma nhất tộc không ít tinh lực"}]},"nguon":["@c1887"]},{"id":"thien-quy-mon","name":"Thiên Quỷ môn","cn":"","type":"ma-dao","typeLabel":"Thế lực ma đạo","diaBan":"","nhanVatChinh":[],"blurb":"Thế lực ma đạo có truyền thừa tu ma liên quan tới tử mẫu Chân Ma Phiên.","detail":"Ngân Quang Tiên Tử nhận ra danh hiệu Thiên Quỷ môn khi Lam tôn giả triển khai tử mẫu Chân Ma Phiên. Quan hệ cụ thể giữa hắn và thế lực này chưa được nói rõ.","tranPhai":["Tử mẫu Chân Ma Phiên"],"trangThai":"không rõ","tabs":{"tienTrinh":[{"chuong":"@c1892","loai":"nhắc tới","importance":"bridge","giaiDoan":"Lộ truyền thừa","text":"Ngân Quang Tiên Tử nhận ra truyền thừa tu ma Thiên Quỷ môn qua tử mẫu Chân Ma Phiên.","anchor":"Tu ma Thiên Quỷ môn, tử mẫu Chân Ma Phiên","trangThaiMoc":"Được nhắc tới"}]},"capNhatToi":"@c1892","nguon":["@c1892"]},{"id":"dai-quan-ma-toc-ngoai-y-thien-thanh","name":"Đại quân Ma tộc ngoài Ỷ Thiên thành","cn":"","type":"quan-doi","typeLabel":"Thế lực quân sự","diaBan":"Bên ngoài Ỷ Thiên thành","nhanVatChinh":["Trọc đầu Ma tộc","Lãnh Nhận"],"blurb":"Đại quân Ma tộc tập kết bên ngoài Ỷ Thiên thành. Lực lượng này có hơn vạn chiến chu màu đen cùng vô số kỵ sĩ cưỡi ma thú mặc giáp.","detail":"Đại quân bao vây một phía tường thành với quy mô lớn, khiến Hàn Lập và Ngân Quang tiên tử vừa tới nơi lập tức trở nên nghiêm nghị.","quyMo":"Hơn vạn chiến chu và vô số kỵ sĩ Ma tộc cưỡi ma thú mặc giáp","trangThai":"Đồn trú và chuẩn bị tổng công kích","tabs":{"tienTrinh":[{"chuong":"@c1898","loai":"khai chiến","importance":"normal","giaiDoan":"Tập kết ngoài thành","text":"Đại quân Ma tộc tập trung hơn vạn chiến chu cùng vô số kỵ sĩ ma thú bên ngoài Ỷ Thiên thành.","anchor":"đang lơ lửng hơn vạn con hắc sắc cự chu","trangThaiMoc":"Đang tập kết ngoài thành"},{"chuong":"@c1902","loai":"khai chiến","importance":"normal","giaiDoan":"Chuẩn bị tổng công kích","text":"Lực lượng vừa công thành chỉ là một bộ phận nhỏ, trong khi đại quân chủ lực vẫn đồn trú tại Trung Kiếm sơn mạch và chờ thời cơ.","anchor":"Đại quân chân chính, còn trú đóng ở cách nơi này vạn dặm xa, đồn trú trong trung kiếm sơn mạch.","trangThaiMoc":"Chủ lực chưa phát động tổng công kích"}]},"capNhatToi":"@c1898","nguon":["@c1898","@c1902"],"aliases":["Đại quân Ma tộc ngoài Ỷ Thiên thành"]},{"id":"van-truong-ma-ky","name":"Vạn Trượng Ma Kỵ","cn":"","aliases":["Vạn trượng ma kỵ","Vạn Tượng Ma Kỵ"],"type":"quan-doi","typeLabel":"Ma tộc kỵ quân","diaBan":"Chiến trường ngoài Ỷ Thiên thành","nhanVatChinh":[],"blurb":"Kỵ quân tinh nhuệ của Ma tộc với quân số hơn mười vạn, có khả năng cộng sinh với tọa kỵ và kết đại trận liên thủ.","detail":"Phần lớn thành viên có tu vi Kim Đan hoặc Nguyên Anh. Trong cuộc công thành Ỷ Thiên thành, đội quân tổ chức nhiều trận hình phức tạp và bắt đầu áp sát phòng tuyến.","quyMo":"Hơn mười vạn kỵ sĩ","capBac":"Lực lượng tinh nhuệ Ma tộc","tranPhai":"Ma tộc đại trận vạn kỵ","trangThai":"Đang tham gia công thành Ỷ Thiên thành","capNhatToi":"@c1899","tabs":{"tienTrinh":[{"chuong":"@c1899","loai":"khai chiến","importance":"normal","giaiDoan":"Kết trận áp sát thành","text":"Hơn mười vạn Vạn Trượng Ma Kỵ kết thành nhiều đội hình và tiến về phòng tuyến Ỷ Thiên thành.","anchor":"Vạn Trượng ma kỵ ở đây có hơn mười vạn","trangThaiMoc":"Tham gia công thành"}]},"nguon":["@c1899"]},{"id":"luc-luong-phong-thu-y-thien-thanh","name":"Lực lượng phòng thủ Ỷ Thiên thành","cn":"","aliases":[],"type":"quan-doi","typeLabel":"Nhân tộc thủ quân","diaBan":"Ỷ Thiên thành","nhanVatChinh":[],"blurb":"Quân phòng thủ Nhân tộc trấn giữ Ỷ Thiên thành bằng lực sĩ, khí cụ tầm xa, pháp trận và đội ngũ chấp pháp.","detail":"Lực lượng này tiêu diệt hàng vạn ma thú cấp thấp và dùng lôi trận đánh trọng thương các cự thú. Khi phòng tuyến bị phá, chấp pháp tu sĩ đàn áp binh sĩ tháo chạy, còn các tổ trận pháp khẩn cấp dùng đá lớn bịt kín lỗ hổng.","quyMo":"Không rõ","tranPhai":"Pháp trận phòng hộ Ỷ Thiên thành và Đại trận màu lam","trangThai":"Phòng tuyến bị phá nhiều nơi nhưng vẫn tiếp tục chống giữ","capNhatToi":"@c1899","tabs":{"tienTrinh":[{"chuong":"@c1899","loai":"khai chiến","importance":"normal","giaiDoan":"Chống đợt tổng công kích","text":"Thủ quân dùng hỏa lực và pháp trận chống trả Ma tộc, đàn áp tình trạng tháo chạy rồi khẩn cấp gia cố những đoạn tường bị phá.","anchor":"Nhất thời, toàn bộ phòng tuyến của Ỷ Thiên thành liền trở nên lảo đảo muốn ngã","trangThaiMoc":"Phòng tuyến lâm nguy"}]},"nguon":["@c1899"]},{"id":"cuong-cot-bo","name":"Cương Cốt bộ","cn":"","type":"bo-toc","typeLabel":"Bộ tộc Ma tộc","diaBan":"Ma giới","nhanVatChinh":["Thiết Long"],"blurb":"Một bộ tộc thuộc Ma tộc, có Thiết Long là Tôn giả Hợp Thể hậu kỳ đỉnh giai.","detail":"Thiết Long của Cương Cốt bộ tham gia mai phục hai viện binh Nhân tộc bên ngoài Ỷ Thiên Thành.","caoThuManhNhat":"Thiết Long","thanhVien":[{"ten":"Thiết Long","chucVu":"Tôn giả","tuChuong":"@c1901","trangThai":"đang hoạt động"}],"trangThai":"đang hoạt động","capNhatToi":"@c1901","tabs":{"tienTrinh":[{"chuong":"@c1901","loai":"nhắc tới","importance":"bridge","giaiDoan":"Lộ diện thành viên","text":"Thiết Long công khai mình là Tôn giả của Cương Cốt bộ.","anchor":"Lão phu là thánh tộc cương cốt bộ xưng là Thiết Long","trangThaiMoc":"đang hoạt động"}]},"nguon":["@c1901"]},{"id":"bang-linh-bo","name":"Băng Linh bộ","cn":"","type":"bo-toc","typeLabel":"Bộ tộc Ma tộc","diaBan":"Ma giới","nhanVatChinh":["Phi Nha"],"blurb":"Một bộ tộc thuộc Ma tộc, có Phi Nha là Tôn giả Hợp Thể trung kỳ.","detail":"Phi Nha của Băng Linh bộ sở trường kỳ hàn và phi đao, tham gia phục kích Hàn Lập bên ngoài Ỷ Thiên Thành.","caoThuManhNhat":"Phi Nha","thanhVien":[{"ten":"Phi Nha","chucVu":"Tôn giả","tuChuong":"@c1901","trangThai":"đang hoạt động"}],"trangThai":"đang hoạt động","capNhatToi":"@c1901","tabs":{"tienTrinh":[{"chuong":"@c1901","loai":"nhắc tới","importance":"bridge","giaiDoan":"Lộ diện thành viên","text":"Phi Nha được xác nhận là Tôn giả thuộc Băng Linh bộ.","anchor":"còn vị này là băng linh bộ đích Phi Nha","trangThaiMoc":"đang hoạt động"}]},"nguon":["@c1901"]},{"id":"bon-dai-tong-mon-tai-y-thien-thanh","name":"Bốn đại tông môn tại Ỷ Thiên Thành","cn":"","type":"lien-minh","typeLabel":"Liên minh tông môn","diaBan":"Ỷ Thiên Thành","nhanVatChinh":["Thanh Long thượng nhân","Lâm Loan tiên tử"],"blurb":"Liên minh bốn đại tông môn tham gia xây dựng và trấn thủ Ỷ Thiên Thành. Các tông môn đã dốc lượng lớn vật liệu, tập trung hơn mười tông sư nghiên cứu Cửu Dương Cương Nhật Tuyệt Trận để chuẩn bị cho Ma Kiếp.","detail":"Bốn đại tông môn là lực lượng đứng sau hệ thống phòng thủ trọng yếu của Ỷ Thiên Thành. Sau khi Hàn Lập và Ngân Quang tiên tử đến viện trợ, phe trấn thủ có bốn chiến lực Hợp Thể để phối hợp với tuyệt trận đối phó các Ma Tôn.","quyMo":"Hơn mười tông sư từng tham gia nghiên cứu trận pháp hộ thành.","thanhVien":[{"ten":"Thanh Long thượng nhân","chucVu":"Đại trưởng lão trấn thủ","tuChuong":"@c1903","trangThai":"đang hoạt động"},{"ten":"Lâm Loan tiên tử","chucVu":"Tu sĩ Hợp Thể trấn thủ","tuChuong":"@c1903","trangThai":"đang hoạt động"}],"trangThai":"Đang trấn thủ Ỷ Thiên Thành","capNhatToi":"@c1903","tabs":{"tienTrinh":[{"chuong":"@c1903","loai":"nhắc tới","importance":"normal","giaiDoan":"Chuẩn bị chống Ma Kiếp","text":"Bốn đại tông môn dốc nguồn lực và tập trung hơn mười tông sư nghiên cứu tuyệt trận bảo vệ Ỷ Thiên Thành.","anchor":"pháp trận này là của bốn đại tông môn chúng ta tập trung hơn mười tông sư","trangThaiMoc":"Đang tổ chức phòng thủ Ỷ Thiên Thành"}]},"nguon":["@c1903"]},{"id":"am-duong-nhi-sat","name":"Âm Dương nhị sát","cn":"","type":"nhom-cao-thu","typeLabel":"Cận vệ Ma tộc","diaBan":"Đang trên đường tới khu vực Ỷ Thiên thành","nhanVatChinh":[],"aliases":["Âm Dương song sát"],"blurb":"Hai cận vệ thân tín bên cạnh Huyết Quang thánh tổ, được phái đi điều tra việc ba Lực tôn giả bị diệt và vật quan trọng bị mất.","detail":"Âm Dương nhị sát dự kiến mất khoảng một tháng để tới hội quân với các tôn giả Ma tộc ngoài Ỷ Thiên thành. Việc cả hai được điều động cho thấy vật bị mất có ý nghĩa rất lớn với Huyết Quang thánh tổ.","nguonGoc":"Cận vệ bên người Huyết Quang thánh tổ","tonChi":"Phụng mệnh Huyết Quang thánh tổ thi hành nhiệm vụ","lanhDaoHienThoi":"Huyết Quang thánh tổ","quyMo":"Hai thành viên","quanHe":"Phụ thuộc Huyết Quang thánh tổ","trangThai":"Đang trên đường tới Ỷ Thiên thành","tabs":{"tienTrinh":[{"chuong":"@c1904","loai":"nhắc tới","importance":"normal","giaiDoan":"Được phái đi điều tra","text":"Âm Dương nhị sát được Huyết Quang thánh tổ phái tới khu vực Ỷ Thiên thành và dự kiến khoảng một tháng nữa sẽ hội quân.","anchor":"Âm Dương Nhị Sát lại bị phái đi ra ngoài? Xem ra vật kia trọng yếu vô cùng đối với Huyết Quang đại nhân"}]},"capNhatToi":"@c1904","nguon":["@c1904"]},{"id":"co-ma-toc","name":"Cổ Ma tộc","cn":"","type":"chung-toc","typeLabel":"Chủng tộc","diaBan":"Cổ Ma giới","nhanVatChinh":["Xa Kỵ Cung","Huyết Quang"],"blurb":"Cổ Ma tộc là chủng tộc cư trú tại Cổ Ma giới và đang tiến hành Ma kiếp xâm nhập Linh giới.","detail":"Ở giai đoạn đầu của Ma kiếp, chân thân các Thánh Tổ Cổ Ma chưa thể hàng lâm Linh giới. Thiên địa pháp tắc tại Cổ Ma giới là điều kiện cần để tồn tại cấp Thánh Tổ khu sử Trấn Ma Tỏa; người tại Linh giới tu ma công đến cấp độ này cũng sẽ bị cưỡng ép phi thăng sang Cổ Ma giới.","nguonGoc":"Cổ Ma giới","quyMo":"Chủng tộc có nhiều Thánh Tổ","caoThuManhNhat":"Thánh Tổ","trangThai":"Đang tham chiến","thanhVien":[{"ten":"Xa Kỵ Cung","chucVu":"Thánh Tổ","tuChuong":"@c1907","trangThai":"Bị giam trong Trấn Ma Tỏa"},{"ten":"Huyết Quang","chucVu":"Thánh Tổ","tuChuong":"@c1907","trangThai":"Đang hoạt động"}],"capNhatToi":"@c1907","tabs":{"tienTrinh":[{"chuong":"@c1907","loai":"khai chiến","importance":"normal","giaiDoan":"Giai đoạn đầu Ma kiếp","text":"Cổ Ma tộc đang xâm nhập Linh giới, nhưng chân thân các Thánh Tổ chưa thể hàng lâm trong giai đoạn đầu.","anchor":"Hiện tại Cổ Ma Giới các người đang xâm nhập Linh giới của chúng ta"},{"chuong":"@c1996","loai":"nhắc tới","importance":"normal","giaiDoan":"Tham gia đại chiến","text":"Các Cổ ma có chiến lực vượt trội đang giao chiến với trưởng lão Thiên Uyên Thành và sứ giả Thánh đảo.","anchor":"trong Ma giới chân chính chính là nguyên thuỷ Cổ ma tộc.","trangThaiMoc":"Đang tham chiến"}]},"nguon":["@c1907","@c1996"]},{"id":"phe-huyet-quang","name":"Phe Huyết Quang","cn":"","type":"phe-phai","typeLabel":"Phe phái Ma tộc","diaBan":"Ma giới và chiến trường Ỷ Thiên thành","nhanVatChinh":["Huyết Quang","Trung niên mỹ phụ áo phấn","Nam tử áo bào ngân ti"],"blurb":"Phe Ma tộc do Huyết Quang chỉ huy, đang truy tìm đồ vật thất lạc và tu sĩ Nhân tộc đã giết ba người Lực tôn giả.","detail":"Huyết Quang trực tiếp phái Âm Dương nhị sát tới Ỷ Thiên thành, cho họ mang theo chí bảo mượn từ thánh tổ để hoàn thành nhiệm vụ truy tìm và đối phó mục tiêu.","lanhDaoHienThoi":"Huyết Quang","thanhVien":[{"ten":"Huyết Quang","chucVu":"Lãnh đạo","tuChuong":"@c1909","trangThai":"đương nhiệm"},{"ten":"Trung niên mỹ phụ áo phấn","chucVu":"Sứ giả truy sát","tuChuong":"@c1909","trangThai":"đang thi hành nhiệm vụ"},{"ten":"Nam tử áo bào ngân ti","chucVu":"Sứ giả truy sát","tuChuong":"@c1909","trangThai":"đang thi hành nhiệm vụ"}],"trangThai":"Đang truy tìm mục tiêu và đồ vật thất lạc","tabs":{"tienTrinh":[{"chuong":"@c1909","loai":"nhắc tới","importance":"normal","giaiDoan":"Phái viện thủ truy sát","text":"Huyết Quang trực tiếp điều Âm Dương nhị sát tới chiến trường để truy tìm mục tiêu cùng đồ vật bị thất lạc.","anchor":"Lần này chính là do Huyết Quang đại nhân tự mình phân phó","trangThaiMoc":"Đang thi hành nhiệm vụ truy tìm"}]},"capNhatToi":"@c1909","nguon":["@c1909"]},{"id":"ma-toc-ba-mat-luc-bao","name":"Ma tộc ba mắt lục bào","cn":"","type":"quan-doi","typeLabel":"Đội quân Ma tộc","diaBan":"Chiến trường ngoài Ỷ Thiên thành","nhanVatChinh":[],"blurb":"Một đội quân Ma tộc cao lớn, có ba mắt và mặc lục bào, trà trộn trong đội hình kỵ sĩ công thành.","detail":"Lực lượng này gồm khoảng hai đến ba vạn thành viên cao bốn năm trượng, có tay sắc nhọn và con mắt xanh trên trán. Họ tiến vào chiến trường cùng Vạn Tượng ma kỵ nhưng chưa bộc lộ năng lực thực chiến.","quyMo":"Khoảng hai đến ba vạn thành viên","soCaoThu":"Không rõ","quanHe":"Thuộc lực lượng tiến công của Ma tộc","trangThai":"Đang tham gia tổng công kích Ỷ Thiên thành","capNhatToi":"@c1911","tabs":{"tienTrinh":[{"chuong":"@c1911","loai":"nhắc tới","importance":"normal","giaiDoan":"Trà trộn đội hình công thành","text":"Khoảng hai đến ba vạn Ma tộc ba mắt mặc lục bào xuất hiện trong đội hình Vạn Tượng ma kỵ khi cuộc tổng công kích bắt đầu.","anchor":"Tổng cộng cũng không hơn hai ba vạn tên, một đám ánh mắt chớp động lục quang, mặt cười âm hiểm.","trangThaiMoc":"Đã tiến vào chiến trường"}]},"nguon":["@c1911"]},{"id":"hoa-huyet-minh-ve","name":"Hóa Huyết Minh vệ","cn":"","type":"quan-doan","typeLabel":"Quân đoàn Ma tộc","diaBan":"Chiến trường ngoài Ỷ Thiên thành","nhanVatChinh":["Ma tướng cầm đầu Hóa Huyết Minh vệ","Tàng ma tôn"],"blurb":"Quân đoàn Ma tộc mang huyết văn, tử khí nồng đậm và thân thể hư ảo như chiến quỷ.","detail":"Theo lệnh Tàng ma tôn, Hóa Huyết Minh vệ hóa thành huyết vụ và triển khai Huyết Minh đại trận để bao vây các chiến lực cấp Hợp Thể.","dacDiem":"Thành viên có huyết văn sặc sỡ, tỏa tử khí đáng sợ và có thân thể hư ảo.","lanhDaoHienThoi":"Ma tướng cầm đầu Hóa Huyết Minh vệ","thanhVien":[{"ten":"Ma tướng cầm đầu Hóa Huyết Minh vệ","chucVu":"Chỉ huy","tuChuong":"@c1916","trangThai":"đang hoạt động"}],"tabs":{"tienTrinh":[{"chuong":"@c1916","loai":"khai chiến","importance":"normal","giaiDoan":"Triển khai Huyết Minh đại trận","text":"Hóa Huyết Minh vệ xuất trận, hóa thành huyết vụ và bao vây ba chiến lực cấp Hợp Thể.","anchor":"Trên thân đám này phát ra tử khí đáng sợ cực kỳ, toàn thân sặc sỡ huyết sắc hoa văn","trangThaiMoc":"đang tham chiến"}]},"trangThai":"đang hoạt động","capNhatToi":"@c1916","nguon":["@c1916"]},{"id":"ma-toc-dai-quan","name":"Ma tộc đại quân","cn":"","aliases":[],"type":"quan-doi","typeLabel":"Đại quân","diaBan":"Chiến trường ngoài Ỷ Thiên thành","nhanVatChinh":["Huyết Quang thánh tổ","Tàng ma tôn","Lãnh Nhận"],"blurb":"Ma tộc đại quân là lực lượng đang giao chiến với Nhân tộc ngoài Ỷ Thiên thành. Sau khi Huyết Quang thánh tổ giáng lâm Linh giới, toàn quân đồng loạt quỳ bái hắn.","detail":"Trong cuộc giao chiến với lực lượng Nhân tộc ngoài Ỷ Thiên thành, Ma tộc đại quân gồm các Ma tộc cao giai và binh sĩ. Khi Huyết Quang thánh tổ giáng lâm Linh giới, toàn quân quỳ bái hắn, qua đó sĩ khí của phe Ma tộc tăng mạnh. @c1923","lanhDaoHienThoi":"Huyết Quang thánh tổ","quyMo":"Đại quân gồm cao giai Ma tộc và đông đảo binh sĩ.","trangThai":"hưng thịnh","thanhVien":[{"ten":"Huyết Quang thánh tổ","chucVu":"Thánh tổ chỉ huy","tuChuong":"@c1923","trangThai":"đang lãnh đạo"},{"ten":"Tàng ma tôn","chucVu":"Tôn giả Hợp Thể","tuChuong":"@c1923","trangThai":"đang tham chiến"},{"ten":"Lãnh Nhận","chucVu":"Tôn giả Hợp Thể trung kỳ","tuChuong":"@c1923","trangThai":"đang tham chiến"}],"lanhDaoMoc":[{"ten":"Huyết Quang thánh tổ","tuChuong":"@c1923","denChuong":""}],"capNhatToi":"@c1923","tabs":{"tienTrinh":[{"chuong":"@c1923","loai":"đổi lãnh đạo","importance":"major","giaiDoan":"Thánh tổ giáng lâm","trangThaiMoc":"Sĩ khí tăng mạnh","text":"Toàn bộ Ma tộc đại quân quỳ bái Huyết Quang thánh tổ sau khi hắn giáng lâm Linh giới.","anchor":"toàn bộ Ma tộc đại quân đều hướng không trung quỳ gối lễ bái"}]},"nguon":["@c1923"],"dacDiem":"Bao gồm Ma tộc cao giai và binh sĩ; toàn quân quy phục, quỳ bái Huyết Quang thánh tổ sau khi hắn giáng lâm Linh giới. @c1923","congNang":["Sĩ khí toàn quân tăng mạnh sau khi Huyết Quang thánh tổ giáng lâm và được toàn quân quỳ bái. @c1923"]},{"id":"thanh-hoang-thanh","name":"Thánh Hoàng thành","cn":"","type":"thanh-tri","typeLabel":"Thế lực thành trì","diaBan":"Thánh Hoàng thành","nhanVatChinh":["Thánh Hoàng","Thiên Thiền đại sư"],"blurb":"Thế lực phòng thủ Thánh Hoàng thành trong ma kiếp.","detail":"Tình hình phòng thủ của Thánh Hoàng thành đang không thuận lợi, khiến Thiên Thiền phải lập tức trở về trợ giúp Thánh Hoàng thủ thành.","lanhDaoHienThoi":"Thánh Hoàng","quanHe":"Đối đầu với Ma tộc trong ma kiếp","trangThai":"Đang bị uy hiếp","thanhVien":[{"ten":"Thánh Hoàng","chucVu":"Người chủ trì phòng thủ","tuChuong":"@c1943","trangThai":"Đang hoạt động"},{"ten":"Thiên Thiền đại sư","chucVu":"Người trợ giúp thủ thành","tuChuong":"@c1943","trangThai":"Trở về thành"}],"tabs":{"tienTrinh":[{"chuong":"@c1943","loai":"khai chiến","importance":"normal","giaiDoan":"Phòng thủ trong ma kiếp","text":"Tình hình phòng thủ không thuận lợi khiến Thiên Thiền phải trở về trợ giúp Thánh Hoàng thủ thành.","anchor":"tình hình của Thánh hoàng thành cũng không được tốt","trangThaiMoc":"Đang bị uy hiếp"}]},"capNhatToi":"@c1943","nguon":["@c1943"]},{"id":"dai-quan-ma-toc-do-huyet-quang-thong-linh","name":"Đại quân Ma tộc do Huyết Quang thống lĩnh","cn":"","type":"quan-doi","typeLabel":"Đại quân Ma tộc","diaBan":"Khu vực quanh tuyến đường tới Thiên Uyên Thành và các cứ điểm lớn của Nhân tộc","nhanVatChinh":["Huyết Quang Thánh Tổ"],"blurb":"Đại quân Ma tộc dưới quyền Huyết Quang được triển khai để phong tỏa và liên tục tiêu hao Hàn Lập.","detail":"Huyết Quang không thể rút toàn bộ đại quân khỏi khu vực, nhưng đã điều nhiều đợt nhân thủ chặn đánh và phong tỏa các tuyến đường dẫn tới Thiên Uyên Thành cùng những cứ điểm lớn của Nhân tộc.","lanhDaoHienThoi":"Huyết Quang Thánh Tổ","thanhVien":[{"ten":"Huyết Quang Thánh Tổ","chucVu":"Người thống lĩnh","tuChuong":"@c1950","trangThai":"đang chỉ huy"}],"trangThai":"đang triển khai phong tỏa","capNhatToi":"@c1950","tabs":{"tienTrinh":[{"chuong":"@c1950","loai":"khai chiến","importance":"normal","giaiDoan":"Phong tỏa tuyến đường Nhân tộc","text":"Huyết Quang điều động quân lực phong tỏa đường tới Thiên Uyên Thành và các cứ điểm lớn của Nhân tộc nhằm bào mòn Hàn Lập.","anchor":"ta sẽ điều động lực lượng, đem đường tới Thiên Uyên Thành và vài cứ điểm lớn của Nhân tộc trong khu vực ngăn lại"}]},"nguon":["@c1950"]},{"id":"tinh-nhue-ben-luc-cuc","name":"Tinh nhuệ bên Lục Cực","cn":"","type":"quan-doi","typeLabel":"Lực lượng tinh nhuệ Ma tộc","diaBan":"Khu vực do Lục Cực kiểm soát","nhanVatChinh":["Lục Cực"],"blurb":"Lực lượng tinh nhuệ Ma tộc dưới quyền Lục Cực được dự kiến điều tới tăng viện cuộc vây bắt Hàn Lập.","detail":"Huyết Quang đề nghị Nguyên Sát điều động lực lượng này, và Nguyên Sát chấp thuận gọi viện binh tới hỗ trợ kế hoạch truy đuổi lâu dài.","lanhDaoHienThoi":"Lục Cực","thanhVien":[{"ten":"Lục Cực","chucVu":"Người nắm lực lượng","tuChuong":"@c1950","trangThai":"đang nắm quyền"}],"trangThai":"được dự kiến điều động","capNhatToi":"@c1950","tabs":{"tienTrinh":[{"chuong":"@c1950","loai":"liên minh","importance":"normal","giaiDoan":"Chuẩn bị tăng viện","text":"Tinh nhuệ bên Lục Cực được đề nghị điều tới để phối hợp với lực lượng Huyết Quang vây bắt Hàn Lập.","anchor":"Đạo hữu sao không điêu động một số tinh nhuệ bên Lục Cực lại đây"}]},"nguon":["@c1950"]},{"id":"thach-ma-toc","name":"Thạch Ma tộc","cn":"","type":"chung-toc","typeLabel":"Ma tộc","diaBan":"Thánh giới","nhanVatChinh":["Hai Thạch trưởng lão"],"blurb":"Một tộc thuộc Thánh giới, có hệ thống cường giả được phân định theo thứ hạng.","detail":"Hai Thạch trưởng lão thuộc nhóm mười cường giả hàng đầu của Thạch Ma tộc, dù chưa thể xếp trong ba hạng đầu. Hai người từng được Nguyên Sát che chở nhiều năm tại Thánh giới.","quyMo":"Có hệ thống xếp hạng gồm ít nhất mười cường giả hàng đầu.","caoThuManhNhat":"Chưa xác định","soCaoThu":"Ít nhất mười cường giả được xếp hạng","thanhVien":[{"ten":"Hai Thạch trưởng lão","chucVu":"Trưởng lão","tuChuong":"@c1952","trangThai":"đang thuộc"}],"trangThai":"đang tồn tại","capNhatToi":"@c1952","tabs":{"tienTrinh":[{"chuong":"@c1952","loai":"nhắc tới","importance":"bridge","giaiDoan":"Hé lộ cường giả trong tộc","text":"Hai Thạch trưởng lão được xác nhận thuộc nhóm mười cường giả hàng đầu của Thạch Ma tộc.","anchor":"bọn họ trong Thạch Ma tộc mặc dù tu vi không thể xếp vào ba hạng đầu, nhưng cũng đủ để xếp trong mười hạng đầu"}]},"nguon":["@c1952"]},{"id":"ma-toc-xam-luoc-nhan-gioi","name":"Ma tộc xâm lược Nhân giới","cn":"","type":"quan-doi","typeLabel":"Lực lượng xâm lược","diaBan":"Các khu vực và điểm truyền tống đã chiếm giữ trong lãnh thổ Nhân tộc","nhanVatChinh":["Huyết Quang Thánh Tổ","Nguyên Sát"],"blurb":"Lực lượng Ma tộc đang xâm nhập lãnh thổ Nhân tộc và kiểm soát nhiều khu vực cùng điểm truyền tống.","detail":"Theo lệnh các hóa thân Huyết Quang, đông đảo nhân thủ Ma tộc được điều động để phong tỏa các khu vực và hỗ trợ truy bắt Hàn Lập. Mật độ lực lượng giảm rõ rệt tại vùng hoang vu sát Man Hoang thế giới, nơi không có thành thị Nhân tộc và Ma tộc cũng không bố trí đại quân.","quyMo":"Đông đảo nhân thủ phân bố tại nhiều khu vực bị chiếm giữ","quanHe":"Đối địch với Nhân tộc","trangThai":"Đang xâm lược và phong tỏa","capNhatToi":"@c1954","tabs":{"tienTrinh":[{"chuong":"@c1954","loai":"mở rộng/mất địa bàn","importance":"normal","giaiDoan":"Mở rộng phong tỏa","text":"Lực lượng Ma tộc được điều động phong tỏa nhiều khu vực và sử dụng các điểm truyền tống đã chiếm giữ để truy bắt Hàn Lập.","anchor":"điều động vô số nhân thủ bày ra thiên la địa võng phong tỏa tất cả các khu vực"}]},"nguon":["@c1954"]},{"id":"ma-toc-tai-cu-diem","name":"Ma tộc tại cứ điểm","cn":"","type":"quân trú phòng","typeLabel":"Lực lượng Ma tộc","diaBan":"Cứ điểm Ma tộc gần Mộc tộc","nhanVatChinh":["Tuần sử Ma tộc hai sừng","Ma tộc bộ dáng gấu chó","Bốn Ma tộc Hóa Thần"],"blurb":"Lực lượng Ma tộc trú đóng tại cứ điểm gần lãnh địa Mộc tộc.","detail":"Lực lượng này dùng quân trú phòng, ma thú hình tê ngưu và các cường giả cao giai để đẩy lui cuộc tập kích của Mộc tộc, sau đó tràn khỏi cứ điểm truy sát quân địch.","quyMo":"Có quân trú phòng, hơn mười ma thú hình tê ngưu, bốn cường giả Hóa Thần và một tuần sử Luyện Hư hậu kỳ tại @c1965.","caoThuManhNhat":"Tuần sử Ma tộc hai sừng","trangThai":"Đẩy lui cuộc tập kích và mở cuộc truy đuổi","thanhVien":[{"ten":"Tuần sử Ma tộc hai sừng","chucVu":"Tuần sử","tuChuong":"@c1965","trangThai":"Đang hoạt động"},{"ten":"Ma tộc bộ dáng gấu chó","chucVu":"Cao giai Ma tộc tại cứ điểm","tuChuong":"@c1965","trangThai":"Đang hoạt động"},{"ten":"Bốn Ma tộc Hóa Thần","chucVu":"Cường giả phòng thủ","tuChuong":"@c1965","trangThai":"Đang truy kích"}],"tabs":{"tienTrinh":[{"chuong":"@c1965","loai":"khai chiến","importance":"normal","giaiDoan":"Phản kích và truy đuổi","text":"Lực lượng Ma tộc tại cứ điểm đẩy lui cuộc tập kích rồi tràn ra truy sát quân Mộc tộc.","anchor":"đại quân Ma tộc theo đó từ bên trong cứ điểm ào ào tuôn ra","trangThaiMoc":"Mở cuộc truy đuổi"}]},"capNhatToi":"@c1965","nguon":["@c1965"]},{"id":"nhan-yeu-hai-toc","name":"Nhân Yêu hai tộc","cn":"","type":"lien-minh","typeLabel":"Liên minh chủng tộc","diaBan":"Lãnh địa Nhân tộc và Yêu tộc tại Linh giới","nhanVatChinh":["Ngao Khiếu lão tổ","Mạc Giản Ly"],"blurb":"Liên minh giữa Nhân tộc và Yêu tộc cùng chống lại cuộc xâm lấn của Ma tộc.","detail":"Thánh đảo có danh vọng đặc biệt trong cả hai tộc và đang đảm nhiệm việc chuẩn bị lực lượng, vật tư cùng phương án cho đại chiến. Nếu đảo bị công phá, tinh thần của liên minh sẽ chịu đả kích nghiêm trọng.","tonChi":"Phối hợp chống đại quân Ma tộc","lanhDaoHienThoi":["Mạc Giản Ly","Ngao Khiếu lão tổ"],"quanHe":"Đối địch Ma tộc","trangThai":"Đang chuẩn bị đại chiến","thanhVien":[{"ten":"Mạc Giản Ly","chucVu":"Đại Thừa Nhân tộc","tuChuong":"@c1969","trangThai":"Đang hoạt động"},{"ten":"Ngao Khiếu lão tổ","chucVu":"Đại Thừa Yêu tộc","tuChuong":"@c1969","trangThai":"Đang tọa trấn Thánh đảo"}],"capNhatToi":"@c1969","tabs":{"tienTrinh":[{"chuong":"@c1969","loai":"khai chiến","importance":"normal","giaiDoan":"Chuẩn bị chống Ma tộc","text":"Nhân Yêu hai tộc tiếp tục tập trung lực lượng và vật tư tại Thánh đảo để chuẩn bị đối đầu đại quân Ma tộc.","anchor":"lấy danh vọng Thánh đảo trong hai tộc chúng ta","trangThaiMoc":"Đang chuẩn bị đại chiến"}]},"nguon":["@c1969"]},{"id":"ngan-nguyet-nhat-toc","name":"Ngân Nguyệt nhất tộc","cn":"","aliases":[],"type":"chung-toc","typeLabel":"Yêu lang vương tộc","diaBan":"","nhanVatChinh":["Ngao Khiếu lão tổ","Ngân Nguyệt"],"blurb":"Yêu lang vương tộc của Ngao Khiếu lão tổ và Ngân Nguyệt, vốn có tư cách nắm giữ ngôi Lang vương.","detail":"Ngân Nguyệt từng là Thánh nữ của tộc trước khi gả cho Thiên Khuê. Ngao Khiếu cho rằng mình đã nâng đỡ một người ngoài lên ngôi Lang vương và muốn thu hồi ngôi vị này cho Ngân Nguyệt sau ma kiếp.","nguonGoc":"Yêu lang vương tộc","lanhDaoHienThoi":"Ngao Khiếu lão tổ","caoThuManhNhat":"Ngao Khiếu lão tổ","thanhVien":[{"ten":"Ngao Khiếu lão tổ","chucVu":"Lão tổ","tuChuong":"@c1970","trangThai":"Đang tại vị"},{"ten":"Ngân Nguyệt","chucVu":"Thánh nữ","tuChuong":"@c1970","trangThai":"Thành viên"}],"trangThai":"Đang mưu tính thu hồi ngôi Lang vương","tabs":{"tienTrinh":[{"chuong":"@c1970","loai":"nhắc tới","importance":"normal","giaiDoan":"Xác nhận địa vị vương tộc","text":"Ngao Khiếu xác nhận Ngân Nguyệt nhất tộc mới là Yêu lang vương tộc và muốn lấy lại ngôi Lang vương cho Ngân Nguyệt.","anchor":"Ngân Nguyệt nhất tộc chúng ta mới là Yêu lang vương tộc","trangThaiMoc":"Chuẩn bị tranh lại ngôi Lang vương"}]},"capNhatToi":"@c1970","nguon":["@c1970"]},{"id":"ba-dai-thuy-to-ma-toc","name":"Ba đại Thủy tổ Ma tộc","cn":"","type":"nhom-dai-nang","typeLabel":"Nhóm đại năng Ma tộc","diaBan":"Ma giới","nhanVatChinh":[],"blurb":"Ba đại Thủy tổ Ma tộc là đối tượng mà kế hoạch tuyệt mật của Ngao Khiếu hướng tới đối phó. Hai nhiệm vụ chuẩn bị phải được hoàn thành trong thời hạn tối đa năm năm.","detail":"Ngao Khiếu giao một trưởng lão bí mật tìm kiếm tài liệu và pháp khí, đồng thời phái một trưởng lão khác vào Man Hoang thế giới gặp các đại năng dị tộc. Cả hai nhiệm vụ đều liên quan trực tiếp đến việc đối phó ba đại Thủy tổ Ma tộc.","trangThai":"Bị Ngao Khiếu bí mật chuẩn bị biện pháp đối phó","capNhatToi":"@c1971","tabs":{"tienTrinh":[{"chuong":"@c1971","loai":"nhắc tới","importance":"normal","giaiDoan":"Kế hoạch đối phó được khởi động","text":"Ngao Khiếu giao hai nhiệm vụ tuyệt mật nhằm chuẩn bị biện pháp đối phó ba đại Thủy tổ Ma tộc trong vòng năm năm.","anchor":"hai chuyện này có liên quan đến ba đại Thủy tổ Ma tộc","trangThaiMoc":"Bị bí mật chuẩn bị biện pháp đối phó"}]},"nguon":["@c1971"]},{"id":"hoa-ly-tong","name":"Hỏa Ly Tông","cn":"","type":"tong-mon","typeLabel":"Tông môn","diaBan":"Khu vực gần Thiên Uyên thành","nhanVatChinh":["Chưởng môn Hỏa Ly Tông","Lý sư đệ","Sư muội xấu xí của chưởng môn Hỏa Ly Tông","Dương sư đệ"],"blurb":"Hỏa Ly Tông là một tông môn đang lẩn tránh đại quân Ma tộc gần Thiên Uyên thành. Trước nguy cơ bị tiêu diệt, tông môn tìm kiếm pháp trận bí mật nhằm đưa môn nhân vào thành và bảo toàn truyền thừa.","detail":"Sau một hành trình dài, Hỏa Ly Tông ẩn náu gần một hạp cốc bí mật cách Thiên Uyên thành hơn mười vạn dặm. Trước sự uy hiếp của Ma tộc, chưởng môn quyết định dò tìm truyền tống pháp trận dành cho trưởng lão Thiên Uyên thành, hy vọng dùng pháp trận đưa môn nhân vào thành; tông môn đồng thời chuẩn bị rút lui nếu việc dò xét thất bại. @c1972","tonChi":"Bảo toàn môn nhân và truyền thừa tông môn.","lanhDaoHienThoi":"Chưởng môn Hỏa Ly Tông","quyMo":"Có nhiều môn nhân đang lẩn tránh Ma tộc.","tranPhai":"Song kiếm vàng xanh của chưởng môn chưa rõ có phải vật trấn phái hay không.","quanHe":"Muốn nương nhờ Thiên Uyên thành và đang bị Ma tộc uy hiếp.","trangThai":"Đang tìm đường di chuyển vào Thiên Uyên thành","thanhVien":[{"ten":"Chưởng môn Hỏa Ly Tông","chucVu":"Chưởng môn","tuChuong":"@c1972","trangThai":"đang tại vị"},{"ten":"Lý sư đệ","chucVu":"Môn nhân","tuChuong":"@c1972","trangThai":"đang hoạt động"},{"ten":"Sư muội xấu xí của chưởng môn Hỏa Ly Tông","chucVu":"Môn nhân","tuChuong":"@c1972","trangThai":"đang hoạt động"},{"ten":"Dương sư đệ","chucVu":"Môn nhân","tuChuong":"@c1972","trangThai":"đang hoạt động"}],"lanhDaoMoc":[{"ten":"Chưởng môn Hỏa Ly Tông","tuChuong":"@c1972","denChuong":""}],"capNhatToi":"@c1972","tabs":{"tienTrinh":[{"chuong":"@c1972","loai":"mở rộng/mất địa bàn","importance":"major","giaiDoan":"Tìm nơi bảo toàn truyền thừa","text":"Trước nguy cơ bị Ma tộc tiêu diệt, Hỏa Ly Tông quyết định dò tìm pháp trận bí mật để đưa môn nhân vào Thiên Uyên thành.","anchor":"chỉ có tiến vào Thiên Uyên thành mới có thể bảo vệ được truyền thừa bổn tông","trangThaiMoc":"Đang lẩn tránh và tìm đường vào thành"}]},"nguon":["@c1972"],"dacDiem":"Ẩn náu để tránh đại quân Ma tộc và ưu tiên bảo toàn môn nhân cùng truyền thừa."},{"id":"luc-luong-phong-thu-thien-uyen-thanh","name":"Lực lượng phòng thủ Thiên Uyên thành","cn":"","type":"quan-su","typeLabel":"Lực lượng phòng thủ","diaBan":"Đại điện truyền tống Thiên Uyên thành","nhanVatChinh":["Hai vệ sĩ Nguyên Anh kỳ","Kim vệ cầm đầu","Trường đại nhân"],"blurb":"Lực lượng thường trực bảo vệ khu vực truyền tống của Thiên Uyên thành.","detail":"Khi truyền tống trận bên ngoài thành bất ngờ hoạt động, các vệ sĩ lập tức mở cấm chế, tập hợp hơn trăm người và chuẩn bị báo cho Trường đại nhân.","tonChi":"Canh giữ hệ thống truyền tống và ứng phó xâm nhập bất thường.","quyMo":"Hơn trăm vệ sĩ hiện diện gần đại điện truyền tống.","tranPhai":["Cấm chế đại điện truyền tống","Trận bàn màu lam"],"thanhVien":[{"ten":"Hai vệ sĩ Nguyên Anh kỳ","chucVu":"Thủ vệ truyền tống","tuChuong":"@c1974","trangThai":"đang phục vụ"},{"ten":"Kim vệ cầm đầu","chucVu":"Chỉ huy Kim vệ","tuChuong":"@c1974","trangThai":"đang phục vụ"},{"ten":"Trường đại nhân","chucVu":"Cấp trên phụ trách","tuChuong":"@c1974","trangThai":"đang phục vụ"}],"trangThai":"Đang hoạt động","capNhatToi":"@c1974","tabs":{"tienTrinh":[{"chuong":"@c1974","loai":"nhắc tới","importance":"normal","giaiDoan":"Báo động truyền tống","text":"Hơn trăm vệ sĩ tập hợp và mở cấm chế khi phát hiện truyền tống trận bên ngoài thành bất ngờ hoạt động.","anchor":"đang có hơn trăm tên vệ sĩ đang ngồi đả tọa","trangThaiMoc":"Báo động"}]},"nguon":["@c1974"]},{"id":"y-thien-thanh","name":"Ỷ Thiên thành","cn":"","type":"thanh-tri","typeLabel":"Thành trì và thế lực tu sĩ","diaBan":"Ỷ Thiên thành","nhanVatChinh":["Thanh Long thượng nhân"],"blurb":"Thế lực có các tu sĩ tinh nhuệ chạy tới Thiên Uyên thành sau biến cố giao chiến với Ma tộc.","detail":"Các tu sĩ tinh nhuệ của Ỷ Thiên thành chạy tới Thiên Uyên thành. Thanh Long thượng nhân được xác nhận là một Thái thượng trưởng lão thuộc thế lực này.","thanhVien":[{"ten":"Thanh Long thượng nhân","chucVu":"Thái thượng trưởng lão","tuChuong":"@c1975","trangThai":"đang giữ chức"}],"tabs":{"tienTrinh":[{"chuong":"@c1975","loai":"nhắc tới","importance":"normal","giaiDoan":"Rút tới Thiên Uyên thành","text":"Các đệ tử tinh nhuệ của thế lực chạy tới Thiên Uyên thành trong thời kỳ ma kiếp.","anchor":"bọn họ dẫn theo đệ tử tinh nhuệ tông môn chạy trốn tới Thiên Uyên thành"}]},"capNhatToi":"@c1975","nguon":["@c1975"]},{"id":"cuu-tinh-tong","name":"Cửu Tinh tông","cn":"","type":"tong-mon","typeLabel":"Tông môn","diaBan":"Ỷ Thiên thành","nhanVatChinh":["Thanh Long thượng nhân"],"blurb":"Tông môn của Thanh Long thượng nhân, một Thái thượng trưởng lão tại Ỷ Thiên thành.","detail":"Cửu Tinh tông được xác nhận là tông môn của Thanh Long thượng nhân. Trong thời gian Hàn Lập mất tích, vị Thái thượng trưởng lão này gây sức ép buộc Băng Phượng song tu.","thanhVien":[{"ten":"Thanh Long thượng nhân","chucVu":"Trưởng lão","tuChuong":"@c1975","trangThai":"được nhắc nhận diện"}],"capNhatToi":"@c1975","nguon":["@c1975","@c1979"],"trangThai":"Không rõ"},{"id":"dau-nguyen-cac","name":"Đâu Nguyên các","cn":"","type":"tổ chức","typeLabel":"Lầu các","diaBan":"Thiên Uyên thành và không gian tỷ thí riêng","nhanVatChinh":["Cố lão giả"],"blurb":"Một tổ chức sở hữu lầu các cùng không gian tỷ thí được mở dựa vào khe không gian. Cơ sở của tổ chức có truyền tống trận và cấm chế đủ sức cách ly tranh đấu giữa tu sĩ Hợp Thể kỳ.","detail":"Tầng cao nhất của Đâu Nguyên các có pháp trận dẫn vào một không gian riêng rộng hàng nghìn mẫu. Trong đó có đài tỷ thí được gia cố và Hỗn Thiên Lưỡng Nghi trận bảo vệ.","quyMo":"Sở hữu cơ sở có thể chịu được tranh đấu giữa tu sĩ Hợp Thể kỳ","tranPhai":"Hỗn Thiên Lưỡng Nghi trận","trangThai":"Hoạt động","thanhVien":[{"ten":"Cố lão giả","chucVu":"Các chủ","tuChuong":"@c1979","trangThai":"đang tại vị"}],"capNhatToi":"@c1979","tabs":{"tienTrinh":[{"chuong":"@c1979","loai":"nhắc tới","importance":"normal","giaiDoan":"Cho mượn không gian tỷ thí","text":"Đâu Nguyên các cung cấp không gian riêng cùng trận pháp bảo hộ để Hàn Lập và Thanh Long thượng nhân tiến hành cuộc tỷ thí.","anchor":"Đâu Nguyên các có một chỗ lợi dụng khe không gian mà mở ra một không gian riêng","trangThaiMoc":"Hoạt động"}]},"nguon":["@c1979"]},{"id":"dai-quan-ma-toc","name":"Đại quân Ma tộc","cn":"","type":"quân đội","typeLabel":"Đại quân","diaBan":"Khu vực bao quanh Thiên Uyên thành","nhanVatChinh":[],"blurb":"Lực lượng Ma tộc đang bao vây Thiên Uyên thành. Việc phong tỏa này khiến nhóm Tiểu Hồng khó rời thành để trốn tránh Hàn Lập.","detail":"Đại quân Ma tộc hiện diện quanh Thiên Uyên thành và làm hạn chế đường rút lui của các tu sĩ trong thành.","trangThai":"Đại bại và tan rã","capNhatToi":"@c1979","nguon":["@c1979","@c2004"],"tabs":{"tienTrinh":[{"chuong":"@c2004","loai":"suy","importance":"normal","giaiDoan":"Tan rã ngoài Thiên Uyên Thành","text":"Đại quân Ma Tộc mất chỉ huy, hoàn toàn đại loạn và bị liên quân truy sát, khiến ít nhất năm sáu phần lực lượng cấp thấp bị tiêu diệt.","anchor":"tồn tại Ma Tộc cấp thấp thì lại bị bọn họ giết ít nhất cũng năm sáu phần","trangThaiMoc":"Đại bại"}]}},{"id":"tu-dai-tong-mon-y-thien-thanh","name":"Tứ đại tông môn Ỷ Thiên thành","cn":"","type":"tong-mon-lien-hop","typeLabel":"Liên hợp tông môn","diaBan":"Ỷ Thiên thành, Thiên Uyên thành và Thánh Hoàng thành","nhanVatChinh":["Thanh Long thượng nhân","Lâm Loan tiên tử"],"blurb":"Bốn tông môn gắn với Ỷ Thiên thành, hiện chỉ còn Thanh Long thượng nhân và Lâm Loan tiên tử là hai Thái thượng trưởng lão được nhắc đến. Lực lượng và truyền thừa được phân tán giữa Thiên Uyên thành và Thánh Hoàng thành để giảm nguy cơ cùng bị tiêu diệt.","detail":"Sau khi Thanh Long quyết định rời Thiên Uyên thành đến Thánh Hoàng thành, Lâm Loan chấp thuận việc phân tán lực lượng của tứ đại tông môn. Nàng ở lại quản lĩnh phần lớn đệ tử Cửu Tinh tông, còn Thanh Long chỉ mang theo hai môn hạ.","quyMo":"Bốn tông môn","caoThuManhNhat":"Thanh Long thượng nhân và Lâm Loan tiên tử","soCaoThu":"Hai Thái thượng trưởng lão còn lại được nhắc đến","thanhVien":[{"ten":"Thanh Long thượng nhân","chucVu":"Thái thượng trưởng lão","tuChuong":"@c1982","trangThai":"Rời Thiên Uyên thành đến Thánh Hoàng thành"},{"ten":"Lâm Loan tiên tử","chucVu":"Thái thượng trưởng lão","tuChuong":"@c1982","trangThai":"Ở lại Thiên Uyên thành"}],"trangThai":"Phân tán lực lượng để bảo toàn truyền thừa","capNhatToi":"@c1982","tabs":{"tienTrinh":[{"chuong":"@c1982","loai":"mở rộng/mất địa bàn","importance":"normal","giaiDoan":"Phân tán truyền thừa","trangThaiMoc":"Lực lượng được chia giữa Thiên Uyên thành và Thánh Hoàng thành","text":"Thanh Long đến Thánh Hoàng thành trong khi Lâm Loan cùng phần lớn môn hạ tiếp tục ở lại Thiên Uyên thành, qua đó phân tán lực lượng và truyền thừa của tứ đại tông môn.","anchor":"tứ đại tông môn Thái thượng trưởng lão bây giờ chỉ còn lại ta và ngươi mà thôi"}]},"nguon":["@c1982"]},{"id":"to-van-son","name":"Tổ Vân Sơn","cn":"","type":"cu-diem","typeLabel":"Cứ điểm Linh Tộc","diaBan":"Khu vực Linh Tộc giáp Nhân Tộc","nhanVatChinh":["Lão giả mập mạp","Hoàng huynh","Phụ nhân xinh đẹp"],"blurb":"Tổ Vân Sơn từng là một cứ điểm nổi tiếng của Linh Tộc nằm gần khu vực Nhân Tộc, do ba thái thượng trưởng lão Hợp Thể Kỳ trấn giữ. Khi ba người xuất môn, toàn bộ thành viên tại cứ điểm bị Thanh niên áo bào vàng giết và hấp thu tinh nguyên bản thể.","detail":"Tổ Vân Sơn là cứ điểm của Linh Tộc nằm gần khu vực Nhân Tộc, có ba thái thượng trưởng lão Hợp Thể Kỳ trấn giữ. Trong lúc ba vị thái thượng trưởng lão xuất môn, Thanh niên áo bào vàng đã giết toàn bộ thành viên tại đây và hấp thu tinh nguyên bản thể của họ, khiến cứ điểm bị tiêu diệt. @c2007","lanhDaoHienThoi":"Ba thái thượng trưởng lão","caoThuManhNhat":"Ba thái thượng trưởng lão Hợp Thể Kỳ","trangThai":"Bị đồ diệt","thanhVien":[{"ten":"Lão giả mập mạp","chucVu":"Thái thượng trưởng lão","tuChuong":"@c2007","trangThai":"đang tại nhiệm"},{"ten":"Hoàng huynh","chucVu":"Thái thượng trưởng lão","tuChuong":"@c2007","trangThai":"đang tại nhiệm"},{"ten":"Phụ nhân xinh đẹp","chucVu":"Thái thượng trưởng lão","tuChuong":"@c2007","trangThai":"đang tại nhiệm"}],"tabs":{"tienTrinh":[{"chuong":"@c2007","loai":"diệt/sáp nhập","importance":"major","giaiDoan":"Cứ điểm bị đồ diệt","text":"Toàn bộ thành viên tại cứ điểm bị Thanh niên áo bào vàng giết và hấp thu tinh nguyên bản thể.","anchor":"Tổ Vân Sơn này đúng là một trong những cứ điểm nổi tiếng của Linh Tộc","trangThaiMoc":"Bị đồ diệt"}]},"capNhatToi":"@c2007","nguon":["@c2007"],"dacDiem":"Cứ điểm nổi tiếng của Linh Tộc, nằm gần khu vực Nhân Tộc và do ba thái thượng trưởng lão Hợp Thể Kỳ trấn giữ."},{"id":"doan-xam-nhap-ma-gioi","name":"Đoàn xâm nhập Ma giới","cn":"","type":"lien-minh-lam-thoi","typeLabel":"Đội ngũ liên tộc lâm thời","diaBan":"Hành trình từ Linh giới tới tiết điểm thông đạo vào Ma giới","nhanVatChinh":["Hàn Lập","Lũng gia lão tổ","Thiên Thu thánh nữ","Phi phát nam tử mặt không chút biểu tình","Tàng Hình"],"blurb":"Đội ngũ lâm thời gồm thành viên Nhân tộc, Linh tộc và Hải tộc, được tổ chức để bí mật xâm nhập Ma giới.","detail":"Sau thời gian điều tức trên cự thuyền màu xanh, đoàn tới gần tiết điểm thông đạo đã định. Vì cự thuyền quá lớn, các thành viên rời thuyền và chuyển sang tự bay để tiếp tục hành trình.","nguonGoc":"Được tập hợp để thực hiện chuyến xâm nhập Ma giới.","quyMo":"Gồm các thành viên Nhân tộc, Linh tộc và Hải tộc.","trangThai":"Đang tiếp cận tiết điểm thông đạo","thanhVien":[{"ten":"Hàn Lập","chucVu":"Thành viên","tuChuong":"@c2012","trangThai":"đang tham gia"},{"ten":"Lũng gia lão tổ","chucVu":"Người điều phối hành trình","tuChuong":"@c2012","trangThai":"đang tham gia"},{"ten":"Thiên Thu thánh nữ","chucVu":"Thành viên Linh tộc","tuChuong":"@c2012","trangThai":"đang tham gia"},{"ten":"Phi phát nam tử mặt không chút biểu tình","chucVu":"Thành viên Lâm gia","tuChuong":"@c2012","trangThai":"đang tham gia"},{"ten":"Tàng Hình","chucVu":"Thành viên Linh tộc","tuChuong":"@c2012","trangThai":"đang tham gia"},{"ten":"Những người Hải tộc trong đoàn xâm nhập Ma giới","chucVu":"Thành viên Hải tộc","tuChuong":"@c2012","trangThai":"đang tham gia"}],"tabs":{"tienTrinh":[{"chuong":"@c2012","loai":"nhắc tới","importance":"normal","giaiDoan":"Tiếp cận tiết điểm","text":"Đoàn rời cự thuyền và chuyển sang tự bay khi tới gần tiết điểm thông đạo vào Ma giới.","anchor":"cho nên chúng ta sẽ tự bay"}]},"capNhatToi":"@c2012","nguon":["@c2012"]},{"id":"bao-ma-toc","name":"Bạo Ma tộc","cn":"","aliases":["Bạo Ma nhất tộc"],"type":"chung-toc","typeLabel":"Thế lực Ma tộc","diaBan":"Góc hẻo lánh của Huyền Vũ cảnh quanh tiết điểm Ma tộc","nhanVatChinh":[],"blurb":"Một nhánh Ma tộc khát máu, hiếu chiến đóng quân quanh tiết điểm tại Huyền Vũ cảnh. Thành viên thường có vóc dáng cao lớn và mặc ma giáp khắc ma văn màu lam.","detail":"Bạo Ma tộc ưa tranh giành và chiến đấu. Các đội tuần tra của họ có quy mô từ hơn mười đến hơn trăm vệ sĩ, nhưng những đội gặp trên đường cao nhất chỉ đạt Hóa Thần kỳ nên không phát hiện đoàn Hàn Lập đang che giấu độn quang.","tonChi":"Ưa tranh giành và mạnh đấu.","quyMo":"Có nhiều đội vệ sĩ tuần tra quanh khu vực tiết điểm.","quanHe":"Thuộc Ma tộc và kiểm soát khu vực quanh tiết điểm tại Huyền Vũ cảnh.","trangThai":"Đang đóng quân","tabs":{"tienTrinh":[{"chuong":"@c2013","loai":"nhắc tới","importance":"normal","giaiDoan":"Trấn giữ tiết điểm","text":"Bạo Ma tộc đóng quân quanh tiết điểm Ma tộc mà đoàn Hàn Lập dự định sử dụng.","anchor":"Bạo Ma Ma tộc thích nhất là tranh giành và mạnh đấu.","trangThaiMoc":"Đang kiểm soát khu vực quanh tiết điểm"}]},"capNhatToi":"@c2013","nguon":["@c2013"]},{"id":"ma-toc-tran-giu-thong-dao","name":"Ma tộc trấn giữ thông đạo","cn":"","type":"quan-doi","typeLabel":"Lực lượng đồn trú","diaBan":"Thông đạo vào Ma giới","nhanVatChinh":["Khách huynh","Trung giai Ma tộc thuộc hạ Khách huynh"],"blurb":"Lực lượng Ma tộc bảo vệ thông đạo bằng quân tuần tra, nhiều tầng cấm chế và mấy trăm quân tinh nhuệ.","detail":"Đơn vị này do Ma Tôn Khách huynh chỉ huy. Trước đoàn hơn mười cường giả Hợp Thể, quân trấn thủ không thể ngăn cản và phải tránh sang hai bên để đối phương vượt thông đạo.","quyMo":"Mấy trăm Ma tộc tinh nhuệ","lanhDaoHienThoi":"Khách huynh","caoThuManhNhat":"Khách huynh","tranPhai":"Nhiều tầng cấm chế phòng hộ","trangThai":"Không ngăn được đoàn xâm nhập","thanhVien":[{"ten":"Khách huynh","chucVu":"Ma Tôn chỉ huy","tuChuong":"@c2016","trangThai":"đang tại nhiệm"},{"ten":"Trung giai Ma tộc thuộc hạ Khách huynh","chucVu":"Thuộc hạ đồn trú","tuChuong":"@c2016","trangThai":"đang phục vụ"}],"capNhatToi":"@c2016","tabs":{"tienTrinh":[{"chuong":"@c2016","loai":"mất địa bàn","importance":"normal","giaiDoan":"Phòng tuyến bị xuyên thủng","text":"Lực lượng trấn giữ bị đoàn cường giả phá nhiều tầng cấm chế và phải nhường đường vào thông đạo.","anchor":"mấy trăm tên Ma tộc tinh nhuệ dưới sự dẫn đầu của một ma ảnh cao lớn, đang chắn phía trước","trangThaiMoc":"Không ngăn được đoàn xâm nhập"}]},"nguon":["@c2016"]},{"id":"am-bo-cua-bao-hoa","name":"Ám bộ của Bảo Hoa","cn":"","aliases":[],"type":"to-chuc-ngam","typeLabel":"Tổ chức ngầm","diaBan":"Ma giới","nhanVatChinh":["Bảo Hoa","Khách Vân"],"nguonGoc":"Bộ phận ngầm từng phục vụ Bảo Hoa.","lanhDaoHienThoi":"Bảo Hoa","trangThai":"Còn hoạt động @c2017","blurb":"Ám bộ của Bảo Hoa là lực lượng ngầm từng phục vụ nàng tại Ma giới.","detail":"Sau khi Bảo Hoa thất thế và phải rời sang Linh giới, một phần ám bộ vẫn tồn tại. Khách Vân là thành viên của lực lượng này và tiếp tục nhận lệnh khi gặp lại chủ cũ.","thanhVien":[{"ten":"Khách Vân","chucVu":"Thuộc hạ ám bộ","tuChuong":"@c2017","trangThai":"đang hoạt động"}],"tabs":{"tienTrinh":[{"chuong":"@c2017","loai":"nhắc tới","importance":"normal","giaiDoan":"Xác nhận còn tồn tại","text":"Bảo Hoa xác nhận ám bộ của mình vẫn còn người bình yên hoạt động sau thời gian nàng thất thế.","anchor":"Nhưng đám ám bộ (bộ phận ngầm) các ngươi không ngờ vẫn bình yên vô sự, khiến ta cũng có chút vui mừng."}]},"capNhatToi":"@c2017","nguon":["@c2017"]},{"id":"huyet-nha-thanh","name":"Huyết Nha Thành","cn":"","type":"thanh-tri","typeLabel":"Thành trì Ma tộc","diaBan":"Ma giới","nhanVatChinh":["Thiết đạo hữu","Ô lão"],"blurb":"Thành trì Ma tộc có Thiết đạo hữu và Ô lão giữ chức hộ pháp.","detail":"Hai hộ pháp viện dẫn thân phận của mình tại Huyết Nha Thành khi cầu xin Hàn Lập cứu khỏi thú triều. Vị trí cụ thể, quy mô và người lãnh đạo thành chưa được tiết lộ.","thanhVien":[{"ten":"Thiết đạo hữu","chucVu":"Hộ pháp","tuChuong":"@c2023","trangThai":"đang giữ chức"},{"ten":"Ô lão","chucVu":"Hộ pháp","tuChuong":"@c2023","trangThai":"đang giữ chức"}],"trangThai":"Đang tồn tại","capNhatToi":"@c2023","tabs":{"tienTrinh":[{"chuong":"@c2023","loai":"nhắc tới","importance":"bridge","giaiDoan":"Lộ diện hộ pháp","text":"Thiết đạo hữu và Ô lão tự nhận là hộ pháp Huyết Nha Thành khi cầu xin Hàn Lập cứu mạng.","anchor":"hai người chúng ta là hộ pháp Huyết Nha Thành"}]},"nguon":["@c2023"]},{"id":"lam-don-toc","name":"Lam Đồn tộc","cn":"","aliases":[],"type":"chung-toc","typeLabel":"Chủng tộc Ma giới","diaBan":"Huyết Nha thành","nhanVatChinh":["Hải Phi"],"blurb":"Lam Đồn tộc là tộc hệ của Hải Phi tại Huyết Nha thành. Lời xúc phạm nhằm vào tộc này khiến Hải Phi nổi giận và ra tay với Ngưu Lực.","detail":"Chương này chỉ xác nhận Hải Phi thuộc Lam Đồn tộc; cơ cấu, địa bàn chính và quy mô của tộc chưa được nêu rõ.","thanhVien":[{"ten":"Hải Phi","chucVu":"Thành viên","tuChuong":"@c2027","trangThai":"Đang thuộc tộc"}],"capNhatToi":"@c2027","nguon":["@c2027"]},{"id":"dieu-de-toc","name":"Điểu Đề tộc","cn":"","aliases":[],"type":"chung-toc","typeLabel":"Chủng tộc Ma giới","diaBan":"Huyết Nha thành","nhanVatChinh":["Ngưu Lực"],"blurb":"Điểu Đề tộc là tộc hệ của Ngưu Lực, một Ma tộc Hóa Thần kỳ có danh tiếng tại Huyết Nha thành.","detail":"Chương này chỉ xác nhận Ngưu Lực thuộc Điểu Đề tộc; cơ cấu, địa bàn chính và quy mô của tộc chưa được nêu rõ.","thanhVien":[{"ten":"Ngưu Lực","chucVu":"Thành viên","tuChuong":"@c2027","trangThai":"Đang thuộc tộc"}],"capNhatToi":"@c2027","nguon":["@c2027"]},{"id":"hoi-dau-gia-huyet-nha-thanh","name":"Hội đấu giá Huyết Nha thành","cn":"","aliases":[],"type":"to-chuc","typeLabel":"Hội đấu giá","diaBan":"Huyết Nha Thành","nhanVatChinh":["Việt Liên Thiên","Huyết Thủ Kinh Vân","Thiết Phá Hồn"],"quyMo":"Có tám vệ sĩ chấp pháp đạt Luyện Hư sơ kỳ hoặc trung kỳ","lanhDaoHienThoi":"Việt Liên Thiên chủ trì phiên đấu giá","trangThai":"Đang tổ chức đấu giá","blurb":"Tổ chức phụ trách phiên đấu giá lớn tại Huyết Nha Thành. Hội bố trí tám Ma tộc Luyện Hư làm vệ sĩ chấp pháp và mời trưởng lão Việt Liên Thiên chủ trì.","detail":"Hội đấu giá đưa ra nhiều ma khí, tài liệu và đan dược có giá trị cao, trong đó có Ám Huyết Ngũ Sắc linh và Thánh Chuyên của Khấp Linh thánh tổ. Đối với Thánh Chuyên, hội cam kết bồi thường gấp mười lần giá đấu nếu vật phẩm là giả.","thanhVien":[{"ten":"Việt Liên Thiên","chucVu":"Chủ trì","tuChuong":"@c2030","trangThai":"Đang đảm nhiệm"},{"ten":"Huyết Thủ Kinh Vân","chucVu":"Vệ sĩ chấp pháp","tuChuong":"@c2030","trangThai":"Đang làm nhiệm vụ"},{"ten":"Thiết Phá Hồn","chucVu":"Vệ sĩ chấp pháp","tuChuong":"@c2030","trangThai":"Đang làm nhiệm vụ"}],"capNhatToi":"@c2030","tabs":{"tienTrinh":[{"chuong":"@c2030","loai":"nhắc tới","importance":"normal","giaiDoan":"Tổ chức phiên đấu giá","trangThaiMoc":"Đang hoạt động","text":"Hội đấu giá Huyết Nha thành bố trí tám vệ sĩ Luyện Hư, bán nhiều vật phẩm quý và bảo chứng lai lịch Thánh Chuyên của Khấp Linh thánh tổ.","anchor":"Nếu có chút giả dối, hội đấu giá xin bồi thường gấp mười lần giá được đưa ra đấu giá"}]},"nguon":["@c2030"]},{"id":"hai-gia","name":"Hải gia","cn":"","aliases":[],"type":"gia-toc","typeLabel":"Luyện khí thế gia","diaBan":"Khô Tịch thành","nhanVatChinh":["Mỹ phụ họ Hải","Ma tộc phụ nhân Hải gia","Hai gã Ma tộc nam tử Hải gia"],"blurb":"Một luyện khí thế gia lớn tại Khô Tịch thành. Thành viên của gia tộc đã tranh mua chân linh di cốt và khẳng định vật này có công dụng lớn đối với Hải gia.","detail":"Hải gia có địa bàn tại Khô Tịch thành, cách xa Huyết Nha Thành. Mỹ phụ họ Hải dựa vào danh thế gia tộc để yêu cầu Hàn Lập nhường chân linh di cốt nhưng không thành công.","quyMo":"Một trong những luyện khí thế gia lớn của Ma giới.","thanhVien":[{"ten":"Mỹ phụ họ Hải","chucVu":"Thành viên gia tộc","tuChuong":"@c2032","trangThai":"gan-bo"},{"ten":"Ma tộc phụ nhân Hải gia","chucVu":"Người chủ trì hành động","tuChuong":"@c2034","trangThai":"đang hoạt động"},{"ten":"Hai gã Ma tộc nam tử Hải gia","chucVu":"Thuộc hạ","tuChuong":"@c2034","trangThai":"đang hoạt động"}],"trangThai":"Đang tìm cách lấy linh chi cốt","capNhatToi":"@c2032","nguon":["@c2032","@c2034"],"tabs":{"tienTrinh":[{"chuong":"@c2034","loai":"nhắc tới","importance":"normal","giaiDoan":"Mưu lấy linh chi cốt","trangThaiMoc":"Chuẩn bị huy động quan hệ","text":"Hải gia xác định linh chi cốt là tài liệu cần cho chí bảo và chuẩn bị nhờ Nam gia cùng Huyết Nha Thành chủ gây sức ép.","anchor":"Nam gia tựa hồ còn thiếu Hải gia chúng ta một cái nhân tình không nhỏ"}]}},{"id":"ma-ve-huyet-nha-thanh","name":"Ma vệ Huyết Nha Thành","cn":"","type":"quan-doi","typeLabel":"Lực lượng phòng vệ","diaBan":"Huyết Nha Thành","nhanVatChinh":["Thống lĩnh ma vệ Huyết Nha Thành","Đội Ma tộc vệ sĩ Huyết Nha Thành"],"blurb":"Lực lượng thi hành giới nghiêm và tuần tra ban đêm tại Huyết Nha Thành.","detail":"Một đội ma vệ đã phát hiện hai người dùng bí thuật ẩn nặc vượt thành. Sau khi chứng kiến thần thông huyết sắc của một người, thống lĩnh nhận định đối phương quá mạnh và cho phép cả hai rời đi.","lanhDaoHienThoi":"Thống lĩnh ma vệ Huyết Nha Thành","trangThai":"Đang tuần tra và duy trì giới nghiêm","thanhVien":[{"ten":"Thống lĩnh ma vệ Huyết Nha Thành","chucVu":"Thống lĩnh tuần tra","tuChuong":"@c2034","trangThai":"đang hoạt động"},{"ten":"Đội Ma tộc vệ sĩ Huyết Nha Thành","chucVu":"Đội tuần tra","tuChuong":"@c2034","trangThai":"đang hoạt động"}],"tabs":{"tienTrinh":[{"chuong":"@c2034","loai":"nhắc tới","importance":"normal","giaiDoan":"Hai cao thủ vượt thành","trangThaiMoc":"Từ bỏ truy bắt","text":"Ma vệ phát hiện hai người ẩn hình nhưng thống lĩnh quyết định không tiếp tục truy bắt vì kiêng kỵ thần thông của họ.","anchor":"hai người này thần thông quảng đại, không phải chúng ta có thể trêu chọc"}]},"capNhatToi":"@c2034","nguon":["@c2034"]},{"id":"loi-hai-that-sat","name":"Lôi Hải Thất Sát","cn":"","type":"to-chuc","typeLabel":"Thế lực","diaBan":"Lôi hải","nhanVatChinh":[],"blurb":"Một thế lực tại Lôi hải từng tranh đoạt nơi Khấp Linh thánh tổ tọa hóa.","detail":"Lôi Hải Thất Sát từng cùng Thiên Phòng Sơn cướp phá nơi Khấp Linh thánh tổ tọa hóa. Sau khi ba khối Thánh Chuyên bị Huyết Nha Thành chủ bí mật lấy đi, hai thế lực đã giao chiến với nhau vì tưởng đối phương chiếm được chúng.","quanHe":"Từng giao chiến với Thiên Phòng Sơn vì các khối Thánh Chuyên thất lạc.","trangThai":"Còn tồn tại","tabs":{"tienTrinh":[{"chuong":"@c2035","loai":"khai chiến","importance":"normal","giaiDoan":"Tranh chấp Thánh Chuyên","text":"Lôi Hải Thất Sát được tiết lộ từng giao chiến với Thiên Phòng Sơn sau khi ba khối Thánh Chuyên biến mất.","anchor":"làm cho Lôi hải Thất Sát cùng Thiên Phòng Sơn sống mái với nhau một hồi","trangThaiMoc":"Từng giao chiến với Thiên Phòng Sơn"}]},"capNhatToi":"@c2035","nguon":["@c2035"]},{"id":"thien-phong-son","name":"Thiên Phòng Sơn","cn":"","type":"to-chuc","typeLabel":"Thế lực","diaBan":"","nhanVatChinh":[],"blurb":"Thế lực từng tham gia cướp phá nơi Khấp Linh thánh tổ tọa hóa.","detail":"Thiên Phòng Sơn cùng Lôi Hải Thất Sát tranh đoạt di vật tại nơi Khấp Linh thánh tổ tọa hóa. Vì ba khối Thánh Chuyên bị Huyết Nha Thành chủ lấy trộm, hai thế lực sau đó đã giao chiến với nhau.","quanHe":"Từng giao chiến với Lôi Hải Thất Sát vì các khối Thánh Chuyên thất lạc.","trangThai":"Còn tồn tại","tabs":{"tienTrinh":[{"chuong":"@c2035","loai":"khai chiến","importance":"normal","giaiDoan":"Tranh chấp Thánh Chuyên","text":"Thiên Phòng Sơn từng tham gia cướp phá nơi Khấp Linh thánh tổ tọa hóa rồi giao chiến với Lôi Hải Thất Sát.","anchor":"Thất Sát cùng Thiên Phòng Sơn cướp sạch nơi Khấp Linh thánh tổ tọa hóa","trangThaiMoc":"Từng giao chiến với Lôi Hải Thất Sát"}]},"capNhatToi":"@c2035","nguon":["@c2035"]},{"id":"nhom-tu-si-nhan-toc-cua-lung-gia-lao-to","name":"Nhóm tu sĩ Nhân tộc của Lũng gia lão tổ","cn":"","aliases":[],"type":"lien-minh-lam-thoi","typeLabel":"Nhóm tu sĩ lâm thời","diaBan":"Huyết Nha Thành","nhanVatChinh":["Lũng gia lão tổ","Hàn Lập","Vũ y thiếu nữ","Phi phát nam tử Lâm gia","Huy trưởng lão"],"blurb":"Nhóm tu sĩ Nhân tộc do Lũng gia lão tổ triệu tập tại Huyết Nha Thành. Trước vòng vây Hấp Ma Nghĩ, họ quyết định phân tán phá vây rồi tái hội họp tại Huyễn Dạ Thành.","detail":"Nhóm thống nhất không tập trung hành động để tránh trở thành mục tiêu chính của Nghĩ hải. Mỗi người sẽ tự vượt qua vùng man hoang và đến khách sạn lớn nhất tại Huyễn Dạ Thành vào cùng ngày hai năm sau; quá hạn sẽ không tiếp tục chờ.","tonChi":"Hợp tác vượt qua Ma giới và ứng phó các hiểm họa trên hành trình.","lanhDaoHienThoi":"Lũng gia lão tổ","quyMo":"Nhóm tu sĩ nhỏ","trangThai":"Chuẩn bị phân tán phá vây","thanhVien":[{"ten":"Lũng gia lão tổ","chucVu":"Người triệu tập và đề xuất kế hoạch","tuChuong":"@c2039","trangThai":"Đang tham gia"},{"ten":"Hàn Lập","chucVu":"Thành viên","tuChuong":"@c2039","trangThai":"Đang tham gia"},{"ten":"Vũ y thiếu nữ","chucVu":"Thành viên","tuChuong":"@c2039","trangThai":"Đang tham gia"},{"ten":"Phi phát nam tử Lâm gia","chucVu":"Thành viên","tuChuong":"@c2039","trangThai":"Đang tham gia"},{"ten":"Huy trưởng lão","chucVu":"Thành viên","tuChuong":"@c2039","trangThai":"Đang tham gia"}],"tabs":{"tienTrinh":[{"chuong":"@c2039","loai":"liên minh","importance":"normal","giaiDoan":"Phân tán phá vây","text":"Nhóm quyết định chia nhau rời Huyết Nha Thành để phân tán áp lực của Hấp Ma Nghĩ hải, sau đó tái hội họp tại Huyễn Dạ Thành.","anchor":"để phân tán áp lực của Nghĩ hải quyết không thể tập trung hành động cùng nhau","trangThaiMoc":"Chuẩn bị phân tán"}]},"capNhatToi":"@c2039","nguon":["@c2039"]},{"id":"bach-gia","name":"Bạch gia","cn":"","aliases":["Huyễn Dạ Bạch gia"],"type":"gia-toc","typeLabel":"Gia tộc","diaBan":"Huyễn Dạ thành","nhanVatChinh":["Mỹ phụ váy xanh","Hai Ma tộc Luyện Hư còn lại","Hơn mười Ma tộc Hóa Thần"],"blurb":"Một gia tộc tại Huyễn Dạ thành, nổi danh nhờ sản xuất cỏ Thuyên. Một đoàn thành viên của gia tộc bị đàn dơi đỏ thẫm vây khốn gần rìa sơn mạc.","detail":"Đoàn người xuất hiện gồm ba Ma tộc Luyện Hư và hơn mười Ma tộc Hóa Thần. Khi lâm nguy, mỹ phụ váy xanh dùng danh nghĩa gia tộc cầu Hàn Lập tương trợ và hứa sẽ báo đáp.","tranPhai":"Cỏ Thuyên","thanhVien":[{"ten":"Mỹ phụ váy xanh","chucVu":"Thành viên Luyện Hư","tuChuong":"@c2043","trangThai":"đang hoạt động"},{"ten":"Hai Ma tộc Luyện Hư còn lại","chucVu":"Thành viên Luyện Hư","tuChuong":"@c2043","trangThai":"đang hoạt động"},{"ten":"Hơn mười Ma tộc Hóa Thần","chucVu":"Thành viên Hóa Thần","tuChuong":"@c2043","trangThai":"đang hoạt động"}],"trangThai":"Đang hoạt động","tabs":{"tienTrinh":[{"chuong":"@c2043","loai":"nhắc tới","importance":"normal","giaiDoan":"Đoàn thành viên bị vây","text":"Một đoàn gồm ba thành viên Luyện Hư và hơn mười thành viên Hóa Thần bị đàn dơi đỏ thẫm vây khốn trên Tử Quang Thụ.","anchor":"Chính là Bạch gia sản xuất ra cỏ Thuyên vang danh thiên hạ sao","trangThaiMoc":"Một đoàn thành viên đang bị vây khốn"}]},"capNhatToi":"@c2043","nguon":["@c2043"]},{"id":"tru-gia","name":"Trữ gia","cn":"","aliases":[],"type":"gia-toc","typeLabel":"Gia tộc Ma tộc","diaBan":"","nhanVatChinh":["Thanh niên áo bào trắng họ Trữ","Ba đồng bạn áo bào trắng của thanh niên họ Trữ"],"blurb":"Gia tộc Ma tộc sở hữu Dạ Yểm Sư làm linh thú hộ tộc.","detail":"Bốn đệ tử Trữ gia tranh giành thi thể Kim Hi Thử với Tây Bạch Minh tam huynh đệ. Họ chiếm ưu thế nhờ Dạ Yểm Sư nhưng phải rút lui khi các tu sĩ Luyện Hư của Bạch gia xuất hiện.","tranPhai":"Dạ Yểm Sư","quanHe":"Tranh chấp Kim Hi Thử với Bạch gia.","trangThai":"hoạt động","thanhVien":[{"ten":"Thanh niên áo bào trắng họ Trữ","chucVu":"Đệ tử","tuChuong":"@c2045","trangThai":"đang thuộc"},{"ten":"Ba đồng bạn áo bào trắng của thanh niên họ Trữ","chucVu":"Đệ tử","tuChuong":"@c2045","trangThai":"đang thuộc"}],"capNhatToi":"@c2045","tabs":{"tienTrinh":[{"chuong":"@c2045","loai":"nhắc tới","importance":"normal","giaiDoan":"Tranh chấp với Bạch gia","text":"Bốn đệ tử Trữ gia mang linh thú hộ tộc tranh Kim Hi Thử nhưng phải rút lui trước các tu sĩ Luyện Hư của Bạch gia.","anchor":"ngươi cũng dám đem linh thú hộ tộc mang ra"}]},"nguon":["@c2045"]},{"id":"tu-dai-gia-toc-huyen-da-thanh","name":"Tứ đại gia tộc Huyễn Dạ thành","cn":"","type":"gia-toc","typeLabel":"Liên nhóm gia tộc","diaBan":"Huyễn Dạ thành","nhanVatChinh":[],"blurb":"Bốn gia tộc lớn giữ địa vị chủ đạo tại Huyễn Dạ thành và cùng kiểm soát nguồn Bát Túc ma tích.","detail":"Tứ đại gia tộc không bán Bát Túc ma tích cho người ngoài dù được trả giá cao, bởi loài ma thú này có liên hệ với căn bản giúp họ duy trì địa vị tại Huyễn Dạ thành.","quyMo":"Bốn gia tộc lớn tại Huyễn Dạ thành","quanHe":"Cùng kiểm soát Bát Túc ma tích và duy trì địa vị tại Huyễn Dạ thành.","trangThai":"Đang nắm giữ Huyễn Dạ Thành","capNhatToi":"@c2046","tabs":{"tienTrinh":[{"chuong":"@c2046","loai":"nhắc tới","importance":"normal","giaiDoan":"Lộ quyền kiểm soát ma tích","text":"Tứ đại gia tộc được hé lộ là những thế lực kiểm soát Bát Túc ma tích và không bán loài ma thú này cho người ngoài.","anchor":"những con ma tích này trên phương diện nào đó cũng là căn bản để mấy đại gia tộc tại Huyễn Dạ thành độc vị nơi này","trangThaiMoc":"Giữ địa vị chủ đạo tại Huyễn Dạ thành"},{"chuong":"@c2067","loai":"nhắc tới","importance":"normal","giaiDoan":"Độc quyền ma tích","text":"Tứ đại gia tộc được xác nhận là những thế lực duy nhất tại Huyễn Dạ Thành sở hữu Bát Túc Ma Tích.","anchor":"Nhưng chỉ có tứ đại gia tộc mới có được Bát Túc Ma Tích","trangThaiMoc":"Độc quyền sở hữu Bát Túc Ma Tích"}]},"nguon":["@c2046","@c2067"]},{"id":"van-no-thap","name":"Vạn Nô Tháp","cn":"","aliases":[],"type":"thuong-nghiep","typeLabel":"Thế lực thương nghiệp","diaBan":"Huyễn Dạ thành","nhanVatChinh":["Chưởng quầy Vạn Nô Tháp","Các thị nữ Vạn Nô Tháp"],"blurb":"Cửa hiệu thương nghiệp tại Huyễn Dạ thành, chuyên buôn bán nô lệ, một số ma thú phổ thông và ma tinh khôi lỗi độc môn.","detail":"Vạn Nô Tháp hoạt động trong một cự tháp nhiều tầng, có thị nữ tiếp khách, chưởng quầy Hóa Thần, Truyền Tống trận, cấm chế, khôi lỗi canh gác và khu pháp trận giam nô lệ.","nguonGoc":"Không rõ","quyMo":"Cự tháp nhiều tầng với khu tiếp khách, phòng vệ và khu giam nô lệ.","lanhDaoHienThoi":"Không rõ","caoThuManhNhat":"Chưởng quầy Hóa Thần trong số nhân sự đã xuất hiện","tranPhai":"Ma tinh khôi lỗi","trangThai":"Đang hoạt động","thanhVien":[{"ten":"Chưởng quầy Vạn Nô Tháp","chucVu":"Chưởng quầy","tuChuong":"@c2047","trangThai":"Đang phục vụ"},{"ten":"Các thị nữ Vạn Nô Tháp","chucVu":"Thị nữ tiếp khách và dẫn đường","tuChuong":"@c2047","trangThai":"Đang phục vụ"}],"tabs":{"tienTrinh":[{"chuong":"@c2047","loai":"nhắc tới","importance":"normal","giaiDoan":"Hoạt động tại Huyễn Dạ thành","text":"Vạn Nô Tháp tiếp đón Hàn Lập, bán nhóm nô lệ Thổ Âm tộc cho khách Trữ gia và giới thiệu ma tinh khôi lỗi độc môn.","anchor":"bản tháp chuyên môn buôn bán nô lệ cùng một ít ma thú"}]},"capNhatToi":"@c2047","nguon":["@c2047"]},{"id":"thanh-linh-vien","name":"Thánh Linh viện","cn":"","type":"co-so-luu-tru","typeLabel":"Cơ sở lưu trú","diaBan":"Vách núi trong Huyễn Dạ thành","nhanVatChinh":["Lão niên ma tộc quản lý Thánh Linh viện"],"blurb":"Cơ sở cung cấp chỗ ở cao cấp cho cao giai ma tộc tại Huyễn Dạ thành.","detail":"Thánh Linh viện được xây dọc theo một vách núi cao hơn ngàn trượng, gồm nhiều lầu các và động phủ. Giá thuê tại đây cao hơn nơi khác ít nhất non nửa; Hàn Lập thuê một lầu các trong thời hạn một năm.","quyMo":"Gồm nhiều lầu các và động phủ dọc vách núi.","thanhVien":[{"ten":"Lão niên ma tộc quản lý Thánh Linh viện","chucVu":"Người quản lý","tuChuong":"@c2049","trangThai":"Đương nhiệm"}],"trangThai":"Hoạt động","capNhatToi":"@c2049","tabs":{"tienTrinh":[{"chuong":"@c2049","loai":"nhắc tới","importance":"normal","giaiDoan":"Hàn Lập thuê chỗ ở","text":"Thánh Linh viện cho Hàn Lập thuê một lầu các có cấm chế trong thời hạn một năm.","anchor":"Thánh Linh viện này, chính là nơi cung cấp chỗ ở cho các cao giai ma tộc"}]},"nguon":["@c2049"]},{"id":"ho-sat-ve","name":"Hổ Sát vệ","cn":"","type":"ve-doi","typeLabel":"Vệ đội tinh nhuệ","diaBan":"Thành trì Bạch gia, Huyễn Dạ thành","nhanVatChinh":["Bạch Vân Hinh"],"blurb":"Vệ đội tinh nhuệ do Bạch gia đặc biệt huấn luyện, chuyên hộ tống và bảo vệ cơ nghiệp của gia tộc.","detail":"Mỗi Hổ Sát vệ từng sống một mình tại vùng hoang vu hơn trăm năm và săn giết nhiều ma thú. Đội hình hộ tống Hàn Lập gồm mười sáu tu sĩ Hóa Thần kỳ mặc giáp đen, cưỡi cự lang song đầu.","nguonGoc":"Do Bạch gia đặc biệt huấn luyện.","quyMo":"Đội hình xuất hiện gồm mười sáu kỵ sĩ.","capBac":"Các thành viên xuất hiện có tu vi Hóa Thần kỳ.","quanHe":"Trực thuộc Bạch gia.","trangThai":"Đang hoạt động","thanhVien":[{"ten":"Mười sáu Hổ Sát vệ","chucVu":"Kỵ sĩ hộ tống","tuChuong":"@c2051","trangThai":"đang hoạt động"}],"capNhatToi":"@c2051","tabs":{"tienTrinh":[{"chuong":"@c2051","loai":"nhắc tới","importance":"normal","giaiDoan":"Hộ tống khách quý","text":"Mười sáu Hổ Sát vệ cưỡi cự lang song đầu hộ tống thú xa đưa Hàn Lập tới thành trì Bạch gia.","anchor":"Hổ Sát vệ này là đội quân tinh nhuệ do bạch gia chúng tôi huấn luyện đặc biệt"}]},"nguon":["@c2051"]},{"id":"thu-ton-dien","name":"Thú Tôn điện","cn":"","aliases":[],"type":"to-chuc","typeLabel":"Thế lực","diaBan":"Các thành thị quanh Huyễn Khiếu sa mạc","nhanVatChinh":["Trung niên đạo sĩ","Nam tử râu rậm","Vạn Thú Thánh Tổ","Thiên Khấp"],"blurb":"Một thế lực được Triệu gia bí mật thuê theo dõi và truy sát nhóm đã cướp Ma Tích.","detail":"Thú Tôn điện có những lão quái tu vi không dưới hai Ma tôn Triệu gia và giàu kinh nghiệm sinh tử chiến. Triệu gia dự định thuê họ theo dõi các thành thị quanh Huyễn Khiếu sa mạc trong thời hạn một trăm năm, chờ mục tiêu xuất hiện rồi tiến hành một lần truy sát.","quyMo":"Có nhiều lão quái cấp Ma tôn","quanHe":"Được Triệu gia bí mật thuê truy sát nhóm cướp Ma Tích","trangThai":"Đang hoạt động","capNhatToi":"@c2071","tabs":{"tienTrinh":[{"chuong":"@c2071","loai":"nhắc tới","importance":"normal","giaiDoan":"Nhận đề nghị truy sát","text":"Triệu gia quyết định liên hệ Thú Tôn điện, thuê thế lực này theo dõi vùng quanh Huyễn Khiếu sa mạc và phục kích nhóm cướp Ma Tích.","anchor":"Khi trở về ngươi hãy liên hệ một chút với người của Thú Tôn điện, mời bọn họ thay ta xuất thủ một lần."},{"chuong":"@c2076","loai":"nhắc tới","importance":"normal","giaiDoan":"Mời chào nhân thủ","text":"Thú Tôn Điện nhận thù lao để đối phó nhiều nhóm ngoại lai, đồng thời mời chào thêm người nhằm chuẩn bị một đại sự.","anchor":"Bổn điện đang mời chào một vài vị đạo hữu cùng chung chí hướng để chuẩn bị mưu đồ đại sự."},{"chuong":"@c2111","loai":"nhắc tới","importance":"normal","giaiDoan":"Được huy động truy bắt Bảo Hoa","trangThaiMoc":"Chuẩn bị giám sát các truyền tống trận","text":"Thiên Khấp ra lệnh báo cho phân đàn Thú Tôn Điện gần nhất để điều động nhân thủ truy tìm Bảo Hoa.","anchor":"Bây giờ ta sẽ cho người báo cho phân đàn của Thú Tôn Điện gần nhất"}]},"nguon":["@c2071","@c2076","@c2111"],"thanhVien":[{"ten":"Trung niên đạo sĩ","chucVu":"Ma Tôn thi hành nhiệm vụ","tuChuong":"@c2076","trangThai":"Đang hoạt động"},{"ten":"Nam tử râu rậm","chucVu":"Ma Tôn thi hành nhiệm vụ","tuChuong":"@c2076","trangThai":"Đang hoạt động"},{"ten":"Thiên Khấp","chucVu":"Người có quyền huy động phân đàn","tuChuong":"@c2111","trangThai":"Đang hoạt động"}]},{"id":"thanh-duc-toc","name":"Thanh Dực tộc","cn":"","type":"chung-toc","typeLabel":"Chủng tộc","diaBan":"Thiết Sa lĩnh","nhanVatChinh":[],"blurb":"Chủng tộc cư trú tại Thiết Sa lĩnh, có một số ít tộc nhân hạch tâm kế thừa huyết mạch Thanh Loan.","detail":"Tộc nhân được xác định mang Thanh Loan chân huyết sẽ có thân phận và địa vị tăng mạnh trong Thanh Dực tộc. Những người này được bảo vệ nghiêm mật do số lượng cực ít và có thể sở hữu một phần thần thông thiên phú của Thanh Loan.","nguonGoc":"Kế thừa huyết mạch Thanh Loan","quyMo":"Chỉ một số rất ít tộc nhân hạch tâm mang Thanh Loan chân huyết","tranPhai":"Thanh Loan chân huyết","trangThai":"đang tồn tại tại Thiết Sa lĩnh","tabs":{"tienTrinh":[{"chuong":"@c2072","loai":"nhắc tới","importance":"normal","giaiDoan":"Hé lộ truyền thừa Thanh Loan","text":"Thanh Dực tộc được hé lộ có một số rất ít tộc nhân hạch tâm kế thừa Thanh Loan chân huyết.","anchor":"chỉ có một số lượng rất ít nhân tài là có thể có cơ duyên như vậy"}]},"capNhatToi":"@c2072","nguon":["@c2072"]},{"id":"nhan-toc-va-cac-toc-lien-minh-chong-ma-toc","name":"Nhân tộc và các tộc liên minh chống Ma tộc","cn":"","type":"lien-minh","typeLabel":"Liên minh chiến sự","diaBan":"Linh giới","nhanVatChinh":[],"blurb":"Liên minh gồm Nhân tộc và một số tộc khác đang chống lại lực lượng Ma tộc xâm nhập Linh giới.","detail":"Liên minh đã giao chiến nhiều lần với Ma tộc trong vài chục năm. Dù có tu sĩ Đại Thừa tham chiến, cục diện chiến tranh vẫn ở thế giằng co.","trangThai":"Đang giao chiến trong thế giằng co","quanHe":"Đối địch với lực lượng Ma tộc xâm nhập Linh giới.","capNhatToi":"@c2076","tabs":{"tienTrinh":[{"chuong":"@c2076","loai":"khai chiến","importance":"normal","giaiDoan":"Chiến sự giằng co","text":"Nhân tộc liên thủ với một số tộc khác giao chiến nhiều lần với Ma tộc nhưng chưa bên nào giành thắng lợi quyết định.","anchor":"Nhân tộc liên thủ với vài tộc khác cùng Ma tộc đại chiến mấy lần"}]},"nguon":["@c2076"]},{"id":"ma-toc-xam-nhap-linh-gioi","name":"Ma tộc xâm nhập Linh giới","cn":"","type":"lien-minh","typeLabel":"Lực lượng chiến tranh","diaBan":"Linh giới","nhanVatChinh":[],"blurb":"Lực lượng gồm một số bộ phận của Ma giới tham gia cuộc xâm nhập Linh giới.","detail":"Lực lượng xâm nhập đã có Thánh tổ Ma tộc hàng lâm và giao chiến với tu sĩ Đại Thừa của các tộc. Dù vậy, chiến sự vẫn giằng co và nhiều thế lực khác tại Ma giới không quan tâm đến cuộc xâm lược.","quyMo":"Chỉ gồm một số bộ phận của Ma giới","trangThai":"Đang giao chiến trong thế giằng co","quanHe":"Đối địch với Nhân tộc và các tộc liên minh tại Linh giới.","capNhatToi":"@c2076","tabs":{"tienTrinh":[{"chuong":"@c2076","loai":"khai chiến","importance":"normal","giaiDoan":"Thánh tổ tham chiến","text":"Lực lượng Ma tộc đã có Thánh tổ hàng lâm Linh giới nhưng vẫn chưa phá vỡ được thế giằng co.","anchor":"hơn nữa còn có Ma tộc thánh tổ hàng lâm xuống Linh giới cùng với vài tu sỹ đại thừa các tộc khác ra tay"}]},"nguon":["@c2076"]},{"id":"tam-dai-thuy-to","name":"Tam Đại Thủy Tổ","cn":"","type":"nhom-dai-nang","typeLabel":"Nhóm Thủy Tổ Ma giới","diaBan":"Khổ Linh Đảo, lôi hải và khu vực Ma Nguyên Hải","nhanVatChinh":["Nữ tử trên đảo lôi hải","Hắc bào thanh niên","Trung niên kim bào"],"blurb":"Ba vị Thủy Tổ Ma giới canh giữ khu vực Khổ Linh Đảo và lôi hải. Mỗi người đều là tồn tại cấp Thánh Tổ đã tiến tới bước cuối trước khi độ kiếp phi thăng Chân Ma giới.","detail":"Tam Đại Thủy Tổ gồm nữ tử trên đảo lôi hải, hắc bào thanh niên tự xưng là Thủy Tổ và trung niên kim bào nằm trong quan tài dưới lòng đất. Khi đoàn Hàn Lập xông vào Khổ Linh Đảo, nữ tử biến mất để hành động, hắc bào thanh niên cưỡi tam thủ hắc giao bay về lôi hải, còn trung niên kim bào chưa có phản ứng.","nguonGoc":"Các Thủy Tổ lâu đời của Ma giới","tonChi":"Canh giữ khu vực Khổ Linh Đảo","lanhDaoHienThoi":"Không rõ","capBac":"Thủy Tổ","quyMo":"Ba thành viên","caoThuManhNhat":"Ba vị đều ở cấp Thủy Tổ","soCaoThu":"3","tranPhai":[],"quanHe":"Thuộc Ma tộc và đối địch những người xâm nhập từ Linh Giới","trangThai":"Đang canh giữ Khổ Linh Đảo","capNhatToi":"@c2084","thanhVien":[{"ten":"Nữ tử trên đảo lôi hải","chucVu":"Thủy Tổ","tuChuong":"@c2084","trangThai":"đang hoạt động"},{"ten":"Hắc bào thanh niên","chucVu":"Thủy Tổ","tuChuong":"@c2084","trangThai":"đang tới lôi hải"},{"ten":"Trung niên kim bào","chucVu":"Thủy Tổ","tuChuong":"@c2084","trangThai":"không rõ sống chết"}],"lanhDaoMoc":[],"tabs":{"tienTrinh":[{"chuong":"@c2084","loai":"khai chiến","importance":"normal","giaiDoan":"Phát hiện đoàn người xâm nhập","text":"Hai trong ba vị Thủy Tổ bắt đầu hành động sau khi phát hiện đoàn Hàn Lập xông vào Khổ Linh Đảo, trong khi vị còn lại vẫn bất động trong quan tài.","anchor":"Còn Thủy Tổ của Ma giới cũng là dạng tồn tại tu vi cấp Thánh Tổ, nhưng đã đến một bước cuối cùng sắp độ kiếp phi thăng Chân Ma giới"}]},"nguon":["@c2084"]},{"id":"ma-toc-song-giac-than-do","name":"Ma tộc song giác thân đỏ","cn":"","type":"chung-toc","typeLabel":"Chủng tộc Ma tộc","diaBan":"Sa mạc vô tận tại Ma giới","nhanVatChinh":["Ma tộc song giác phát lệnh"],"blurb":"Một nhóm Ma tộc thân đỏ, trên đầu mọc một cặp sừng, xuất hiện với hơn trăm cá thể tại sa mạc.","detail":"Các cá thể có hình dạng giống hệt nhau, không biểu cảm và mang khí tức lạnh lẽo như vật không có sinh mệnh. Chúng đồng loạt dùng lệnh bài màu đen phóng quang cầu vây công Bảo Hoa và Hắc Ngạc.","quyMo":"Hơn trăm cá thể còn lại tại chiến trường.","quanHe":"Đối địch với Bảo Hoa và Hắc Ngạc.","trangThai":"Đang vây công Bảo Hoa và Hắc Ngạc","thanhVien":[{"ten":"Ma tộc song giác phát lệnh","chucVu":"Cá thể phát lệnh","tuChuong":"@c2112","trangThai":"đang hoạt động"}],"tabs":{"tienTrinh":[{"chuong":"@c2112","loai":"khai chiến","importance":"normal","giaiDoan":"Vây công trong sa mạc","text":"Hơn trăm Ma tộc song giác thân đỏ đồng loạt dùng lệnh bài đen tấn công Bảo Hoa và Hắc Ngạc.","anchor":"có khoảng hơn trăm tên cao giai ma tộc trên đầu mọc thêm một cặp sừng","trangThaiMoc":"Đang vây công"}]},"capNhatToi":"@c2112","nguon":["@c2112"]},{"id":"thien-hai-cac","name":"Thiên Hải các","cn":"","type":"thuong-hoi","typeLabel":"Cửa hàng","diaBan":"Lam Bộc thành","nhanVatChinh":[],"blurb":"Cửa hàng lớn tại Lam Bộc thành, được giới thiệu là một cơ sở kinh doanh hiện đại hàng đầu bản thành.","detail":"Thiên Hải các có bề ngoài cổ xưa và không nổi bật, nhưng bên trong sử dụng không gian ma khí để mở một tiểu Tu Di không gian với đại sảnh rộng vài mẫu.","quyMo":"Một trong những cửa hàng lớn nhất Lam Bộc thành","trangThai":"Đang hoạt động","capNhatToi":"@c2116","tabs":{"tienTrinh":[{"chuong":"@c2116","loai":"nhắc tới","importance":"normal","giaiDoan":"Lộ quy mô nội bộ","text":"Thiên Hải các được giới thiệu là cửa hàng hiện đại hàng đầu Lam Bộc thành và để lộ tiểu Tu Di không gian rộng vài mẫu bên trong.","anchor":"Thiên Hải các này bề ngoài nhìn như không chút thu hút nhưng tuyệt đối là cửa hàng niện đại đệ nhất bổn thành."}]},"nguon":["@c2116"]},{"id":"thai-hien-cac","name":"Thải Hiên Các","cn":"","aliases":[],"type":"thuong-nghiep","typeLabel":"Thế lực thương nghiệp","diaBan":"Lam Bộc thành","nhanVatChinh":["Hiếu Nhan"],"blurb":"Cửa hàng lớn tại Lam Bộc thành, nổi bật về độ đa dạng hàng hóa. Nơi này có bảo khố tích trữ Dị Ma Kim và phải tuân thủ quy định của thành chủ khi bán Huyết Nha Mễ.","detail":"Thải Hiên Các kinh doanh nhiều loại hàng hóa và phân chia khu bán hàng thông thường với khu bảo vật có giá trị cao. Tầng hai có phòng khách quý dành cho tu sĩ cấp cao, còn đại trưởng quầy Hiếu Nhan phụ trách những giao dịch quan trọng.","quyMo":"Cửa hàng lớn tại Lam Bộc thành","thanhVien":[{"ten":"Hiếu Nhan","chucVu":"Đại trưởng quầy","tuChuong":"@c2117","trangThai":"Đương nhiệm"}],"trangThai":"Đang hoạt động","capNhatToi":"@c2117","tabs":{"tienTrinh":[{"chuong":"@c2117","loai":"nhắc tới","importance":"normal","giaiDoan":"Giao dịch Dị Ma Kim","text":"Thải Hiên Các bán toàn bộ hơn trăm khối Dị Ma Kim đang có cho Hàn Lập và giải thích giới hạn giao dịch Huyết Nha Mễ.","anchor":"Nhưng nếu nói về độ đa dạng của hàng hóa thì nơi đây tuyệt đối là số một."}]},"nguon":["@c2117"]},{"id":"phu-thanh-chu-lam-boc-thanh","name":"Phủ thành chủ Lam Bộc thành","cn":"","aliases":[],"type":"quan-ly","typeLabel":"Thế lực quản lý","diaBan":"Lam Bộc thành","nhanVatChinh":[],"blurb":"Cơ quan quản lý Lam Bộc thành, trực tiếp khống chế việc mua bán Huyết Nha Mễ. Phủ thành chủ quy định lượng hàng được bán mỗi năm và kiểm tra danh sách giao dịch của các cửa hàng.","detail":"Phủ thành chủ nắm quyền kiểm soát Huyết Nha Mễ, khiến các cửa hàng không thể tùy ý bán số lượng lớn. Mỗi năm, các cửa hàng phải lập danh sách lượng Huyết Nha Mễ đã bán để chịu kiểm tra nghiêm ngặt.","tonChi":"Quản lý hoạt động trong Lam Bộc thành và kiểm soát tài nguyên đặc sản","trangThai":"Đang quản lý Lam Bộc thành","capNhatToi":"@c2117","tabs":{"tienTrinh":[{"chuong":"@c2117","loai":"nhắc tới","importance":"normal","giaiDoan":"Kiểm soát Huyết Nha Mễ","text":"Phủ thành chủ giới hạn lượng Huyết Nha Mễ được bán hằng năm và kiểm tra danh sách giao dịch do các cửa hàng lập.","anchor":"Hơn nữa còn phải dựa theo quy định của thành chủ là hàng năm phải lập danh sách Huyết Nha Mễ đã bán ra và bị nghiêm ngặt kiểm tra."}]},"nguon":["@c2117"]},{"id":"nhom-khai-mo-cua-vo-uu","name":"Nhóm khai mỏ của Vô Ưu","cn":"","type":"nhom-ma-toc","typeLabel":"Nhóm Ma tộc","diaBan":"Lam Bộc thành","nhanVatChinh":["Vô Ưu","Tam đệ của Vô Ưu","Thiết Hổ","Nữ tử Ma tộc thanh tú"],"blurb":"Nhóm Ma tộc do Vô Ưu cầm đầu, bí mật khai thác một mỏ quặng tại Lam Bộc thành.","detail":"Nhóm đã tự ý khai thác nhiều khoáng thạch quý hiếm, giết những người biết nội tình và phong kín mỏ. Sau khi chốt bán Dị Ma kim cho Hàn Lập, họ dự định đổi toàn bộ hàng hóa thành tài phú rồi lập tức rời Lam Bộc thành.","nguonGoc":"Nhóm Ma tộc cùng tham gia khai thác mỏ trái phép tại Lam Bộc thành.","lanhDaoHienThoi":"Vô Ưu","quyMo":"Gồm Vô Ưu, Tam đệ, Thiết Hổ và một nhóm nam nữ Ma tộc.","quanHe":"Có nguy cơ bị các thế lực liên quan đến quyền lợi khai mỏ tại Lam Bộc thành truy sát.","trangThai":"Chuẩn bị bán tháo khoáng thạch và rời Lam Bộc thành","thanhVien":[{"ten":"Vô Ưu","chucVu":"Thủ lĩnh","tuChuong":"@c2118","trangThai":"Đang lãnh đạo"},{"ten":"Tam đệ của Vô Ưu","chucVu":"Thành viên","tuChuong":"@c2118","trangThai":"Đang hoạt động"},{"ten":"Thiết Hổ","chucVu":"Thuộc hạ phụ trách diệt khẩu và phong mỏ","tuChuong":"@c2118","trangThai":"Đang hoạt động"},{"ten":"Nữ tử Ma tộc thanh tú","chucVu":"Thuộc hạ","tuChuong":"@c2118","trangThai":"Đang hoạt động"}],"lanhDaoMoc":[{"ten":"Vô Ưu","tuChuong":"@c2118","denChuong":""}],"capNhatToi":"@c2118","nguon":["@c2118"]},{"id":"quang-nguyen-trai","name":"Quảng Nguyên Trai","cn":"","type":"to-chuc","typeLabel":"Cơ sở bí ẩn","diaBan":"Khu rừng ngoài cửa đông Lam Bộc thành","nhanVatChinh":["Tiểu thư Quảng Nguyên Trai","Chu Di","Hi Nhi","Lão giả áo tro mặt đỏ","Lam Dĩnh"],"blurb":"Một cơ sở bí ẩn nằm trong khu rừng ngoài Lam Bộc thành, nổi tiếng có khả năng giải quyết nhiều việc tại khu vực Lam Bộc hồ.","detail":"Quảng Nguyên Trai vận hành hệ thống sàng lọc khách từ ngoài rừng đến bên trong lầu các năm tầng. Tầng một có Tứ Tượng Trận cùng một sát trận bí mật, còn người phụng sự tại đây gồm lão giả áo tro, Hi Nhi và Chu Di.","lanhDaoHienThoi":"Tiểu thư Quảng Nguyên Trai","tranPhai":"Hệ thống cấm chế nhiều lớp trong lầu các","thanhVien":[{"ten":"Tiểu thư Quảng Nguyên Trai","chucVu":"Chủ nhân","tuChuong":"@c2119","trangThai":"Đang hoạt động"},{"ten":"Chu Di","chucVu":"Cao giai hộ pháp","tuChuong":"@c2119","trangThai":"Đang miễn cưỡng chống đỡ thế lực"},{"ten":"Hi Nhi","chucVu":"Nha hoàn tiếp đón","tuChuong":"@c2119","trangThai":"Đang hoạt động"},{"ten":"Lão giả áo tro mặt đỏ","chucVu":"Người sàng lọc khách","tuChuong":"@c2119","trangThai":"Đang hoạt động"},{"ten":"Lam Dĩnh","chucVu":"Trai chủ","tuChuong":"@c2123","trangThai":"Đương nhiệm"}],"trangThai":"Suy yếu","capNhatToi":"@c2119","tabs":{"tienTrinh":[{"chuong":"@c2119","loai":"nhắc tới","importance":"normal","giaiDoan":"Tiếp đón Hàn Lập","text":"Quảng Nguyên Trai sàng lọc Hàn Lập, để hắn vượt qua hệ thống cấm chế tầng một rồi giao cho Chu Di dẫn đi gặp tiểu thư.","anchor":"vị chủ nhân của Quảng Nguyên trai này ở khu vực Lam Bộc hồ không có gì là không thể làm được"},{"chuong":"@c2123","loai":"suy","importance":"normal","giaiDoan":"Nội bộ suy yếu","text":"Sau khi cựu trai chủ và nhiều cao giai hộ pháp ngã xuống, Quảng Nguyên Trai chỉ còn danh tiếng bên ngoài và phải dựa vào Lam Dĩnh cùng Chu Di để duy trì.","anchor":"Quảng Nguyên Trai cũng chỉ còn mỗi vẻ bề ngoài, thực ra bên trong vô cùng suy yếu","trangThaiMoc":"Suy yếu"}]},"nguon":["@c2119","@c2123"]},{"id":"the-luc-thanh-chu-lam-boc-ho","name":"Thế lực thành chủ Lam Bộc hồ","cn":"","type":"chinh-quyen","typeLabel":"Thế lực địa phương","diaBan":"Lam Bộc hồ","nhanVatChinh":["Thành chủ Lam Bộc hồ","Lam Bộc Thánh tổ"],"blurb":"Thế lực mạnh nhất tại khu vực Lam Bộc hồ, nắm giữ mạch khoáng có cực phẩm khoáng thạch.","detail":"Thế lực này do thành chủ Lam Bộc hồ đứng đầu và có Lam Bộc Thánh tổ làm chỗ dựa. Nhóm Vô Ưu vô tình đào lệch từ mỏ trung phẩm sang cực phẩm khoáng mạch thuộc quyền kiểm soát của họ.","lanhDaoHienThoi":"Thành chủ Lam Bộc hồ","caoThuManhNhat":"Lam Bộc Thánh tổ","quanHe":"Có Lam Bộc Thánh tổ chống lưng.","thanhVien":[{"ten":"Thành chủ Lam Bộc hồ","chucVu":"Lãnh đạo","tuChuong":"@c2119","trangThai":"Đang tại vị"},{"ten":"Lam Bộc Thánh tổ","chucVu":"Chỗ dựa","tuChuong":"@c2119","trangThai":"Đang liên hệ"}],"trangThai":"Đang hoạt động","capNhatToi":"@c2119","tabs":{"tienTrinh":[{"chuong":"@c2119","loai":"nhắc tới","importance":"normal","giaiDoan":"Mạch khoáng bị xâm nhập","text":"Nhóm Vô Ưu vô tình đào đường hầm sang cực phẩm khoáng mạch thuộc thế lực thành chủ Lam Bộc hồ.","anchor":"thế lực của thành chủ là lớn nhất tại Lam Bộc hồ"}]},"nguon":["@c2119"]},{"id":"tam-dai-thuy-to-ma-gioi","name":"Tam đại Thủy Tổ Ma giới","cn":"","type":"lien-minh","typeLabel":"Nhóm lãnh đạo tối cao","diaBan":"Ma giới","nhanVatChinh":[],"blurb":"Tam đại Thủy Tổ là ba vị đứng đầu Ma giới, dồn phần lớn tâm sức ứng phó hiểm họa Minh Trùng. Họ vừa củng cố phong ấn đang suy yếu, vừa tiêu diệt những Minh Trùng bậc thấp thoát ra ngoài.","detail":"Trước nguy cơ do Minh Trùng gây ra, Tam đại Thủy Tổ Ma giới trực tiếp tập trung lực lượng để củng cố phong ấn và ngăn chặn các Minh Trùng bậc thấp đã thoát ra. Những hành động này cho thấy họ giữ vai trò chủ chốt trong việc bảo vệ Ma giới trước đại họa. @c2125","tonChi":"Duy trì phong ấn và bảo toàn Ma giới trước Minh Trùng Mẫu.","quyMo":"Ba vị Thủy Tổ cùng các lực lượng Ma giới phụ thuộc.","quanHe":"Phối hợp với những Thánh Tổ khác của Ma giới để ứng phó đại kiếp.","trangThai":"Đang đối phó Minh Trùng Mẫu","capNhatToi":"@c2125","dinhDanh":"goc","tabs":{"tienTrinh":[{"chuong":"@c2125","loai":"khai chiến","importance":"major","giaiDoan":"Ứng phó đại kiếp Minh Trùng","text":"Tam đại Thủy Tổ Ma giới dồn phần lớn tâm sức củng cố phong ấn và tiêu diệt những Minh Trùng bậc thấp thoát ra ngoài.","anchor":"Ba đại Thủy Tổ và những Thánh Tổ khác ở Ma giới hầu như đều đặt hơn phân nửa tâm tư vào chuyện này","trangThaiMoc":"Đang cố trì hoãn phong ấn sụp đổ"}]},"nguon":["@c2125"],"dacDiem":"Ba vị Thủy Tổ đứng đầu Ma giới, là lực lượng chủ chốt đối phó hiểm họa Minh Trùng.","congNang":["Củng cố phong ấn đang suy yếu để kiềm chế hiểm họa Minh Trùng. @c2125","Tiêu diệt những Minh Trùng bậc thấp thoát ra ngoài. @c2125"]},{"id":"the-luc-cua-tu-linh-tai-lam-boc-ho","name":"Thế lực của Tử Linh tại Lam Bộc hồ","cn":"","type":"khac","typeLabel":"Thế lực cá nhân","diaBan":"Lam Bộc hồ","nhanVatChinh":["Tử Linh Tiên Tử"],"blurb":"Lực lượng do Tử Linh điều động tại khu vực Lam Bộc hồ nhờ thân phận đệ tử của Lục Cực.","detail":"Thế lực này có khả năng nhanh chóng điều tra một tu sĩ Luyện Hư kỳ cùng hoạt động khai thác trộm và chuyển kết quả rõ ràng tới Hàn Lập trong chưa đầy một ngày.","nguonGoc":"Hình thành từ địa vị đệ tử Lục Cực của Tử Linh.","lanhDaoHienThoi":"Tử Linh Tiên Tử","quyMo":"Không nhỏ tại Lam Bộc hồ","thanhVien":[{"ten":"Tử Linh Tiên Tử","chucVu":"Người điều động","tuChuong":"@c2127","trangThai":"Đang lãnh đạo"},{"ten":"Hắc giáp Ma tộc đưa tin","chucVu":"Người đưa tin","tuChuong":"@c2127","trangThai":"Đang phục vụ"}],"trangThai":"Đang hoạt động","capNhatToi":"@c2127","tabs":{"tienTrinh":[{"chuong":"@c2127","loai":"nhắc tới","importance":"normal","giaiDoan":"Điều tra vụ khai thác trộm","text":"Thế lực của Tử Linh điều tra Vô Ưu và vụ khai thác trộm rồi chuyển kết quả cho Hàn Lập.","anchor":"thế lực của Tử Linh ở Lam Bộc hồ vẫn là không nhỏ","trangThaiMoc":"Đang hoạt động"}]},"nguon":["@c2127"]},{"id":"thu-ha-cu-bi-mat-cua-bao-hoa","name":"Thủ hạ cũ bí mật của Bảo Hoa","cn":"","type":"nhom-thuoc-ha","typeLabel":"Nhóm thuộc hạ","diaBan":"Ma giới","nhanVatChinh":["Bảo Hoa","Bóng người trong hào quang màu vàng"],"blurb":"Những thuộc hạ cũ được Bảo Hoa bí mật giữ lại trong Ma tộc.","detail":"Bóng người trong hào quang vàng là một thành viên từng được Bảo Hoa cứu giúp và thu nhận. Người này công khai tỏ thái độ thù địch với nàng, nhưng thực tế vẫn trung thành và giúp nàng che giấu tung tích trước Lam Bộc cùng Lục Cực.","tonChi":"Bí mật trợ giúp và bảo vệ Bảo Hoa.","thanhVien":[{"ten":"Bóng người trong hào quang màu vàng","chucVu":"Thuộc hạ cũ","tuChuong":"@c2139","trangThai":"đang hoạt động"}],"trangThai":"bí mật hoạt động","tabs":{"tienTrinh":[{"chuong":"@c2139","loai":"nhắc tới","importance":"normal","giaiDoan":"Che giấu Bảo Hoa","text":"Một thuộc hạ cũ bí mật đưa Bảo Hoa tới nơi ẩn náu để tránh cuộc truy sát.","anchor":"ngoài ra còn là thủ hạ cũ được Bảo Hoa bí mật dấu lại"}]},"capNhatToi":"@c2139","nguon":["@c2139"]},{"id":"cac-thanh-tri-xung-quanh-khu-truy-tung","name":"Các thành trì xung quanh khu truy tung","cn":"","type":"lien-minh-dia-phuong","typeLabel":"Nhóm thành trì","diaBan":"Khu vực quanh nơi Bảo Hoa biến mất tại Ma giới","nhanVatChinh":["Lam Bộc Thánh Tổ"],"blurb":"Các thành trì lân cận nằm trong tay những người có quan hệ với Lam Bộc Thánh Tổ.","detail":"Lam Bộc có thể huy động những thành trì này đóng các truyền tống trận nhằm phong tỏa đường thoát của Bảo Hoa.","quanHe":"Có quan hệ với Lam Bộc Thánh Tổ và có thể tiếp nhận lệnh phong tỏa.","trangThai":"tham gia phong tỏa","tabs":{"tienTrinh":[{"chuong":"@c2139","loai":"liên minh","importance":"normal","giaiDoan":"Phong tỏa truyền tống trận","text":"Các thành trì lân cận được huy động đóng truyền tống trận để thu hẹp đường thoát của Bảo Hoa.","anchor":"Các thành trì xung quanh đây nằm trong tay những người có quan hệ với ta"}]},"capNhatToi":"@c2139","nguon":["@c2139"]},{"id":"bo-lac-moc-toc-duoc-han-lap-cuu","name":"Bộ lạc Mộc tộc được Hàn Lập cứu","cn":"","type":"bo-lac","typeLabel":"Bộ lạc","diaBan":"Vùng Ma tộc chiếm đóng tại lãnh địa Mộc tộc","nhanVatChinh":["Trưởng lão bộ lạc Mộc tộc"],"blurb":"Bộ lạc Mộc tộc hơn vạn người mắc kẹt trong vùng bị Ma tộc chiếm đóng và được Hàn Lập cứu khỏi một toán quân truy sát.","detail":"Bộ lạc có hơn vạn người nhưng chỉ khoảng hai ba nghìn người có khả năng chiến đấu, còn phụ nữ, trẻ em và người già chiếm khoảng hai phần ba. Họ từng tách khỏi một bộ lạc lớn sau khi bị phát hiện, rồi tiếp tục bị hơn một nghìn Ma tộc bao vây trước khi Hàn Lập ra tay cứu.","lanhDaoHienThoi":"Trưởng lão bộ lạc Mộc tộc","quyMo":"Hơn vạn người","trangThai":"Đang lẩn trốn trong vùng bị chiếm đóng","thanhVien":[{"ten":"Trưởng lão bộ lạc Mộc tộc","chucVu":"Trưởng lão đứng đầu","tuChuong":"@c2143","trangThai":"đang tại vị"}],"tabs":{"tienTrinh":[{"chuong":"@c2143","loai":"nhắc tới","importance":"normal","giaiDoan":"Được giải cứu","text":"Bộ lạc hơn vạn người được Hàn Lập cứu khỏi hơn một nghìn Ma tộc nhưng chưa thể rút ngay về vùng do liên quân bảo vệ.","anchor":"Cái bộ lạc Mộc tộc này có đến hơn vạn người","trangThaiMoc":"Được cứu khỏi vòng vây"}]},"capNhatToi":"@c2143","nguon":["@c2143"]},{"id":"lien-quan","name":"Liên quân","cn":"","type":"lien-minh","typeLabel":"Liên quân","diaBan":"Đại doanh liên quân","nhanVatChinh":["Ngao Khiếu lão tổ","Hàn Lập","Giải Đạo Nhân"],"blurb":"Lực lượng liên quân có đại doanh tại Mộc Miên Thành, là nơi đoàn Ngao Khiếu trở về sau chuyến đi trong khu vực Ma tộc chiếm đóng.","detail":"Ngao Khiếu quyết định đưa Hàn Lập và Giải Đạo Nhân trở về đại doanh liên quân sau khi nhận định chuyến đi đã hoàn thành và khu vực hiện tại không thể ở lâu.","trangThai":"Đang hoạt động","thanhVien":[{"ten":"Ngao Khiếu lão tổ","chucVu":"Không nêu","tuChuong":"@c2147","trangThai":"Đang hoạt động"}],"capNhatToi":"@c2147","tabs":{"tienTrinh":[{"chuong":"@c2147","loai":"nhắc tới","importance":"bridge","giaiDoan":"Trở về đại doanh","text":"Ngao Khiếu đưa Hàn Lập và Giải Đạo Nhân trở về đại doanh của liên quân.","anchor":"theo lão phu trở về đại doanh của liên quân đi"}]},"nguon":["@c2147"]},{"id":"luc-luong-phong-thu-mat-tran-moc-toc","name":"Lực lượng phòng thủ mắt trận Mộc tộc","cn":"","type":"lien-quan-quan-su","typeLabel":"Lực lượng phòng thủ","diaBan":"Mắt trận trong dãy núi Mộc tộc","nhanVatChinh":["Hàn Lập","Thảo Tật","Phỉ Tiểu Tịch","Giải Đạo Nhân"],"blurb":"Lực lượng bảo vệ mắt trận gồm các tu sĩ chủ chốt, hơn mười vệ sĩ Luyện Hư và hơn trăm người Mộc tộc hỗ trợ trận pháp.","detail":"Hàn Lập chia lực lượng thành hai bộ phận: Thảo Tật cùng hơn trăm người Mộc tộc ở lại vận hành cấm chế, còn Hàn Lập, Giải Đạo Nhân, Phỉ Tiểu Tịch và hơn mười vệ sĩ Luyện Hư xuất kích ngăn nhóm Ma tộc.","quyMo":"Hơn một trăm người","quanHe":"Đối địch với nhóm bảy Ma tộc xâm nhập dãy núi.","trangThai":"đang nghênh chiến","thanhVien":[{"ten":"Hàn Lập","chucVu":"Người phân công nghênh chiến","tuChuong":"@c2159","trangThai":"đang xuất kích"},{"ten":"Thảo Tật","chucVu":"Người vận hành cấm chế","tuChuong":"@c2159","trangThai":"đang trấn giữ"},{"ten":"Phỉ Tiểu Tịch","chucVu":"Người nghênh chiến","tuChuong":"@c2159","trangThai":"đang xuất kích"},{"ten":"Giải Đạo Nhân","chucVu":"Người nghênh chiến","tuChuong":"@c2159","trangThai":"đang xuất kích"},{"ten":"Hơn mười vệ sĩ Luyện Hư","chucVu":"Vệ sĩ","tuChuong":"@c2159","trangThai":"đang xuất kích"},{"ten":"Hơn trăm Mộc tộc hỗ trợ trận pháp","chucVu":"Hỗ trợ vận hành cấm chế","tuChuong":"@c2159","trangThai":"đang trấn giữ"}],"capNhatToi":"@c2159","tabs":{"tienTrinh":[{"chuong":"@c2159","loai":"khai chiến","importance":"normal","giaiDoan":"Phân công nghênh chiến","text":"Lực lượng phòng thủ chia thành nhóm ở lại vận hành cấm chế và nhóm xuất kích ngăn bảy Ma tộc.","anchor":"Bốn phía xung quanh tòa pháp trận còn có thêm hơn trăm tên Mộc tộc.","trangThaiMoc":"đang nghênh chiến"}]},"nguon":["@c2159"]},{"id":"nhom-bay-ma-toc-xam-nhap-day-nui","name":"Nhóm bảy Ma tộc xâm nhập dãy núi","cn":"","type":"doi-xam-nhap","typeLabel":"Nhóm xâm nhập","diaBan":"Dãy núi Mộc tộc","nhanVatChinh":["Ma Tôn mặt mũi dữ tợn","Hai Ma Tôn còn lại","Bốn Ma tộc Luyện Hư tương tự nhau"],"blurb":"Đội xâm nhập gồm ba Ma Tôn và bốn Ma tộc Luyện Hư Hậu Kỳ đại thành, đang phá cấm chế để tiến về trung tâm dãy núi.","detail":"Nhóm dùng gương đồng cùng các ma khí để vượt qua cấm chế Mộc tộc. Khi Điên Đảo Hoán Hình Ngũ Nhạc phát động, đội hình bị chia cắt và Ma Tôn cầm gương trở thành người duy nhất còn lại tại vị trí ban đầu.","quyMo":"Bảy người","caoThuManhNhat":"Ba Ma Tôn cảnh giới Hợp Thể","soCaoThu":"Ba Ma Tôn và bốn tu sĩ Luyện Hư Hậu Kỳ đại thành","quanHe":"Đối địch với lực lượng phòng thủ mắt trận Mộc tộc.","trangThai":"đã bị chia cắt","thanhVien":[{"ten":"Ma Tôn mặt mũi dữ tợn","chucVu":"Ma Tôn cầm gương","tuChuong":"@c2159","trangThai":"bị cô lập"},{"ten":"Hai Ma Tôn còn lại","chucVu":"Ma Tôn","tuChuong":"@c2159","trangThai":"bị chuyển khỏi vị trí ban đầu"},{"ten":"Bốn Ma tộc Luyện Hư tương tự nhau","chucVu":"Thành viên phối hợp","tuChuong":"@c2159","trangThai":"bị chuyển khỏi vị trí ban đầu"}],"capNhatToi":"@c2159","tabs":{"tienTrinh":[{"chuong":"@c2159","loai":"khai chiến","importance":"normal","giaiDoan":"Xâm nhập và bị chia cắt","text":"Nhóm bảy Ma tộc tiến qua các cấm chế hướng tới trung tâm dãy núi nhưng bị Điên Đảo Hoán Hình Ngũ Nhạc chia tách.","anchor":"Nơi đó có bảy tên Ma tộc đang lơ lửng trong không trung.","trangThaiMoc":"đã bị chia cắt"}]},"nguon":["@c2159"]},{"id":"hoi-dong-truong-lao-moc-toc","name":"Hội đồng trưởng lão Mộc tộc","cn":"","type":"co-cau-lanh-dao","typeLabel":"Cơ cấu lãnh đạo","diaBan":"Lãnh địa Mộc tộc","nhanVatChinh":["Đại trưởng lão lâm thời của Mộc tộc","Các trưởng lão Mộc tộc tại đài cao"],"blurb":"Hội đồng trưởng lão là cơ cấu lãnh đạo của Mộc tộc trong thời kỳ chiến tranh với Ma tộc. Sau khi Thánh thụ và đại trưởng lão đương nhiệm đều mất, hội đồng quyết định rút phần lớn đại quân, thông báo cho các tộc khác và tự bạo Mộc Giới Tuyệt Trận để bảo toàn tộc đàn.","detail":"Trước tổn thất của Thánh thụ và đại trưởng lão đương nhiệm, Hội đồng trưởng lão chuyển mục tiêu từ duy trì địa vị độc lập sang cứu hàng trăm triệu tộc nhân. Hội đồng phong tỏa tin tức, thông báo tình hình cho các tu sĩ cao cấp thuộc những tộc khác, rút phần lớn đại quân và chuẩn bị kích phát mắt trận thứ hai nhằm phá hủy toàn bộ Mộc Giới Tuyệt Trận. @c2170","tonChi":"Lãnh đạo và bảo toàn Mộc tộc","lanhDaoHienThoi":"Đại trưởng lão lâm thời của Mộc tộc","capBac":"Cơ cấu lãnh đạo tối cao của Mộc tộc","quanHe":"Lãnh đạo Mộc tộc và phối hợp với các lực lượng liên quân.","trangThai":"Đang tổ chức rút lui và bảo toàn tộc đàn","thanhVien":[{"ten":"Đại trưởng lão lâm thời của Mộc tộc","chucVu":"Lãnh đạo lâm thời","tuChuong":"@c2170","trangThai":"Đang lãnh đạo"},{"ten":"Các trưởng lão Mộc tộc tại đài cao","chucVu":"Trưởng lão","tuChuong":"@c2170","trangThai":"Đang hoạt động"}],"lanhDaoMoc":[{"ten":"Đại trưởng lão lâm thời của Mộc tộc","tuChuong":"@c2170","denChuong":""}],"capNhatToi":"@c2170","tabs":{"tienTrinh":[{"chuong":"@c2170","loai":"suy","importance":"major","giaiDoan":"Quyết định rút lui","trangThaiMoc":"Chuyển sang bảo toàn tộc đàn","text":"Hội đồng trưởng lão quyết định rút phần lớn đại quân, thông báo cho các tộc khác và tự bạo Mộc Giới Tuyệt Trận để sát thương quân Ma.","anchor":"hội đồng trưởng lão của Mộc tộc cũng đã đưa ra quyết định"}]},"nguon":["@c2170"],"uyLuc":"Có quyền quyết định rút phần lớn đại quân và tự bạo toàn bộ Mộc Giới Tuyệt Trận. @c2170","dacDiem":"Cơ cấu lãnh đạo Mộc tộc đặt việc bảo toàn hàng trăm triệu tộc nhân lên trên mục tiêu duy trì địa vị độc lập.","congNang":["Điều động và rút phần lớn đại quân Mộc tộc. @c2170","Phong tỏa tin tức và thông báo tình hình cho các tu sĩ cao cấp của những tộc khác. @c2170","Quyết định chuẩn bị kích phát mắt trận thứ hai để tự bạo, phá hủy toàn bộ Mộc Giới Tuyệt Trận. @c2170"]}]};
